let isHydratingFromServer=false;
const tableRefreshTimers=new WeakMap();
const purchaseRecordCache=new Map();
let currentPurchaseViewRef='';
const PURCHASE_PAGE_SIZE=100;
let purchaseRecordsTotal=0;
let purchaseRecordsOffset=0;
let purchaseRecordsLoading=false;
let purchaseRecordsLoaded=false;

function scheduleIdleTask(fn,timeout=800){
  if('requestIdleCallback' in window){
    window.requestIdleCallback(fn,{timeout});
  }else{
    setTimeout(fn,0);
  }
}

function scheduleTableRefresh(table,delay=120){
  if(!table)return;
  const existing=tableRefreshTimers.get(table);
  if(existing)clearTimeout(existing);
  const timer=setTimeout(()=>{
    tableRefreshTimers.delete(table);
    refreshEnhancedTable(table);
  },isHydratingFromServer?Math.max(delay,350):delay);
  tableRefreshTimers.set(table,timer);
}

function runPageWarmup(page){
  const pageId='page-'+page;
  scheduleIdleTask(()=>{
    enhancePageTables(pageId);
    bindDetailViews();
    bindEditActions();
    bindGenericAddActions();
    if(page==='rota'){
      _fixStaleRotaDateDefaults();
      seedDefaultRotaShifts();
      renderRotaBoards();
      updateRotaStats();
      // Edit Shift's task-attachment picker (openRotaCellEditor) needs
      // _taskListCache populated -- loadTasks() otherwise only runs when
      // the Tasks page itself has been visited this session.
      if(!_taskListCache.length)loadTasks();
    }
  },500);
}

const navHistory=[];
let restoringNavigation=false;

function getCurrentNavState(){
  const pageEl=document.querySelector('.page.on');
  const page=(pageEl?.id||'page-dashboard').replace(/^page-/,'')||'dashboard';
  const tab=pageEl?.querySelector('.tab-body.on')?.id||'';
  return {page,tab};
}

function sameNavState(a,b){
  return !!a&&!!b&&a.page===b.page&&a.tab===b.tab;
}

function updateBackButton(){
  const back=document.getElementById('back-btn');
  if(back)back.disabled=navHistory.length===0;
}

function rememberNavState(state){
  if(!state?.page)return;
  const last=navHistory[navHistory.length-1];
  if(!sameNavState(last,state))navHistory.push(state);
  if(navHistory.length>40)navHistory.shift();
  updateBackButton();
}

function restoreNavState(state){
  if(!state?.page)return;
  restoringNavigation=true;
  go(state.page);
  if(state.tab){
    const tab=[...document.querySelectorAll('#page-'+state.page+' .tab')].find(el=>(el.getAttribute('onclick')||'').includes("'"+state.tab+"'"));
    if(tab)stab(tab,state.tab);
  }
  restoringNavigation=false;
  updateBackButton();
}

function goBack(){
  const openOverlay=[...document.querySelectorAll('.overlay.on')].pop();
  if(openOverlay){
    openOverlay.classList.remove('on');
    return;
  }
  const previous=navHistory.pop();
  if(!previous){
    updateBackButton();
    toast('No previous page','info');
    return;
  }
  restoreNavState(previous);
}

// Direct-navigation guard for HRMS sub-users (Employee principals with a
// restricted role) — blocks go()/goHrmsTab() calls reaching a module the
// current role's permissions don't grant :view for (URL hash tampering,
// back button, stale bookmarks). This is UI politeness only: the real
// control is the backend 403 on every underlying API call — a user who
// bypasses this via devtools still gets no data. window.HRMS_ALLOWED_MODULES
// is populated by applyHrmsPermissionNav() (hrms.html); until it's set (or
// for a User/admin principal), navigation is never blocked.
function _hrmsNavAllowed(matchSubstr){
  if(!window.HRMS_STANDALONE||window.HRMS_IS_ADMIN!==false||!window.HRMS_ALLOWED_MODULES)return true;
  const navs=[...document.querySelectorAll('.sb .nav[data-module]')].filter(n=>(n.getAttribute('onclick')||'').includes(matchSubstr));
  if(!navs.length)return true; // not a sidebar-gated destination — don't block
  return navs.some(n=>window.HRMS_ALLOWED_MODULES.has(n.getAttribute('data-module')));
}
function _hrmsBlockNav(){
  toast("You don't have access to this module — contact your administrator",'warn');
}

// go() re-queries these on every single navigation click otherwise — cheap
// per DOM size today but scales linearly with every page/nav item added.
// Safe to cache once: all .page/.nav/.nav-sub elements are static markup
// baked into the HTML at load, never added/removed dynamically afterward.
let _navPageEls=null,_navItemEls=null,_navSubEls=null;
function _cachedNavEls(){
  if(!_navPageEls)_navPageEls=[...document.querySelectorAll('.page')];
  if(!_navItemEls)_navItemEls=[...document.querySelectorAll('.nav')];
  if(!_navSubEls)_navSubEls=[...document.querySelectorAll('.nav-sub')];
  return {pages:_navPageEls,navs:_navItemEls,navSubs:_navSubEls};
}

function go(page){
  // hrms.html's own boot sequence schedules a forced go('hrms') 300ms after
  // DOMContentLoaded to establish the default Dashboard view -- unconditional,
  // so a real sidebar click landing before that timer fires (a slow initial
  // load, or just a fast click) got silently overridden back to Dashboard a
  // moment later. Exposed as a real window property (not a plain module-level
  // let/const, which a classic <script> doesn't expose to hrms.html's own
  // inline <script> block) so that boot-time call can check it first.
  window._hrmsAnyNavHappened=true;
  // 'staff' and 'hrms-ext' are shared containers for several differently-
  // permissioned tabs (Employees vs HR Workflow; Performance/Training/
  // Assets) — gating them here would block a legitimately-permitted tab's
  // own goHrmsTab()/goHrmsExtTab() call, which already guards itself below.
  if(page!=='staff'&&page!=='hrms-ext'&&!_hrmsNavAllowed(`go('${page}')`)){_hrmsBlockNav();return;}
  // Company-level Module Permissions (set by superadmin) — separate from the
  // HRMS per-employee RBAC check above. Only meaningful in the main app.
  if(!window.HRMS_STANDALONE&&!_moduleNavAllowed(page)){
    toast("This module isn't enabled for your company — contact support to enable it",'warn');
    return;
  }
  if(!_mainDashboardNavAllowed(page)){_mainDashboardBlockNav();return;}
  if(page==='corporate')_ensureCorporateLoaded();
  if(page==='ai')_ensureAIWorkbenchLoaded();
  if(page==='payments'){
    go('bank');
    setTimeout(()=>{
      const tab=[...document.querySelectorAll('#page-bank .tab')].find(item=>(item.getAttribute('onclick')||'').includes("'pay-in'"));
      if(tab)stab(tab,'pay-in');
    },50);
    return;
  }
  if(page==='company'){
    go('settings');
    setTimeout(()=>stab(document.querySelectorAll('#page-settings .tab')[0],'set-company'),50);
    return;
  }
  if(page==='design'){
    toast('System Design is hidden','info');
    return;
  }
  if(page==='hr-settings'){
    if(window.HRMS_STANDALONE){
      const fromState=getCurrentNavState();
      if(!restoringNavigation&&fromState.page!=='hr-settings')rememberNavState(fromState);
      const {pages:_hrPages,navs:_hrNavs}=_cachedNavEls();
      _hrPages.forEach(p=>p.classList.remove('on'));
      _hrNavs.forEach(n=>n.classList.remove('on'));
      const staffPage=document.getElementById('page-staff');
      if(staffPage){
        staffPage.classList.add('on');
        staffPage.querySelectorAll('.tab').forEach(t=>t.classList.remove('on'));
        staffPage.querySelectorAll('.tab-body').forEach(b=>b.classList.remove('on'));
        document.getElementById('hr-policy')?.classList.add('on');
      }
      document.getElementById('ptitle').textContent='HR Settings';
      document.getElementById('psub').textContent='Configure departments, roles, OT rules, leave policy, and user access';
      document.getElementById('nav-hr-settings')?.classList.add('on');
    }else{
      window.open('/hrms','_blank');
    }
    return;
  }
  const target=document.getElementById('page-'+page);
  if(!target)return;
  const fromState=getCurrentNavState();
  if(!restoringNavigation&&fromState.page!==page)rememberNavState(fromState);
  const {pages:_pages,navs:_navs,navSubs:_navSubs}=_cachedNavEls();
  _pages.forEach(p=>p.classList.remove('on'));
  _navs.forEach(n=>n.classList.remove('on'));
  target.classList.add('on');
  _navs.forEach(n=>{if((n.getAttribute('onclick')||'').includes("'"+page+"'"))n.classList.add('on');});
  if(page==='corporate'){
    const corpPage=document.getElementById('page-corporate');
    corpPage?.querySelectorAll('.tab').forEach(tab=>tab.classList.remove('on'));
    corpPage?.querySelectorAll('.tab-body').forEach(body=>body.classList.remove('on'));
    corpPage?.querySelector('.tab')?.classList.add('on');
    document.getElementById('corp-tax-tab')?.classList.add('on');
  }
  // Falls back to a plain title derived from the page id itself instead of
  // hard-crashing navigation — a page with a real #page-<id> element but no
  // META[<id>] registration (see META['hrms-ai']'s own comment for how this
  // was actually hit) previously threw here with no page title ever set.
  const m=META[page]||{t:page.replace(/-/g,' ').replace(/\b\w/g,c=>c.toUpperCase()),s:'',a:'',ao:null};
  const mAr=_appLang==='ar'?(_META_AR[page]||{}):null;
  document.getElementById('ptitle').textContent=mAr?.t||m.t;
  document.getElementById('psub').textContent=mAr?.s||m.s;
  const topAction=document.getElementById('topaction');
  if(topAction){
    topAction.textContent=m.a||'';
    topAction.onclick=m.ao||null;
    topAction.classList.toggle('hidden',!m.a);
  }
  // Keep staff nav highlighted for staff sub-pages
  if(['staff'].includes(page)){
    document.getElementById('nav-hrms')?.classList.add('on');
  }
  _navSubs.forEach(s=>s.classList.remove('on'));
  localStorage.setItem('taxflow_current_page',page);
  closeSidebar();
  if(page==='reports'){loadReportsBranchSelector();syncReportsFromDatabase();}
  if(page==='hrms-reports')loadHrAttendanceReport();
  if(page==='tasks')loadTasks();
  if(page==='exception')loadExceptionCenter();
  if(page==='expense'){loadExpenseVendors();ensureExpensesLoaded();}
  if(page==='recruitment')scheduleIdleTask(refreshRecruitmentStats,100);
  if(page==='hrms-ext')scheduleIdleTask(refreshManagerPortalCounts,100);
  if(page==='inventory'){
    ensurePurchaseRecordsLoadedForStock();
    setTimeout(()=>ensureInventoryBulkSelection(),80);
  }
  if(page==='pos')loadPosPage();
  if(page==='sales')ensureSalesRegisterLoaded();
  if(page==='bills')ensureBillsLoaded();
  if(page==='quotations')loadRegisterPage('quotations');
  if(page==='purchase')ensurePurchaseDocumentsLoaded();
  if(page==='bank')loadPaymentTotals();
  if(page==='accounting'){loadAccountingFromDb();renderPeriodLockPanel();}
  runPageWarmup(page);
  updateBackButton();
}

function stab(el,target){
  if(!el)return;
  const fromState=getCurrentNavState();
  if(!restoringNavigation&&target&&fromState.tab!==target)rememberNavState(fromState);
  const tb=el.closest('.tabs');
  if(tb)tb.querySelectorAll('.tab').forEach(t=>t.classList.remove('on'));
  el.classList.add('on');
  const pg=el.closest('.page');
  if(pg)pg.querySelectorAll('.tab-body').forEach(b=>b.classList.remove('on'));
  const t=document.getElementById(target);
  if(t)t.classList.add('on');
  if(target==='hr-ot')loadOtEligibility();
  if(target==='inv-mapping')loadStockMappingsFromServer();
  if(target==='inv-stock')ensurePurchaseRecordsLoadedForStock();
  if(String(target||'').startsWith('inv-'))setTimeout(()=>ensureInventoryBulkSelection(),80);
  if(target==='p-records')goToPurchaseRecordsPage(1);
  if(target==='s-invoices')ensureSalesRegisterLoaded();
  if(target==='pay-in')loadRegisterPage('receipts');
  if(target==='q-list')loadRegisterPage('quotations');
  if(target==='pay-out')ensureSupplierPaymentsLoaded();
  if(target==='bk-transactions')loadRegisterPage('bankTx');
  // loadLeaveRequests() was previously only wired into the Leave
  // Management tab's own inline onclick (hrms.html) -- every OTHER real
  // path that lands here (the sidebar's "Leave" nav item, the Dashboard's
  // Pending Approvals "View all" link, the notifications icon, the
  // approvals-row quick action) all call goHrmsTab(4,'hr-leave'), which
  // only runs stab() itself, never a tab element's own onclick chain. The
  // Leave Requests table was therefore permanently stuck on "No database
  // records yet" through every one of those paths, even with real
  // pending/approved requests in the database -- only literally re-
  // clicking the already-selected inner tab strip item ever loaded it.
  // Centralized here, matching hr-att's existing fix below for the same
  // bug class.
  if(target==='hr-leave'){scheduleIdleTask(updateLeaveBalance,50);loadLeaveRequests();}
  // Previously only wired into the Attendance tab element's own inline
  // onclick (hrms.html) — any OTHER path that lands on this tab
  // programmatically (goHrmsTab(2,'hr-att'), used by the sidebar's own
  // "Attendance" nav item and the AI Insights "View Attendance" link)
  // never called any of these, leaving every stat/table/chart on the tab
  // permanently stuck at zero/"Loading…" with no error and no retry —
  // confirmed live: waited 6s, nothing ever resolved. Centralizing here
  // means every path that reaches this tab loads it correctly exactly
  // once, including the tab's own literal click (now removed from its
  // onclick to avoid firing these twice on a direct click).
  // openAttendanceCheck() (the "Do you have any absences today?" modal)
  // is deliberately NOT included here — that one shouldn't pop up
  // automatically every single time this tab is opened (it did before
  // this fix too, via the tab's own onclick; moving it into stab() would
  // have made an already-questionable auto-popup fire from even MORE
  // places, like the sidebar). It's now a real "📋 Daily Check" button
  // instead, same section as Correction/Import CSV/Sync Now.
  if(target==='hr-att'){
    refreshAttendanceToday();
    loadAttendanceTrend();
    renderHrAccessPanel();
  }
  if(target==='acc-voucher')prepareJournalForm();
  if(target==='bk-reconcile')loadBankReconItems();
  if(target==='acc-ledger')loadAccountingFromDb();
  if(target==='set-backup')loadBackupTab();
  if(target==='set-users')loadUsersIntoTable();
  if(target==='p-manual'){
    bindManualPurchaseCalculator();
    setManualPurchaseDefaults();
  }
  if(target==='p-extract')autoClearIncompleteUploads();
  updateBackButton();
}

function toast(msg,type='ok'){
  const svgs={
    ok:`<svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="8" cy="8" r="6"/><polyline points="5.5,8 7,9.5 10.5,6"/></svg>`,
    warn:`<svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><path d="M8 2.5L14 13H2z"/><line x1="8" y1="7" x2="8" y2="10"/><circle cx="8" cy="11.5" r=".6" fill="currentColor" stroke="none"/></svg>`,
    err:`<svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="8" cy="8" r="6"/><line x1="5.5" y1="5.5" x2="10.5" y2="10.5"/><line x1="10.5" y1="5.5" x2="5.5" y2="10.5"/></svg>`,
    info:`<svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="8" cy="8" r="6"/><line x1="8" y1="7.5" x2="8" y2="11"/><circle cx="8" cy="5.5" r=".6" fill="currentColor" stroke="none"/></svg>`,
  };
  const clrs={ok:'var(--green)',warn:'var(--amber)',err:'var(--red)',info:'var(--accent)'};
  const t=document.createElement('div');
  t.className='toast '+type;
  const icon=document.createElement('span');
  icon.style.cssText=`color:${clrs[type]||clrs.info};display:inline-flex;flex-shrink:0`;
  icon.innerHTML=svgs[type]||svgs.info;
  const text=document.createElement('span');
  text.textContent=msg;
  t.append(icon,text);
  document.getElementById('toasts').appendChild(t);
  setTimeout(()=>t.remove(),3500);
}

function toggleSidebar(force){
  const isMobile=window.innerWidth<=1100;
  if(isMobile){
    const open=force??!document.body.classList.contains('nav-open');
    document.body.classList.toggle('nav-open',open);
    document.getElementById('nav-scrim')?.classList.toggle('on',open);
    document.getElementById('menu-btn')?.setAttribute('aria-expanded',String(open));
  } else {
    const hide=force!==undefined?force:!document.body.classList.contains('sb-hidden');
    document.body.classList.toggle('sb-hidden',hide);
    localStorage.setItem('sb-hidden',hide?'1':'');
  }
}
function closeSidebar(){
  if(window.innerWidth<=1100)toggleSidebar(false);
}

// go('staff') highlights every sidebar item whose onclick text contains
// 'staff' (Employees AND HR Workflow both call go('staff') with nothing to
// tell them apart) plus unconditionally re-highlights Dashboard (its own
// hardcoded "keep staff nav highlighted" fallback) -- so every sidebar
// item that shares the #page-staff container (Employees, Attendance,
// Leave, Overtime, Loans & Advances, HR Workflow) ended up lighting up
// Dashboard + Employees + HR Workflow together, regardless of which one
// was actually clicked, and never itself. Called after go('staff') to
// correct the sidebar down to just the one item that actually matches
// navKey (via data-staff-nav) -- or none, for a goHrmsTab() call with no
// sidebar entry of its own (e.g. Corrections, Expiry Alerts).
function _hrmsFixStaffNavHighlight(navKey){
  document.querySelectorAll('.sb .nav.on').forEach(n=>n.classList.remove('on'));
  document.querySelector(`.sb .nav[data-staff-nav="${navKey}"]`)?.classList.add('on');
}

// Same problem as _hrmsFixStaffNavHighlight, for #page-hrms-ext's own
// shared container: Performance/Training/Assets previously all called bare
// go('hrms-ext') with no tab argument, so clicking any of them just showed
// whichever internal tab was last active rather than the one actually
// clicked — and since all three onclick attributes contained the literal
// substring 'hrms-ext', go()'s generic nav highlighter lit up all three
// sidebar items together regardless of which was clicked. Now called from
// goHrmsExtTab() after go('hrms-ext') to both open the right tab AND
// highlight only the one matching sidebar entry.
function _hrmsFixExtNavHighlight(navKey){
  document.querySelectorAll('.sb .nav.on').forEach(n=>n.classList.remove('on'));
  document.querySelector(`.sb .nav[data-hrext-nav="${navKey}"]`)?.classList.add('on');
}

function goHrmsTab(n,id){
  if(window.HRMS_STANDALONE){
    if(!_hrmsNavAllowed(`goHrmsTab(${n},'${id}')`)){_hrmsBlockNav();return;}
    const tab=document.querySelector('#page-staff .tab:nth-child('+n+')');
    if(tab)stab(tab,id);
    go('staff');
    _hrmsFixStaffNavHighlight(id);
  }else{
    window.open('/hrms','_blank');
  }
}

// Same as goHrmsTab, but for #page-hrms-ext (Performance/Training/Asset
// Management/ESS Portal/Manager Portal) instead of #page-staff.
function goHrmsExtTab(n,id){
  if(window.HRMS_STANDALONE){
    if(!_hrmsNavAllowed(`goHrmsExtTab(${n},'${id}')`)){_hrmsBlockNav();return;}
    const tab=document.querySelector('#page-hrms-ext .tab:nth-child('+n+')');
    if(tab)stab(tab,id);
    go('hrms-ext');
    _hrmsFixExtNavHighlight(id);
  }else{
    window.open('/hrms','_blank');
  }
}

// Feeds New Loan / Salary Advance / Submit OT / Attendance Correction /
// Shift Swap (both sides) -- the one employee-picker left in the app that
// scraped #employee-tbody with no active/inactive filter at all, unlike
// every sibling picker (currentRotaStaff(), _getAttendanceEmployees(),
// /payroll/employees-backed selects). An Inactive employee should stay
// visible in the Employee Directory itself (their history/records are
// kept), but has no reason to be offered here for brand-new work.
function populateHrEmployeeSelect(id){
  const sel=document.getElementById(id);
  if(!sel)return;
  sel.innerHTML='<option value="">— select employee —</option>';
  document.querySelectorAll('#employee-tbody tr:not([data-empty-state])').forEach(row=>{
    const emp=employeeFromDirectoryRow(row);
    if(!emp||!emp.name||emp.name==='Employee'||emp.status==='Inactive')return;
    const opt=document.createElement('option');
    opt.value=emp.name;
    opt.dataset.empId=emp.id||'';
    opt.textContent=emp.name+(emp.id?' ('+emp.id+')':'');
    sel.appendChild(opt);
  });
}

function populateEmpShiftSelect(){
  const sel=document.getElementById('emp-shift');
  if(!sel)return;
  const current=sel.value;
  sel.innerHTML='<option value="">— Select Shift —</option>';
  const shiftRows=[...document.querySelectorAll('#rota-shift-tbody tr:not([data-empty-state])')];
  shiftRows.forEach(row=>{
    const shift=row.dataset.shift?JSON.parse(row.dataset.shift):null;
    if(!shift||!shift.code)return;
    const opt=document.createElement('option');
    opt.value=shift.name||shift.code;
    const timeRange=shift.start&&shift.end?` · ${shift.start}–${shift.end}`:'';
    opt.textContent=`${shift.name||shift.code} (${shift.code})${timeRange}`;
    sel.appendChild(opt);
  });
  if(current)sel.value=current;
}

function populateRotaEditTypeSelect(restoreVal){
  const sel=document.getElementById('rota-edit-type');
  if(!sel)return;
  const current=restoreVal!==undefined?restoreVal:sel.value;
  sel.innerHTML='';
  const shiftRows=[...document.querySelectorAll('#rota-shift-tbody tr:not([data-empty-state])')];
  const shiftGrp=document.createElement('optgroup');
  shiftGrp.label='Shifts';
  const blankOpt=document.createElement('option');
  blankOpt.value='';blankOpt.textContent='— Select Shift —';
  shiftGrp.appendChild(blankOpt);
  shiftRows.forEach(row=>{
    let shift=null;
    try{shift=JSON.parse(row.dataset.shift||'{}');}catch{}
    const shiftName=shift?.name||shift?.shift_name||(row.children[0]?.textContent||'').trim();
    if(!shiftName)return;
    if((shift?.status||'Active').toLowerCase()==='inactive')return;
    // department-wise shifts: an employee's rota cell only offers shifts for their own department
    if(activeRotaCell&&shift&&!shiftAppliesToDepartment(shift,activeRotaCell.dataset.department))return;
    const start=shift?.start||shift?.start_time||'';
    const end=shift?.end||shift?.end_time||'';
    const opt=document.createElement('option');
    opt.value=shiftName;
    opt.textContent=shiftName+(start&&end?` · ${start}–${end}`:'');
    shiftGrp.appendChild(opt);
  });
  if(!shiftGrp.children.length){
    ['Morning','Evening','Night'].forEach(s=>{
      const opt=document.createElement('option');
      opt.value=s;opt.textContent=s;
      shiftGrp.appendChild(opt);
    });
  }
  sel.appendChild(shiftGrp);
  if(current)sel.value=current;
}

function showM(id){
  const modal=document.getElementById(id);
  if(!modal)return;
  ensureModalCloseButton(modal,id);
  modal.classList.add('on');
  if(id==='m-user')applyUserRolePermissions();
  if(id==='m-emp'&&!document.getElementById('emp-id')?.value)setFieldValue(document.getElementById('emp-id'),nextEmployeeId());
  if(id==='m-edit-shift')populateRotaEditTypeSelect();
  if(id==='m-payment')setTimeout(()=>syncPaymentFormOptions(),0);
  if(id==='m-leave')populateLeaveEmployeeSelect();
  if(id==='m-loan')populateHrEmployeeSelect('loan-employee');
  if(id==='m-loan-advance')populateHrEmployeeSelect('advance-employee');
  // updateOtMultiplier() previously only ran on #ot-type's onchange / #ot-hours's
  // oninput — leaving the type on its default and submitting straight away sent
  // whatever the HTML shipped with (1.25×) instead of the configured rate, and
  // #ot-hours stayed blank/0 until the user touched it. Populate both on open.
  if(id==='m-ot'){populateHrEmployeeSelect('ot-employee-sel');updateOtMultiplier();}
  if(id==='m-att-correction')populateHrEmployeeSelect('corr-employee');
  if(id==='m-shift-swap'){populateHrEmployeeSelect('swap-employee-a');populateHrEmployeeSelect('swap-employee-b');}
  setTimeout(()=>modal.querySelector('input,select,textarea,button:not(.modal-x)')?.focus(),30);
}

function ensureModalCloseButton(overlay,id){
  const panel=overlay.querySelector('.modal');
  if(!panel||panel.querySelector('.modal-x,.pmt-close,.icon-btn[aria-label="Close"]'))return;
  const close=document.createElement('button');
  close.type='button';
  close.className='modal-x';
  close.setAttribute('aria-label','Close popup');
  close.title='Close';
  close.textContent='×';
  close.onclick=event=>{
    event.stopPropagation();
    closeM(id);
  };
  panel.prepend(close);
}

const hideM=id=>closeM(id);
function closeM(id){
  document.getElementById(id)?.classList.remove('on');
  if(id==='m-emp'){
    const titleEl=document.querySelector('#m-emp .modal-title');
    const subEl=document.querySelector('#m-emp .modal-sub');
    const btnEl=document.querySelector('#m-emp .btn-p');
    if(titleEl)titleEl.textContent='Add Employee';
    if(subEl)subEl.textContent='Register new employee details';
    if(btnEl)btnEl.textContent='Add Employee';
  }
  if(id==='m-customer'){
    customerReturnToInvoice=false;
    customerReturnToQuotation=false;
  }
  if(id==='m-product'){
    productReturnToInvoice=false;
    productTargetLine=null;
  }
}

function ensureAppConfirmModal(){
  let overlay=document.getElementById('m-app-confirm');
  if(overlay)return overlay;
  overlay=document.createElement('div');
  overlay.className='overlay';
  overlay.id='m-app-confirm';
  overlay.innerHTML=`
    <div class="modal modal-sm app-confirm-modal">
      <div class="modal-title" id="app-confirm-title">Confirm Action</div>
      <div class="modal-sub" id="app-confirm-message">Please confirm this action.</div>
      <div class="modal-foot">
        <button class="btn btn-g" id="app-confirm-cancel" type="button">Cancel</button>
        <button class="btn btn-danger" id="app-confirm-ok" type="button">Delete</button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
  return overlay;
}

function appConfirm({title='Confirm Action',message='Please confirm this action.',messageHtml='',okText='Delete',cancelText='Cancel',tone='danger'}={}){
  const overlay=ensureAppConfirmModal();
  const ok=overlay.querySelector('#app-confirm-ok');
  const cancel=overlay.querySelector('#app-confirm-cancel');
  cancel.textContent=cancelText;
  overlay.querySelector('#app-confirm-title').textContent=title;
  const msgEl=overlay.querySelector('#app-confirm-message');
  if(messageHtml){
    const _tmp=document.createElement('div');
    _tmp.innerHTML=messageHtml;
    _tmp.querySelectorAll('script,style,iframe,object,embed').forEach(el=>el.remove());
    _tmp.querySelectorAll('*').forEach(el=>{[...el.attributes].forEach(a=>{if(/^on/i.test(a.name)||(a.name==='href'&&/^javascript:/i.test(a.value)))el.removeAttribute(a.name);});});
    msgEl.innerHTML=_tmp.innerHTML;
  }else{msgEl.textContent=message;}
  ok.textContent=okText;
  ok.className=`btn ${tone==='danger'?'btn-danger':'btn-p'}`;
  overlay.classList.add('on');
  return new Promise(resolve=>{
    const done=value=>{
      overlay.classList.remove('on');
      ok.onclick=null;
      cancel.onclick=null;
      overlay.onclick=null;
      resolve(value);
    };
    ok.onclick=event=>{
      event.stopPropagation();
      done(true);
    };
    cancel.onclick=event=>{
      event.stopPropagation();
      done(false);
    };
    overlay.onclick=event=>{
      if(event.target===overlay)done(false);
    };
    setTimeout(()=>cancel.focus(),30);
  });
}

// Used to close the modal on a click landing directly on the dark backdrop
// (e.target.id===id, i.e. outside the .modal panel itself) -- disabled by
// request: a stray click outside a form like New Receipt/Payment silently
// discarded whatever had been typed, with no confirmation. Every modal still
// has its own X (ensureModalCloseButton) and Cancel/Close button, so this is
// now a deliberate no-op rather than removing the ~59 closeOvBg(event,'id')
// call sites across index.html/hrms.html/app.js that still wire it up.
function closeOvBg(e,id){}
function saveM(id,msg){closeM(id);toast(msg,'ok');audit(msg.replace(/[?.]/g,'').trim(),id,'Saved');}

function initialsFromName(name){
  return String(name||'User').trim().split(/\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase()||'U';
}

function roleBadgeClass(role){
  const map={Admin:'b-p',Manager:'b-t',Accountant:'b-b',Sales:'b-gray',Viewer:'b-gray'};
  return map[role]||'b-gray';
}

function rolePermissionDefaults(role){
  const all=['sales','purchases','staff','payroll','reports'];
  const actions=['view','create','approve','export','admin'];
  const set=(modules,perms)=>{
    const allowed=new Set();
    modules.forEach(module=>perms.forEach(perm=>allowed.add(`${module}:${perm}`)));
    return allowed;
  };
  if(role==='Admin')return set(all,actions);
  if(role==='Manager')return set(all,['view','create','approve','export']);
  if(role==='Accountant')return set(['sales','purchases','reports'],['view','create','approve','export']);
  if(role==='Sales')return set(['sales','reports'],['view','create','export']);
  return set(all,['view']);
}

function applyUserRolePermissions(){
  const role=document.getElementById('user-role')?.value||'Viewer';
  const defaults=rolePermissionDefaults(role);
  document.querySelectorAll('[data-user-perm]').forEach(box=>{
    box.checked=defaults.has(box.dataset.userPerm);
  });
}

function collectUserPermissions(){
  return [...document.querySelectorAll('[data-user-perm]:checked')].map(box=>box.dataset.userPerm);
}

function permissionSummary(permissions=[]){
  if(!Array.isArray(permissions))permissions=[];
  const modules=[...new Set(permissions.map(item=>String(item).split(':')[0]))];
  if(permissions.some(item=>String(item).endsWith(':admin')))return 'All modules';
  if(modules.length===0)return 'No access';
  if(modules.length>3)return `${modules.length} modules`;
  const names={sales:'Sales',purchases:'Purchases',staff:'Staff',payroll:'Payroll',reports:'Reports'};
  return modules.map(module=>names[module]||titleCase(module)).join(', ');
}

function resetUserForm(){
  ['user-name','user-email','user-temp-password'].forEach(id=>setFieldValue(document.getElementById(id),''));
  setFieldValue(document.getElementById('user-role'),'Admin');
  setFieldValue(document.getElementById('user-status'),'Active');
  applyUserRolePermissions();
}

async function saveUser(){
  const name=document.getElementById('user-name')?.value.trim()||'';
  const email=document.getElementById('user-email')?.value.trim()||'';
  const role=document.getElementById('user-role')?.value||'Viewer';
  const status=document.getElementById('user-status')?.value||'Active';
  const permissions=collectUserPermissions();
  if(!name||!email){
    toast('Enter user name and email','warn');
    return;
  }
  if(!permissions.length){
    toast('Select at least one permission','warn');
    return;
  }
  let password=document.getElementById('user-temp-password')?.value||'';
  const generated=!password;
  if(generated)password=Math.random().toString(36).slice(2,8)+Math.random().toString(36).slice(2,6).toUpperCase()+'7';
  // The server enforces these roles (they used to all become a full-access 'user').
  const apiRole={Admin:'admin',Manager:'manager',Accountant:'accountant',Sales:'sales',Viewer:'viewer'}[role]||'viewer';
  try{
    await moduleApi('/companies/current/users',{method:'POST',body:{email,full_name:name,password,role:apiRole}});
  }catch(err){
    toast(`User not created: ${err.message}`,'err');
    return;
  }
  const user={
    id:`USER-${Date.now()}`,
    name,
    email,
    role,
    status,
    permissions,
    temporary_password_set:true,
    created_at:new Date().toISOString()
  };
  renderUserRecord(user);
  saveServer('users',user);
  closeM('m-user');
  resetUserForm();
  toast(generated?`User created — temporary password: ${password} (share it securely)`:'User created','ok');
  audit('Created user',email,'Saved');
}

function renderUserRecord(user){
  const tbody=document.getElementById('user-tbody');
  if(!tbody)return;
  const existing=[...tbody.querySelectorAll('tr')].find(row=>{
    const data=row.dataset.user?JSON.parse(row.dataset.user):null;
    return data&&(data.id===user.id||data.email===user.email);
  });
  if(existing)existing.remove();
  const row=document.createElement('tr');
  row.dataset.user=JSON.stringify(user);
  row.innerHTML=`
    <td><div class="flx"><div class="co-av">${escapeHtml(initialsFromName(user.name))}</div><span style="margin-left:8px">${escapeHtml(user.name)}</span></div></td>
    <td>${escapeHtml(user.email)}</td>
    <td><span class="b ${roleBadgeClass(user.role)}">${escapeHtml(user.role)}</span></td>
    <td><span class="b b-b">${escapeHtml(permissionSummary(user.permissions))}</span></td>
    <td><span class="b ${user.status==='Active'?'b-g':'b-gray'}">${escapeHtml(user.status)}</span></td>
    <td class="mono">Never</td>
    <td><button class="btn btn-g btn-sm">Edit</button></td>`;
  tbody.prepend(row);
  refreshEnhancedTable(tbody.closest('table'));
}

function nextEmployeeId(){
  const ids=[...document.querySelectorAll('#employee-tbody tr td:first-child')].map(td=>td.textContent.trim());
  const max=ids.reduce((num,id)=>Math.max(num,Number((id.match(/\d+/)||['0'])[0])),0);
  return `EMP-${String(max+1).padStart(3,'0')}`;
}

function employeeFormValue(id,fallback=''){
  return document.getElementById(id)?.value.trim()||fallback;
}

function openEmpEdit(emp){
  // Pre-fill all m-emp fields with existing employee data
  const setV=(id,val)=>{const el=document.getElementById(id);if(el)el.value=val||'';};
  const setSel=(id,val)=>{const el=document.getElementById(id);if(el&&val){const opt=[...el.options].find(o=>o.value===val||o.textContent===val);if(opt)el.value=opt.value;}};
  setV('emp-id',emp.id);
  setV('emp-name',emp.name);
  setV('emp-nickname',emp.nickname);
  setV('emp-email',emp.email);
  setV('emp-mobile',emp.mobile);
  setSel('emp-department',emp.department);
  setV('emp-designation',emp.designation);
  setV('emp-supervisor',emp.supervisor);
  setV('emp-salary',emp.salary);
  setV('emp-housing-allowance',emp.housing_allowance||0);
  setV('emp-transport-allowance',emp.transport_allowance||0);
  setV('emp-other-allowance',emp.other_allowance||0);
  setSel('emp-contract',emp.contract);
  setSel('emp-branch',emp.branch||emp.location);
  // pre-filter roles then set saved role
  filterEmpRoles();
  setV('emp-role',emp.role_id||'');
  setSel('emp-location',emp.location);
  setV('emp-cost-center',emp.cost_center);
  setSel('emp-nationality',emp.nationality);
  setV('emp-dob',emp.dob);
  setSel('emp-gender',emp.gender);
  setSel('emp-marital',emp.marital_status);
  setV('emp-address',emp.address);
  setV('emp-join-date',emp.join_date);
  setSel('emp-ot-rate',emp.overtime_rate);
  setSel('emp-leave-policy',emp.leave_policy);
  setSel('emp-shift',emp.shift);
  setV('emp-emergency',emp.emergency_contact);
  setV('emp-emergency-mobile',emp.emergency_mobile);
  setV('emp-work-permit',emp.work_permit_no);
  setV('emp-visa-expiry',emp.visa_expiry);
  setV('emp-emirates-id',emp.emirates_id);
  setV('emp-eid-expiry',emp.eid_expiry);
  setV('emp-passport-no',emp.passport_no);
  setV('emp-passport-expiry',emp.passport_expiry);
  setV('emp-labor-card',emp.labor_card);
  setV('emp-labor-card-expiry',emp.labor_card_expiry);
  setV('emp-driving-license',emp.driving_license);
  setV('emp-driving-expiry',emp.driving_expiry);
  setSel('emp-insurance-type',emp.insurance_type);
  setV('emp-insurance-policy',emp.insurance_policy);
  setV('emp-insurance-expiry',emp.insurance_expiry);
  setSel('emp-bank',emp.salary_bank);
  setV('emp-iban',emp.iban);
  setV('emp-personal-code',emp.personal_code);
  setV('emp-routing-code',emp.routing_code);
  // Restore the previously-saved photo into the preview box. Without this,
  // the preview always reset to the empty placeholder icon on every Edit
  // open, and saveEmployee() reads whatever <img> is (or isn't) in that box
  // at save time -- so re-saving an edit without re-picking a new photo
  // silently wiped out the employee's existing photo every time.
  const photoEl=document.getElementById('emp-photo-preview');
  if(photoEl){
    photoEl.innerHTML=emp.photo
      ?`<img src="${emp.photo}" style="width:100%;height:100%;object-fit:cover">`
      :'<svg viewBox="0 0 24 24" width="30" height="30" fill="none" stroke="var(--text3)" stroke-width="1.4"><circle cx="12" cy="8" r="4"/><path d="M4 20c0-4 3.6-7 8-7s8 3 8 7"/></svg>';
  }
  // Update modal title and button for edit mode
  const titleEl=document.querySelector('#m-emp .modal-title');
  const subEl=document.querySelector('#m-emp .modal-sub');
  const btnEl=document.querySelector('#m-emp .btn-p');
  if(titleEl)titleEl.textContent='Edit Employee';
  if(subEl)subEl.textContent=`Editing ${emp.name||'employee'} — ${emp.id||''}`;
  if(btnEl)btnEl.textContent='Save Changes';
  _populateEmpSelects();
  setSel('emp-department',emp.department);
  setSel('emp-branch',emp.branch||emp.location);
  filterEmpRoles();
  setV('emp-role',emp.role_id||'');
  showM('m-emp');
}

function saveEmployee(){
  // Captured before the modal title gets reset back to "Add Employee"
  // below — editEmployeeFromRow() sets it to "Edit Employee" when opening
  // the form to edit an existing record, the only signal this function has
  // for which toast/audit-log wording to use. This variable was referenced
  // at the bottom of this function but never declared anywhere, throwing
  // "isEdit is not defined" on every single save — the record itself still
  // saved correctly, but the ReferenceError meant neither the success toast
  // nor the audit() call ever ran.
  const isEdit=document.querySelector('#m-emp .modal-title')?.textContent==='Edit Employee';
  const passportFile=document.getElementById('emp-passport-file')?.files?.[0];
  const workPermitFile=document.getElementById('emp-work-permit-file')?.files?.[0];
  const medicalFile=document.getElementById('emp-medical-file')?.files?.[0];
  const photoPreview=document.getElementById('emp-photo-preview')?.querySelector('img')?.src||'';
  const employee={
    id:employeeFormValue('emp-id',nextEmployeeId()),
    name:employeeFormValue('emp-name'),
    nickname:employeeFormValue('emp-nickname'),
    email:employeeFormValue('emp-email'),
    mobile:employeeFormValue('emp-mobile'),
    department:employeeFormValue('emp-department','Management'),
    designation:employeeFormValue('emp-designation','Employee'),
    supervisor:employeeFormValue('emp-supervisor',''),
    shift_hours_type:employeeFormValue('emp-shift-hours-type','weekly'),
    shift_hours:parseAmount(employeeFormValue('emp-shift-hours','0'))||0,
    salary:parseAmount(employeeFormValue('emp-salary','0')),
    housing_allowance:parseAmount(employeeFormValue('emp-housing-allowance','0'))||0,
    transport_allowance:parseAmount(employeeFormValue('emp-transport-allowance','0'))||0,
    other_allowance:parseAmount(employeeFormValue('emp-other-allowance','0'))||0,
    contract:employeeFormValue('emp-contract','Full-Time'),
    location:employeeFormValue('emp-location',''),
    branch:employeeFormValue('emp-branch',''),
    // Real Branch row id, looked up by name from the live _branchList (not
    // stored as the <select>'s value — that select is shared with the
    // free-text #emp-location/#req-location fields via _syncBranchSelects,
    // so its value is the branch NAME, not an id). Empty when the selected
    // name doesn't match any real Branch (e.g. no branches created yet).
    branch_id:(typeof _branchList!=='undefined'?_branchList.find(b=>b.name===employeeFormValue('emp-branch','')):null)?.id||'',
    role_id:employeeFormValue('emp-role'),
    role_name:(()=>{const rid=employeeFormValue('emp-role');const r=_hrRolesCache.find(x=>x.id===rid);return r?r.role_name:'';})(),
    cost_center:employeeFormValue('emp-cost-center'),
    // The Edit modal has no Status field at all, so this used to hardcode
    // 'Active' on every single save — editing an Inactive employee (e.g.
    // just to fix a phone number) silently flipped them back to Active.
    // Preserve whatever status the row already had when editing; only a
    // genuinely new employee defaults to Active.
    status:(()=>{
      if(!isEdit)return 'Active';
      const empId=employeeFormValue('emp-id','');
      const existingRow=[...document.querySelectorAll('#employee-tbody tr')].find(row=>{
        try{return JSON.parse(row.dataset.employee||'{}').id===empId;}catch{return false;}
      });
      if(!existingRow)return 'Active';
      try{return JSON.parse(existingRow.dataset.employee).status||'Active';}catch{return 'Active';}
    })(),
    created_at:new Date().toISOString(),
    emirates_id:employeeFormValue('emp-emirates-id'),
    nationality:employeeFormValue('emp-nationality'),
    dob:employeeFormValue('emp-dob'),
    gender:employeeFormValue('emp-gender'),
    marital_status:employeeFormValue('emp-marital'),
    address:employeeFormValue('emp-address'),
    join_date:employeeFormValue('emp-join-date'),
    overtime_rate:employeeFormValue('emp-ot-rate'),
    leave_policy:employeeFormValue('emp-leave-policy'),
    emergency_contact:employeeFormValue('emp-emergency'),
    emergency_mobile:employeeFormValue('emp-emergency-mobile'),
    work_permit_no:employeeFormValue('emp-work-permit'),
    visa_expiry:employeeFormValue('emp-visa-expiry'),
    passport_no:employeeFormValue('emp-passport-no'),
    passport_expiry:employeeFormValue('emp-passport-expiry'),
    eid_expiry:employeeFormValue('emp-eid-expiry'),
    labor_card:employeeFormValue('emp-labor-card'),
    labor_card_expiry:employeeFormValue('emp-labor-card-expiry'),
    driving_license:employeeFormValue('emp-driving-license'),
    driving_expiry:employeeFormValue('emp-driving-expiry'),
    insurance_type:employeeFormValue('emp-insurance-type'),
    insurance_policy:employeeFormValue('emp-insurance-policy'),
    insurance_expiry:employeeFormValue('emp-insurance-expiry'),
    salary_bank:employeeFormValue('emp-bank'),
    iban:employeeFormValue('emp-iban'),
    personal_code:employeeFormValue('emp-personal-code'),
    routing_code:employeeFormValue('emp-routing-code'),
    photo:photoPreview,
    documents:{
      passport:passportFile?.name||'',
      work_permit:workPermitFile?.name||'',
      other:medicalFile?.name||''
    }
  };
  if(!employee.name){
    toast('Enter employee name','warn');
    return;
  }
  renderEmployeeRecord(employee);
  renderPayrollEmployeeRecord(employee);
  saveServer('employees',employee);
  closeM('m-emp');
  document.querySelectorAll('#m-emp input').forEach(inp=>{if(inp.type!=='file')inp.value='';});
  document.querySelectorAll('#m-emp select').forEach(sel=>sel.selectedIndex=0);
  document.querySelectorAll('#m-emp textarea').forEach(ta=>ta.value='');
  const photoEl=document.getElementById('emp-photo-preview');
  if(photoEl)photoEl.innerHTML='<svg viewBox="0 0 24 24" width="30" height="30" fill="none" stroke="var(--text3)" stroke-width="1.4"><circle cx="12" cy="8" r="4"/><path d="M4 20c0-4 3.6-7 8-7s8 3 8 7"/></svg>';
  // Reset modal title back to Add for next use
  const titleEl=document.querySelector('#m-emp .modal-title');
  const subEl=document.querySelector('#m-emp .modal-sub');
  const btnEl=document.querySelector('#m-emp .btn-p');
  if(titleEl)titleEl.textContent='Add Employee';
  if(subEl)subEl.textContent='Register new employee details';
  if(btnEl)btnEl.textContent='Add Employee';
  toast(isEdit?`${employee.name} updated`:'Employee added to table','ok');
  audit(isEdit?'Updated employee':'Created employee',employee.id,'Saved');
}

// Numeric-aware sort key for an employee id: pulls out the first run of
// digits so "52" and "EMP-012" both sort on their number (52, 12) rather
// than as plain strings (which would put "EMP-012" before "52" — and "10"
// before "2" — regardless of magnitude). Ids with no digits at all sort
// last rather than first.
function _employeeIdSortValue(id){
  const m=String(id||'').match(/\d+/);
  return m?parseInt(m[0],10):Infinity;
}

// [statusRank, idValue] — Inactive employees always sort after every Active
// one (statusRank 1 vs 0), by request, rather than being interleaved with
// Active staff purely by Employee No. Within each status group, still
// numeric-aware ascending by id.
function _employeeSortKey(status,id){
  return [String(status||'Active').trim()==='Inactive'?1:0,_employeeIdSortValue(id)];
}

// A role without employees:view_salary -- called once from
// applyHrmsPermissionNav() (hrms.html) once window.HRMS_CAN_VIEW_SALARY
// is known. Toggles the Employee Directory's Salary column (CSS, see
// styles.css .hide-salary-col) and hides the Add/Edit Employee modal's
// salary/allowance inputs so they can't even be typed into -- the actual
// enforcement is server-side (app_data.py's _redact_employee_salary and
// the write-side guard in sync_domain_model()), this is presentation only.
function applyHrmsSalaryVisibility(){
  const hide=window.HRMS_CAN_VIEW_SALARY===false;
  const table=document.getElementById('employee-directory-table');
  if(table)table.classList.toggle('hide-salary-col',hide);
  const salaryFg=document.getElementById('emp-salary')?.closest('.fg');
  if(salaryFg)salaryFg.style.display=hide?'none':'';
  const allowanceRow=document.getElementById('emp-housing-allowance')?.closest('.fr3');
  if(allowanceRow)allowanceRow.style.display=hide?'none':'';
}

// Employee Directory shows Inactive employees by default, sunk to the bottom
// of the list (see _employeeSortKey) rather than interleaved with Active
// staff -- someone who's left should still be visible/reachable (Activate,
// CSV export, search) without hunting for a checkbox. The "Show Inactive"
// checkbox (checked by default) can be unchecked to hide them entirely, e.g.
// department-scoped managers wanting a "who's actually here" view. Routed
// through setTableExternalFilter() like Candidates' stage filter, so it
// survives typing in the search box and Prev/Next -- a plain row.style.display
// toggle would be undone by either.
function applyEmployeeInactiveFilter(){
  const table=document.getElementById('employee-directory-table');
  if(!table)return;
  enhanceTable(table); // idempotent -- ensures tableEnhanceState exists before the filter is set
  const showInactive=!!document.getElementById('emp-show-inactive')?.checked;
  setTableExternalFilter(table,showInactive?null:(tr=>tr.dataset.status!=='Inactive'));
}

function renderEmployeeRecord(employee){
  const tbody=document.getElementById('employee-tbody');
  if(!tbody)return;
  const [sortRank,sortId]=_employeeSortKey(employee.status,employee.id);
  // Dedup + sorted-insertion-point used to be TWO separate JS scans over
  // every row, each calling JSON.parse(row.dataset.employee) per row to
  // read the id/status back out -- an O(n) scan with real parsing cost,
  // done TWICE, once per employee during bootstrap hydration (so O(n^2)
  // total: ~90,000 JSON.parse calls for a 300-employee company, one of the
  // causes of HRMS's multi-second load freeze, see the isHydratingFromServer
  // fix above this function). One querySelectorAll + one pass now finds
  // both the row to remove and the insertion point together, comparing
  // plain attributes (set below) instead of parsing JSON per row.
  const employeeIdStr=String(employee.id);
  let existing=null,nextSibling=null;
  for(const r of tbody.querySelectorAll('tr')){
    if(r.dataset.employeeId===employeeIdStr){existing=r;continue;}
    if(nextSibling||r.dataset.emptyState)continue;
    const rRank=Number(r.dataset.sortRank??1);
    const rId=Number(r.dataset.sortId??Infinity);
    if(rRank>sortRank||(rRank===sortRank&&rId>sortId))nextSibling=r;
  }
  if(existing)existing.remove();
  const row=document.createElement('tr');
  row.dataset.employee=JSON.stringify(employee);
  row.dataset.employeeId=employeeIdStr;
  // Plain attribute (not another JSON.parse(row.dataset.employee)) so the
  // "Show Inactive" filter (applyEmployeeInactiveFilter()) can test every
  // row cheaply — same reasoning as employeeId/sortRank/sortId above.
  row.dataset.status=employee.status||'Active';
  row.dataset.sortRank=sortRank;
  row.dataset.sortId=sortId;
  row.innerHTML=`
    <td class="mono">${escapeHtml(employee.id)}</td>
    <td><div class="flx"><div class="co-av" style="width:26px;height:26px;font-size:10px${employee.photo?';padding:0;overflow:hidden':''}">${employee.photo?`<img src="${employee.photo}" style="width:100%;height:100%;object-fit:cover">`:escapeHtml(initialsFromName(employee.name))}</div><div>${escapeHtml(employee.name)}<div class="card-sub">${escapeHtml(employee.contract||'Full-time')} · ${escapeHtml(employee.location||'—')}</div></div></div></td>
    <td>${employee.nickname?escapeHtml(employee.nickname):'<span style="color:var(--text3)">—</span>'}</td>
    <td>${escapeHtml(employee.department)}</td>
    <td>${escapeHtml(employee.designation)}</td>
    <td>${escapeHtml(employee.supervisor)}</td>
    <td>${(()=>{const h=Number(employee.shift_hours||0);if(h>0){const t=(employee.shift_hours_type||'weekly');const label=t.charAt(0).toUpperCase()+t.slice(1)+' · '+h+'h';return `<span class="b b-b">${escapeHtml(label)}</span>`;}return employee.shift?`<span class="b b-b">${escapeHtml(employee.shift)}</span>`:'<span style="color:var(--text3)">—</span>';})()}</td>
    <td class="mono">${window.HRMS_CAN_VIEW_SALARY===false?'—':Number(employee.salary||0).toLocaleString('en-AE',{minimumFractionDigits:0,maximumFractionDigits:0})}</td>
    <td><span class="b ${employee.status==='Inactive'?'b-gray':'b-g'}">${escapeHtml(employee.status||'Active')}</span></td>
    <td data-action-col="1"><div class="row-actions"><button class="btn btn-g btn-sm" onclick="openEmployeeProfile(this)">View</button> <button class="icon-btn edit" type="button" title="Edit" onclick="editEmployeeFromRow(this)">${editIconSvg()}</button> <button class="btn btn-g btn-sm" onclick="toggleEmployeeStatusFromRow(this)">${employee.status==='Inactive'?'Activate':'Deactivate'}</button></div></td>`;
  // Employee Directory is kept sorted by Employee No. ascending (numeric-
  // aware) rather than newest-added-first — tbody.prepend() previously put
  // whichever employee was most recently created/edited at the very top
  // regardless of their actual number. Inactive employees are additionally
  // sunk below every Active one (see _employeeSortKey) rather than being
  // interleaved by number with active staff — toggling an employee to
  // Inactive re-inserts their row here too, so Deactivate immediately moves
  // them down instead of leaving them in their old numeric position.
  // nextSibling was already found above, in the same pass as the dedup check.
  if(nextSibling)tbody.insertBefore(row,nextSibling);
  else tbody.appendChild(row);
  const table=tbody.closest('table');
  const state=tableEnhanceState.get(table);
  if(state){
    state.query='';
    state.page=1;
    if(state.search)state.search.value='';
  }
  row.style.display='';
  row.hidden=false;
  // refreshEnhancedTable() re-scans EVERY row in the table (search filter +
  // pagination + the "DB records: N" counter) on every call -- fine for one
  // ad-hoc edit, but this function also runs once per employee during
  // bootstrap hydration (hydrateFromServer()'s renderRecordList loop), so
  // an unconditional call here made populating the Employee Directory
  // O(n^2) in the employee count: a 300-employee company was doing ~45,000
  // row touches just to build this one table, before even considering the
  // same problem in renderPayrollEmployeeRecord() below and the two O(n)
  // dedup/sort-position scans earlier in this function. Same fix already
  // applied to Item Master's renderProductRecord() for the same reason --
  // skip it mid-hydration, and hydrateFromServer() calls it once at the
  // end instead (see the renderRecordList(...,'employee') call site).
  if(!isHydratingFromServer)refreshEnhancedTable(table);
}

function editEmployeeFromRow(btn){
  const row=btn.closest('tr');
  if(!row)return;
  let emp={};
  try{emp=JSON.parse(row.dataset.employee||'{}');}catch{}
  if(!emp.id)emp=employeeFromDirectoryRow(row);
  openEmpEdit(emp);
}

// Delete was replaced with a status toggle per direct request — an
// employee's history (payroll, leave, attendance) shouldn't disappear just
// because they've left; Inactive keeps the record while excluding them
// from active-staff lists elsewhere (payroll run, rota, etc. already key
// off employee.status).
function toggleEmployeeStatusFromRow(btn){
  const row=btn.closest('tr');
  if(!row)return;
  let emp={};
  try{emp=JSON.parse(row.dataset.employee||'{}');}catch{}
  if(!emp.id)emp=employeeFromDirectoryRow(row);
  const newStatus=emp.status==='Inactive'?'Active':'Inactive';
  emp.status=newStatus;
  renderEmployeeRecord(emp);
  if(typeof renderPayrollEmployeeRecord==='function')renderPayrollEmployeeRecord(emp);
  saveServer('employees',emp);
  toast(`${emp.name||'Employee'} marked ${newStatus}`,'ok');
  audit('Employee status changed',emp.id||'',newStatus);
}

function employeeFromDirectoryRow(row){
  if(!row)return {};
  if(row.dataset.employee){
    try{return JSON.parse(row.dataset.employee);}catch{}
  }
  const cells=row.children;
  const nameCell=cells[1];
  const nameBlock=nameCell?.querySelector('.flx > div:last-child');
  const sub=nameCell?.querySelector('.card-sub')?.textContent||'';
  const fallbackName=(nameBlock?.textContent||nameCell?.textContent||'Employee').replace(sub,'').trim();
  const parts=sub.split('·').map(part=>part.trim());
  return {
    id:cells[0]?.textContent.trim()||'',
    name:fallbackName||'Employee',
    contract:parts[0]||'Full-time',
    location:parts[1]||'',
    nickname:cells[2]?.textContent.trim()||'',
    department:cells[3]?.textContent.trim()||'-',
    designation:cells[4]?.textContent.trim()||'-',
    supervisor:cells[5]?.textContent.trim()||'-',
    shift:cells[6]?.textContent.trim()||'-',
    salary:parseAmount(cells[7]?.textContent),
    status:cells[8]?.textContent.trim()||'Active',
    documents:{}
  };
}

function ensureEmployeeProfileModal(){
  let overlay=document.getElementById('m-employee-profile');
  if(overlay)return overlay;
  overlay=document.createElement('div');
  overlay.className='overlay';
  overlay.id='m-employee-profile';
  overlay.onclick=e=>closeOvBg(e,'m-employee-profile');
  overlay.innerHTML=`
    <div class="modal modal-xl">
      <div class="modal-title" id="employee-profile-title">Employee Profile</div>
      <div class="modal-sub" id="employee-profile-sub">Employee directory detail</div>
      <div id="employee-profile-body"></div>
      <div class="modal-foot">
        <button class="btn btn-p" id="emp-profile-edit-btn" onclick="">Edit Profile</button>
        <button class="btn btn-g" onclick="toast('Employee document checklist exported','ok')">Export Documents</button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
  return overlay;
}

function employeeDocumentBadge(label,fileName){
  const available=Boolean(fileName);
  return `<div class="setting-tile"><strong>${escapeHtml(label)}</strong><p>${available?escapeHtml(fileName):'Not uploaded'}</p><span class="b ${available?'b-g':'b-a'}">${available?'Stored':'Missing'}</span></div>`;
}

