function audit(action,record='System',result='Logged'){
  // Previously hardcoded 'System User' for every single call, on every
  // page, for every real user — no audit entry anywhere ever recorded who
  // actually did it. taxflow_user_display_name is set by applyRoleBasedNav()
  // (index.html/admin) or applyHrmsPermissionNav() (hrms.html/either
  // principal kind), whichever loaded first on this page.
  const displayUser=localStorage.getItem('taxflow_user_display_name')||'Unknown User';
  const entry={time:new Date().toLocaleString('en-AE',{dateStyle:'short',timeStyle:'short'}),user:displayUser,action,record,result};
  debouncedSaveServer('audit',entry,300);
  renderAuditLog([entry]);
}

function renderAuditLog(entries=[]){
  const tbody=document.getElementById('audit-tbody');
  if(!tbody||entries.length===0)return;
  tbody.querySelectorAll('[data-audit-dynamic]').forEach(row=>row.remove());
  const template=document.createElement('tbody');
  template.innerHTML=entries.map(entry=>`<tr data-audit-dynamic><td class="mono">${escapeHtml(entry.time)}</td><td>${escapeHtml(entry.user)}</td><td>${escapeHtml(entry.action)}</td><td>${escapeHtml(entry.record)}</td><td><span class="b b-g">${escapeHtml(entry.result)}</span></td></tr>`).join('');
  [...template.children].reverse().forEach(row=>tbody.prepend(row));
}

function persistSalesInvoice(inv,options={}){
  // Stamped once, here — not in buildDraftInvoice(), which rebuilds on
  // every form edit for the live preview and would re-stamp on every
  // keystroke. Only set if missing, so re-saving/editing an invoice that
  // already has one doesn't overwrite its real creation time. This is also
  // what the ZATCA QR code (invoiceQrValue -> zatcaQrValue) uses for its
  // required timestamp field — previously invoices carried no time
  // component at all, only a date.
  if(!inv.created_at)inv.created_at=new Date().toISOString();
  // createOnly for a new number: the server refuses one already used by any
  // saved invoice, including ones not on the register's current page.
  return saveServer('salesInvoices',inv,{throwOnError:true,createOnly:!!options.createOnly})
    .then(()=>'saved')
    .catch(err=>err?.status===409?'duplicate':'failed');
}

