// ── POS Receipt Design — a deliberately trimmed-down sibling of the full
// Invoice Design Layout above: a POS receipt is printed on an 80mm/58mm
// thermal roll, not A4, so most Invoice Design fields (payment terms, bank
// details, bilingual labels, signatures...) don't apply. A fixed `id` (not
// a per-record key like invoiceLayout's "company") keeps this a true
// singleton — one row upserted in place, never a growing list to pick the
// "latest" from.
function defaultPosReceiptSettings(){
  return {
    id:'pos-receipt-settings',
    company:'',
    companyAr:'',
    address:'',
    addressAr:'',
    phone:'',
    heading:'Tax Invoice | فاتورة ضريبية',
    vatLabel:'VAT | الرقم الضريبي',
    vatNumber:'',
    showLogo:false,
    showTrn:true,
    footer:'Thank you for your business',
    showQr:true,
    paperWidth:'80mm'
  };
}

// "English | Arabic" pairs — same convention Invoice Design already uses
// for its own bilingual labels (inv-layout-heading-label etc.) — so a
// receipt can print a Saudi-style "Simplified Tax Invoice | فاتورة ضريبية
// مبسطة" heading or a custom VAT ID label without a second, parallel field.
function splitBilingualLabel(value,fallback){
  const raw=String(value||fallback||'').split('|');
  return {en:(raw[0]||'').trim(),ar:(raw[1]||'').trim()};
}

let savedPosReceiptSettings=defaultPosReceiptSettings();

function setPosReceiptDesignFields(record={}){
  savedPosReceiptSettings={...defaultPosReceiptSettings(),...record};
  const s=savedPosReceiptSettings;
  const set=(id,value)=>{const el=document.getElementById(id);if(el)el.value=value||'';};
  set('pos-rcpt-company',s.company);
  set('pos-rcpt-company-ar',s.companyAr);
  set('pos-rcpt-address',s.address);
  set('pos-rcpt-address-ar',s.addressAr);
  set('pos-rcpt-phone',s.phone);
  set('pos-rcpt-heading',s.heading);
  set('pos-rcpt-vat-label',s.vatLabel);
  set('pos-rcpt-vat-number',s.vatNumber);
  set('pos-rcpt-footer',s.footer);
  const showLogo=document.getElementById('pos-rcpt-show-logo');if(showLogo)showLogo.checked=Boolean(s.showLogo);
  const showTrn=document.getElementById('pos-rcpt-show-trn');if(showTrn)showTrn.checked=s.showTrn!==false;
  const showQr=document.getElementById('pos-rcpt-show-qr');if(showQr)showQr.checked=s.showQr!==false;
  const paper=document.getElementById('pos-rcpt-paper');if(paper)paper.value=s.paperWidth||'80mm';
}

function readPosReceiptDesignFields(){
  const base=savedPosReceiptSettings||defaultPosReceiptSettings();
  const val=id=>document.getElementById(id)?.value;
  return {
    id:'pos-receipt-settings',
    company:(val('pos-rcpt-company')||'').trim(),
    companyAr:(val('pos-rcpt-company-ar')||'').trim(),
    address:(val('pos-rcpt-address')||'').trim(),
    addressAr:(val('pos-rcpt-address-ar')||'').trim(),
    phone:(val('pos-rcpt-phone')||'').trim(),
    heading:(val('pos-rcpt-heading')||'').trim()||base.heading,
    vatLabel:(val('pos-rcpt-vat-label')||'').trim()||base.vatLabel,
    vatNumber:(val('pos-rcpt-vat-number')||'').trim(),
    showLogo:document.getElementById('pos-rcpt-show-logo')?.checked??base.showLogo,
    showTrn:document.getElementById('pos-rcpt-show-trn')?.checked??base.showTrn,
    footer:(val('pos-rcpt-footer')||'').trim(),
    showQr:document.getElementById('pos-rcpt-show-qr')?.checked??base.showQr,
    paperWidth:val('pos-rcpt-paper')||base.paperWidth||'80mm'
  };
}

function updatePosReceiptPreview(){
  const preview=document.getElementById('pos-receipt-preview');
  if(!preview)return;
  const s=readPosReceiptDesignFields();
  const width=s.paperWidth==='58mm'?'150px':'200px';
  const heading=splitBilingualLabel(s.heading,'Tax Invoice | فاتورة ضريبية');
  const vatLabel=splitBilingualLabel(s.vatLabel,'VAT | الرقم الضريبي');
  preview.innerHTML=`
    <div style="background:#fff;color:#111;font-family:'DM Mono',monospace;font-size:11px;line-height:1.6;width:${width};margin:0 auto;padding:14px 10px;border-radius:4px;box-shadow:0 1px 4px rgba(0,0,0,.15)">
      ${s.showLogo?`<div style="text-align:center;font-size:20px;margin-bottom:4px">🧾</div>`:''}
      <div style="text-align:center;font-weight:700">${escapeHtml(s.company||currentCompany?.name||'Your Company')}</div>
      ${s.companyAr?`<div style="text-align:center;font-weight:700" dir="rtl">${escapeHtml(s.companyAr)}</div>`:''}
      ${s.address?`<div style="text-align:center;color:#555">${escapeHtml(s.address)}</div>`:''}
      ${s.addressAr?`<div style="text-align:center;color:#555" dir="rtl">${escapeHtml(s.addressAr)}</div>`:''}
      ${s.phone?`<div style="text-align:center;color:#555">${escapeHtml(s.phone)}</div>`:''}
      <div style="text-align:center;font-size:10px;color:#888;margin-top:2px">${escapeHtml(heading.en)}${heading.ar?' / '+escapeHtml(heading.ar):''}</div>
      ${s.showTrn?`<div style="text-align:center;color:#555">${escapeHtml(vatLabel.en)}${vatLabel.ar?' / '+escapeHtml(vatLabel.ar):''}: ${escapeHtml(s.vatNumber||currentCompany?.trn||'not set')}</div>`:''}
      <div style="border-top:1px dashed #999;margin:8px 0"></div>
      <div style="display:flex;justify-content:space-between"><span>1x Sample Item</span><span>25.00</span></div>
      <div style="display:flex;justify-content:space-between;color:#555"><span>VAT</span><span>1.25</span></div>
      <div style="border-top:1px dashed #999;margin:8px 0"></div>
      <div style="display:flex;justify-content:space-between;font-weight:700"><span>TOTAL</span><span>26.25</span></div>
      ${s.showQr?`<div style="text-align:center;margin-top:8px;font-size:26px">▦</div>`:''}
      ${s.footer?`<div style="text-align:center;color:#555;margin-top:6px">${escapeHtml(s.footer)}</div>`:''}
    </div>`;
}

async function savePosReceiptDesign(){
  const settings=readPosReceiptDesignFields();
  try{
    await saveServer('posReceiptSettings',settings,{throwOnError:true});
    savedPosReceiptSettings=settings;
    updatePosReceiptPreview();
    toast('POS receipt design saved','ok');
    audit('Saved POS receipt design',settings.company||'POS Receipt','Saved');
  }catch(err){
    console.warn('POS receipt design save failed:',err);
    toast('POS receipt design could not be saved','err');
  }
}

function encodePublicInvoicePayload(payload){
  try{
    // URL-safe base64: replace + → - and / → _ so URLSearchParams and email clients don't mangle the hash
    return btoa(unescape(encodeURIComponent(JSON.stringify(payload))))
      .replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/g,'');
  }catch{
    return '';
  }
}

function publicInvoicePayload(inv=currentSalesInvoice){
  const layout=getInvoiceLayout();
  const labels=invoiceLabels(layout);
  const heading=salesDocumentHeading(inv,layout);
  const companyTrn=currentCompany?.trn||document.getElementById('set-company-trn')?.value||'';
  return {
    company:{
      name:layout.company,
      logo:layout.logo,
      trn:companyTrn,
      address:layout.address,
      bank:layout.bank,
      bankName:layout.bankName,
      accountName:layout.accountName,
      accountNumber:layout.accountNumber,
      iban:layout.iban,
      swiftCode:layout.swiftCode,
      paymentLink:layout.paymentLink,
      footer:layout.footer,
      color:layout.color,
      taxLabel:heading,
      trnLabel:layout.trnLabel,
      customerTrnLabel:layout.customerTrnLabel,
      enableRtl:layout.enableRtl,
      enableArabic:invoiceUsesArabic(layout),
      language:layout.language
    },
    invoice:{
      invoice_no:inv?.invoice_no||'Draft',
      status:inv?.status||'Draft',
      customer:inv?.customer||'Customer',
      customer_trn:inv?.customer_trn||'TRN not provided',
      customer_address:inv?.customer_address||document.getElementById('inv-caddr')?.value||'',
      po_number:inv?.po_number||'',
      delivery_note_no:inv?.delivery_note_no||'',
      reference_no:inv?.reference_no||'',
      salesperson:inv?.salesperson||'',
      date:inv?.date||'',
      due_date:inv?.due_date||'',
      subtotal:Number(inv?.subtotal||0),
      vat_amount:Number(inv?.vat_amount||0),
      total:Number(inv?.total||0),
      terms:layout.terms,
      labels:{
        heading,
        billTo:labels.billTo,
        issueDate:labels.issueDate,
        dueDate:labels.dueDate,
        paymentTerms:labels.paymentTerms,
        currency:labels.currency,
        product:labels.product,
        unit:labels.unit,
        quantity:labels.quantity,
        unitPrice:labels.unitPrice,
        taxable:labels.taxable,
        vat:labels.vat,
        vatAmount:labels.vatAmount,
        amount:labels.amount,
        subtotal:labels.subtotal,
        total:labels.total,
        balanceDue:labels.balanceDue,
        purchaseOrder:labels.purchaseOrder,
        deliveryNote:labels.deliveryNote,
        reference:labels.reference,
        paymentDetails:labels.paymentDetails,
        digitalGenerated:labels.digitalGenerated
      },
      lines:inv?.lines||[]
    }
  };
}

function publicInvoiceUrl(inv=currentSalesInvoice){
  const payload=encodePublicInvoicePayload(publicInvoicePayload(inv));
  const url=new URL('/digital-invoice.html',window.location.origin);
  url.hash='invoice='+payload;
  return url.toString();
}

// ZATCA (Saudi Arabia) Phase 1 simplified-invoice QR — TLV (Tag-Length-Value)
// byte sequence, Base64-encoded. Five tags in order: 1=seller name,
// 2=VAT registration number, 3=invoice timestamp, 4=invoice total (incl.
// VAT), 5=VAT total. Each field is [1-byte tag][1-byte UTF-8 length][UTF-8
// value bytes]. This is the structural "Generation phase" QR — no
// cryptographic signing (that's ZATCA Phase 2, a separate government
// integration, not attempted here).
function zatcaTlvField(tag,value){
  // TextEncoder, not value.length — JS string .length counts UTF-16 code
  // units, not bytes, which is wrong for non-ASCII (Arabic seller names are
  // the normal case here) and would desync every tag after a multi-byte one.
  const valueBytes=new TextEncoder().encode(String(value==null?'':value));
  if(valueBytes.length>255){
    // TLV length is a single byte (0-255) per spec — truncate rather than
    // overflow into a byte that would be misread as part of the next tag.
    // Only realistically reachable for an unusually long seller name.
    return zatcaTlvField(tag,new TextDecoder().decode(valueBytes.slice(0,255)));
  }
  const field=new Uint8Array(2+valueBytes.length);
  field[0]=tag;
  field[1]=valueBytes.length;
  field.set(valueBytes,2);
  return field;
}

function zatcaQrValue(inv,layout){
  const sellerName=layout?.company||currentCompany?.name||'';
  // Same 15-digit registration-number field UAE's TRN uses — ZATCA calls it
  // a VAT number, not a rename of the underlying data.
  const vatNumber=currentCompany?.trn||document.getElementById('set-company-trn')?.value||'';
  if(!vatNumber&&!window.__taxflowZatcaTrnWarned){
    window.__taxflowZatcaTrnWarned=true;
    toast('ZATCA QR code is missing the VAT number — add your company TRN in Settings','warn');
  }
  // inv.created_at (stamped once at save time, see persistSalesInvoice())
  // carries real time-of-day; older records that predate that stamp only
  // have a date, so midnight UTC is used as a documented approximation
  // rather than leaving the required timestamp field empty.
  const timestamp=inv?.created_at||`${inv?.date||new Date().toISOString().slice(0,10)}T00:00:00Z`;
  const total=Number(inv?.total||0).toFixed(2);
  const vatTotal=Number(inv?.vat_amount||0).toFixed(2);

  const fields=[
    zatcaTlvField(1,sellerName),
    zatcaTlvField(2,vatNumber),
    zatcaTlvField(3,timestamp),
    zatcaTlvField(4,total),
    zatcaTlvField(5,vatTotal),
  ];
  const totalLength=fields.reduce((sum,f)=>sum+f.length,0);
  const bytes=new Uint8Array(totalLength);
  let offset=0;
  fields.forEach(f=>{bytes.set(f,offset);offset+=f.length;});

  // Binary-safe base64: map each byte 1:1 to a char code before btoa(),
  // rather than btoa() on a JS string directly, which assumes one
  // UTF-16 code unit per byte and corrupts anything non-ASCII.
  let binary='';
  bytes.forEach(b=>{binary+=String.fromCharCode(b);});
  return btoa(binary);
}

function invoiceQrValue(inv=currentSalesInvoice,layout=getInvoiceLayout()){
  if(layout.qrCodeType==='zatca_qr'){
    return zatcaQrValue(inv,layout);
  }
  if(layout.qrCodeType==='uae_vat_qr'){
    const companyTrn=currentCompany?.trn||document.getElementById('set-company-trn')?.value||'';
    return [
      layout.company,
      companyTrn,
      inv?.date||new Date().toISOString().slice(0,10),
      Number(inv?.total||0).toFixed(2),
      Number(inv?.vat_amount||0).toFixed(2)
    ].join('|');
  }
  return publicInvoiceUrl(inv);
}

function qrCodeFallbackImageUrl(value){
  return `https://api.qrserver.com/v1/create-qr-code/?size=180x180&margin=10&data=${encodeURIComponent(value)}`;
}

function renderInvoiceQrCode(value,imgId='public-invoice-qr'){
  const img=document.getElementById(imgId);
  if(!img)return;
  const fallback=qrCodeFallbackImageUrl(value);
  if(window.TaxFlowQRCode?.toDataURL){
    window.TaxFlowQRCode.toDataURL(value,{width:180,margin:1,color:{dark:'#172033',light:'#ffffff'}})
      .then(src=>{img.src=src;})
      .catch(()=>{img.src=fallback;});
    return;
  }
  img.src=fallback;
}

async function openCurrentPublicInvoice(){
  const inv=currentSalesInvoice||buildDraftInvoice();
  const url=await createShortInvoiceUrl(inv);
  const w=window.open(url,'_blank');
  if(!w){
    const link=document.getElementById('share-link');
    if(link)link.value=url;
    navigator.clipboard?.writeText(url);
    toast('Popup blocked — link copied. Paste it in a new tab.','warn');
  }
}

function currentInvoiceForShare(){
  return currentSalesInvoice||buildDraftInvoice();
}

function invoicePdfHtml(inv=currentInvoiceForShare()){
  const payload=publicInvoicePayload(inv);
  const company=payload.company||{};
  const invoice=payload.invoice||{};
  const labels=invoice.labels||{};
  const lines=Array.isArray(invoice.lines)&&invoice.lines.length?invoice.lines:[{description:'Invoice items',unit:'PCS',qty:1,price:invoice.subtotal,amount:invoice.subtotal}];
  const initials=String(company.logo||company.name||'TF').split(/\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase()||'TF';
  const fmt=n=>Number(n||0).toLocaleString('en-AE',{minimumFractionDigits:2,maximumFractionDigits:2});
  const accent=escapeHtml(company.color||'#2563eb');
  return `<!doctype html><html><head><meta charset="utf-8"><title>${escapeHtml(invoice.invoice_no||'Invoice')} - PDF</title>
    <style>
      *{box-sizing:border-box}body{margin:0;background:#fff;color:#172033;font-family:Arial,Helvetica,sans-serif;font-size:13px;line-height:1.45}.sheet{max-width:900px;margin:0 auto;padding:34px}.bar{height:7px;background:${accent};margin:-34px -34px 28px}.head{display:grid;grid-template-columns:1fr 280px;gap:24px;border-bottom:1px solid #e5eaf2;padding-bottom:22px}.brand{display:flex;gap:14px}.logo{width:58px;height:58px;border-radius:12px;background:${accent};color:#fff;display:grid;place-items:center;font-size:20px;font-weight:800}.company{font-size:22px;font-weight:800}.muted{color:#667085;font-size:12px;margin-top:3px}.right{text-align:right}.label{font-size:30px;font-weight:900;text-transform:uppercase}.badge{display:inline-block;margin-top:8px;border:1px solid #d8e2ff;color:${accent};border-radius:999px;padding:4px 10px;font-size:11px;font-weight:700;text-transform:uppercase}.grid{display:grid;grid-template-columns:1fr 280px;gap:16px;margin:22px 0}.panel{border:1px solid #e5eaf2;border-radius:8px;padding:14px}.kicker{font-size:10px;text-transform:uppercase;letter-spacing:.8px;color:#667085;font-weight:700;margin-bottom:7px}.party{font-size:17px;font-weight:800}.row{display:flex;justify-content:space-between;gap:12px;color:#667085;padding:4px 0}.row strong{color:#172033;text-align:right}table{width:100%;border-collapse:collapse;border:1px solid #e5eaf2;border-radius:8px;overflow:hidden}th{background:#f3f6fb;color:#667085;text-transform:uppercase;font-size:10px;letter-spacing:.5px;text-align:left;padding:10px}td{padding:11px 10px;border-top:1px solid #e5eaf2}.num{text-align:right;white-space:nowrap}.summary{display:grid;grid-template-columns:1fr 300px;gap:20px;margin-top:22px}.notes{border-left:4px solid ${accent};padding-left:12px;color:#667085}.totals{border:1px solid #e5eaf2;border-radius:8px;padding:14px}.total,.grand{display:flex;justify-content:space-between;gap:14px}.total{color:#667085;padding:4px 0}.grand{border-top:1px solid #e5eaf2;margin-top:8px;padding-top:12px;font-size:19px;font-weight:900}.grand strong{color:${accent}}.link{margin-top:14px;font-size:11px;color:#667085;word-break:break-all}[dir=rtl] .right{text-align:left}[dir=rtl] th{text-align:right}[dir=rtl] .num{text-align:left}[dir=rtl] .notes{border-left:0;border-right:4px solid ${accent};padding-left:0;padding-right:12px}@media print{body{print-color-adjust:exact;-webkit-print-color-adjust:exact}.sheet{padding:24px}.bar{margin:-24px -24px 24px}.no-print{display:none}}
    </style></head><body><main class="sheet"><div class="bar"></div>
      <section class="head" dir="${company.enableRtl?'rtl':'ltr'}"><div class="brand">${_logoPdfHtml(initials)}<div><div class="company">${escapeHtml(company.name||'TaxFlow')}</div><div class="muted">${escapeHtml(company.address||'')}</div><div class="muted">${escapeHtml(company.trnLabel||'TRN')} ${escapeHtml(company.trn||'not set')}</div></div></div><div class="right"><div class="label">${escapeHtml(company.taxLabel||'Tax Invoice')}</div><div>${escapeHtml(invoice.invoice_no||'Draft')}</div><span class="badge">${escapeHtml(invoice.status||'Draft')}</span></div></section>
      <section class="grid" dir="${company.enableRtl?'rtl':'ltr'}"><div class="panel"><div class="kicker">${escapeHtml(labels.billTo||'Bill To')}</div><div class="party">${escapeHtml(invoice.customer||'Customer')}</div><div class="muted">${escapeHtml(company.customerTrnLabel||'Customer TRN')} ${escapeHtml(invoice.customer_trn||'not provided')}</div><div class="muted">${escapeHtml(invoice.customer_address||'')}</div></div><div class="panel"><div class="row"><span>${escapeHtml(labels.issueDate||'Issue Date')}</span><strong>${escapeHtml(invoice.date||'-')}</strong></div><div class="row"><span>${escapeHtml(labels.dueDate||'Due Date')}</span><strong>${escapeHtml(invoice.due_date||'-')}</strong></div><div class="row"><span>${escapeHtml(labels.paymentTerms||'Terms')}</span><strong>${escapeHtml(invoice.terms||'Net 30')}</strong></div><div class="row"><span>${escapeHtml(labels.currency||'Currency')}</span><strong>${AED_SYMBOL}</strong></div></div></section>
      <table dir="${company.enableRtl?'rtl':'ltr'}"><thead><tr><th>#</th><th>${escapeHtml(labels.product||'Product')}</th><th>${escapeHtml(labels.unit||'Unit')}</th><th class="num">${escapeHtml(labels.quantity||'Qty')}</th><th class="num">${escapeHtml(labels.unitPrice||'Unit Price')}</th><th class="num">${escapeHtml(labels.amount||'Amount')}</th></tr></thead><tbody>${lines.map((line,index)=>`<tr><td>${index+1}</td><td><strong>${escapeHtml(line.description||'Item')}</strong></td><td>${escapeHtml(line.unit||'PCS')}</td><td class="num">${escapeHtml(line.qty||1)}</td><td class="num">${fmt(line.price)}</td><td class="num">${fmt(line.amount)}</td></tr>`).join('')}</tbody></table>
      <section class="summary" dir="${company.enableRtl?'rtl':'ltr'}"><div class="notes"><div class="kicker">${escapeHtml(labels.paymentDetails||'Payment Details')}</div><div style="margin-top:8px">${escapeHtml(company.footer||'')}</div><div class="link">Online view: ${escapeHtml(_shortUrlCache.get(inv?.invoice_no||'draft')||publicInvoiceUrl(inv))}</div></div><div class="totals"><div class="total"><span>${escapeHtml(labels.subtotal||'Subtotal')}</span><strong>${AED_SYMBOL} ${fmt(invoice.subtotal)}</strong></div><div class="total"><span>${escapeHtml(labels.vat||'VAT')}</span><strong>${AED_SYMBOL} ${fmt(invoice.vat_amount)}</strong></div><div class="grand"><span>${escapeHtml(labels.total||'Total')}</span><strong>${AED_SYMBOL} ${fmt(invoice.total)}</strong></div></div></section>
    </main><script>window.onload=()=>setTimeout(()=>window.print(),250);<\/script></body></html>`;
}

