    const res=await moduleApi('/ai/hr/attrition-risk',{method:'POST',body:{}});
    if(res.error){el.innerHTML=`<div style="font-size:11px;color:var(--red)">${escapeHtml(res.error)}</div>`;return;}
    const risks=(res.at_risk||[]).slice(0,3);
