    el.innerHTML=risks.map(r=>`<div class="hc-ai-row"><div class="hc-ai-name">${escapeHtml(r.name||r.employee||'')}</div><div class="hc-ai-pct" style="color:${(r.risk_score||0)>=80?'#ef4444':'#f59e0b'}">${r.risk_score||'—'}%</div></div>`).join('');
