// 1. CV Parser
async function hrmsAiCvParse(){
  const text=(document.getElementById('hrms-ai-cv-text')?.value||'').trim();
  if(!text){toast('Paste CV text first','warn');return;}
  _hrmsAiBtn('hrms-ai-cv-btn','Parse CV',true);
  _hrmsAiResultHtml('hrms-ai-cv-result','<div style="color:var(--text3);text-align:center;padding:20px">Extracting…</div>');
  try{
    const res=await moduleApi('/ai/hr/cv-parse',{method:'POST',body:{text}});
    if(res.error){_hrmsAiErrorHtml('hrms-ai-cv-result',res.error);return;}
    const fields=[
      ['Name',res.full_name],['Email',res.email],['Phone',res.phone],
      ['Nationality',res.nationality],['Visa',res.visa_type],
      ['Department',res.department_suggestion],['Designation',res.designation],
      ['Salary Suggestion',res.basic_salary_suggestion?currentCurrency()+' '+res.basic_salary_suggestion:'—'],
      ['Experience',res.years_experience?res.years_experience+' yrs':'—'],
      ['Skills',(res.skills||[]).slice(0,5).join(', ')],
      ['Languages',(res.languages||[]).join(', ')],
    ].filter(([,v])=>v).map(([k,v])=>`<div style="display:flex;justify-content:space-between;padding:3px 0;border-bottom:1px solid var(--border)"><span style="color:var(--text3)">${k}</span><strong style="color:var(--text);text-align:right;max-width:60%">${escapeHtml(String(v))}</strong></div>`).join('');
    const useBtn=`<button class="btn btn-p btn-sm" style="width:100%;margin-top:8px" onclick="hrmsAiCvFillForm(${jsonAttr(JSON.stringify(res))})">Use in Employee Form</button>`;
    _hrmsAiResultHtml('hrms-ai-cv-result',`<div>${fields}</div>${useBtn}`);
  }catch(e){_hrmsAiErrorHtml('hrms-ai-cv-result','AI call failed: '+e.message);}
  finally{_hrmsAiBtn('hrms-ai-cv-btn','Parse CV',false);}
}

function hrmsAiCvUpload(input){
  const file=input?.files?.[0];
  if(!file)return;
  const reader=new FileReader();
  reader.onload=e=>{
    const text=e.target?.result||'';
    const el=document.getElementById('hrms-ai-cv-text');
    if(el)el.value=typeof text==='string'?text:'[Binary file — paste text version instead]';
  };
  reader.readAsText(file);
}

function hrmsAiCvFillForm(jsonStr){
  if(!window.HRMS_STANDALONE){window.open('/hrms','_blank');return;}
  try{
    const data=JSON.parse(jsonStr);
    const field=(id,val)=>{const el=document.getElementById(id);if(el&&val)el.value=val;};
    const sel=(id,val)=>{const el=document.getElementById(id);if(el&&val)setSelectValue(el,val);};
    go('staff');
    setTimeout(()=>{
      openEmpModal();
      setTimeout(()=>{
        field('emp-name',data.full_name);
        field('emp-email',data.email);
        field('emp-phone',data.phone);
        field('emp-designation',data.designation);
        sel('emp-department',data.department_suggestion);
        field('emp-salary',data.basic_salary_suggestion||'');
        toast('CV data filled into employee form','ok');
      },300);
    },200);
  }catch{}
}

// 2. Payroll Anomaly Detector
async function hrmsAiPayrollAnomaly(){
  _hrmsAiBtn('hrms-ai-payroll-btn','Run Anomaly Scan',true);
  _hrmsAiResultHtml('hrms-ai-payroll-result','<div style="color:var(--text3)">Scanning payroll records from database…</div>');
  try{
    const res=await moduleApi('/ai/hr/payroll-anomaly',{method:'POST',body:{}});
    if(res.error){_hrmsAiErrorHtml('hrms-ai-payroll-result',res.error);return;}
    const anomalies=res.anomalies||[];
    const badges={High:'b-r',Medium:'b-a',Low:'b-g',Critical:'b-r'};
    const rows=anomalies.map(a=>`
      <div style="padding:8px;border:1px solid var(--border);border-radius:7px;margin-bottom:6px">
        <div style="display:flex;align-items:center;gap:6px;margin-bottom:4px">
          <strong style="font-size:12px">${escapeHtml(a.employee_name||a.employee_no||'—')}</strong>
          <span class="b ${badges[a.severity]||'b-a'}" style="font-size:10px">${escapeHtml(a.severity||'')}</span>
          <span class="b b-g" style="font-size:10px;margin-left:auto">${escapeHtml(a.type||'')}</span>
        </div>
        <div style="font-size:11.5px;color:var(--text2)">${escapeHtml(a.description||'')}</div>
        ${a.action?`<div style="font-size:11px;color:var(--accent);margin-top:3px">→ ${escapeHtml(a.action)}</div>`:''}
      </div>`).join('');
    const summary=`<div style="background:var(--bg2);border-radius:8px;padding:8px;margin-bottom:8px;font-size:12px">
      <div style="display:flex;gap:12px;flex-wrap:wrap;margin-bottom:4px">
        <span>Checked: <strong>${res.db_employees||0}</strong> employees</span>
        <span>Anomalies: <strong style="color:var(--red)">${anomalies.length}</strong></span>
        <span>Payroll records: <strong>${res.db_payroll_records||0}</strong></span>
      </div>
      <div style="color:var(--text2)">${escapeHtml(res.summary||'')}</div>
    </div>`;
    _hrmsAiResultHtml('hrms-ai-payroll-result',anomalies.length?summary+rows:`${summary}<div style="color:var(--green);font-size:12px;text-align:center;padding:8px">✓ No anomalies detected</div>`);
  }catch(e){_hrmsAiErrorHtml('hrms-ai-payroll-result','Scan failed: '+e.message);}
  finally{_hrmsAiBtn('hrms-ai-payroll-btn','Run Anomaly Scan',false);}
}

// 3. Attrition Risk Score
async function hrmsAiAttritionRisk(){
  _hrmsAiBtn('hrms-ai-attr-btn','Score All Employees',true);
  _hrmsAiResultHtml('hrms-ai-attr-result','<div style="color:var(--text3)">Scoring employees from database…</div>');
  try{
    const res=await moduleApi('/ai/hr/attrition-risk',{method:'POST',body:{}});
    if(res.error){_hrmsAiErrorHtml('hrms-ai-attr-result',res.error);return;}
    const scores=(res.scores||[]).sort((a,b)=>b.risk_score-a.risk_score);
    const riskColor={Critical:'var(--red)',High:'#f97316',Medium:'var(--amber)',Low:'var(--green)'};
    const rows=scores.map(s=>{
      const color=riskColor[s.risk_level]||'var(--text3)';
      const pct=Math.min(100,s.risk_score||0);
      return `<div style="padding:8px;border:1px solid var(--border);border-radius:7px;margin-bottom:6px">
        <div style="display:flex;align-items:center;gap:6px;margin-bottom:4px">
          <strong style="font-size:12px">${escapeHtml(s.name||s.employee_no||'—')}</strong>
          <span style="font-size:10.5px;color:var(--text3)">${escapeHtml(s.department||'')} · ${escapeHtml(s.designation||'')}</span>
          <span style="margin-left:auto;font-size:13px;font-weight:700;color:${color}">${pct}%</span>
        </div>
        <div style="height:4px;border-radius:2px;background:var(--bg3);margin-bottom:4px">
          <div style="height:4px;border-radius:2px;background:${color};width:${pct}%;transition:width .5s"></div>
        </div>
        ${(s.risk_factors||[]).length?`<div style="font-size:11px;color:var(--text3)">${s.risk_factors.map(f=>escapeHtml(f)).join(' · ')}</div>`:''}
      </div>`;
    }).join('');
    const summary=`<div style="background:var(--bg2);border-radius:8px;padding:8px;margin-bottom:8px;font-size:12px">
      <div style="display:flex;gap:12px;flex-wrap:wrap;margin-bottom:4px">
        <span style="color:var(--red)">Critical/High: <strong>${(res.high_risk_count||0)}</strong></span>
        <span style="color:var(--amber)">Medium: <strong>${(res.medium_risk_count||0)}</strong></span>
        <span style="color:var(--green)">Low: <strong>${(res.low_risk_count||0)}</strong></span>
      </div>
      <div style="color:var(--text2)">${escapeHtml(res.summary||'')}</div>
    </div>`;
    _hrmsAiResultHtml('hrms-ai-attr-result',summary+rows);
  }catch(e){_hrmsAiErrorHtml('hrms-ai-attr-result','Score failed: '+e.message);}
  finally{_hrmsAiBtn('hrms-ai-attr-btn','Score All Employees',false);}
}

// 4. UAE Compliance Check
async function hrmsAiComplianceCheck(){
  _hrmsAiBtn('hrms-ai-comp-btn','Run Compliance Audit',true);
  _hrmsAiResultHtml('hrms-ai-comp-result','<div style="color:var(--text3)">Checking compliance against UAE Labor Law…</div>');
  try{
    const res=await moduleApi('/ai/hr/compliance-check',{method:'POST',body:{}});
    if(res.error){_hrmsAiErrorHtml('hrms-ai-comp-result',res.error);return;}
    const issues=res.issues||[];
    const sevColor={Critical:'var(--red)',High:'#f97316',Medium:'var(--amber)',Low:'var(--green)'};
    const rows=issues.map(i=>`
      <div style="padding:8px;border-left:3px solid ${sevColor[i.severity]||'var(--border)'};background:var(--bg2);border-radius:0 7px 7px 0;margin-bottom:6px">
        <div style="display:flex;align-items:center;gap:6px;margin-bottom:3px">
          <strong style="font-size:12px">${escapeHtml(i.name||i.employee_no||'—')}</strong>
          <span class="b" style="font-size:10px;background:${sevColor[i.severity]||'var(--bg3)'}22;color:${sevColor[i.severity]||'var(--text3)'}">${escapeHtml(i.severity||'')}</span>
          <span style="font-size:10px;color:var(--text3);margin-left:auto">${escapeHtml(i.law_reference||'')}</span>
        </div>
        <div style="font-size:11.5px;color:var(--text)">${escapeHtml(i.description||'')}</div>
        ${i.recommended_action?`<div style="font-size:11px;color:var(--accent);margin-top:2px">→ ${escapeHtml(i.recommended_action)}</div>`:''}
      </div>`).join('');
    const score=res.overall_compliance_score||0;
    const scoreColor=score>=90?'var(--green)':score>=70?'var(--amber)':'var(--red)';
    const summary=`<div style="background:var(--bg2);border-radius:8px;padding:10px;margin-bottom:8px">
      <div style="display:flex;align-items:center;gap:12px;margin-bottom:6px">
        <div style="font-size:28px;font-weight:800;color:${scoreColor}">${score}%</div>
        <div><div style="font-size:12px;font-weight:600">Compliance Score</div><div style="font-size:11px;color:var(--text3)">${res.compliant_count||0} compliant · ${res.non_compliant_count||0} with issues · ${res.critical_count||0} critical</div></div>
      </div>
      <div style="font-size:12px;color:var(--text2)">${escapeHtml(res.summary||'')}</div>
    </div>`;
    const disclaimer=`<div style="font-size:10px;color:var(--text3);margin-top:8px;padding-top:6px;border-top:1px solid var(--border)">AI-generated law references and severities are a starting point, not legal advice — verify against UAE Federal Decree-Law No. 33 of 2021 (or current counsel) before acting.</div>`;
    _hrmsAiResultHtml('hrms-ai-comp-result',summary+(issues.length?rows:'<div style="color:var(--green);font-size:12px;text-align:center;padding:8px">✓ All employees fully compliant</div>')+disclaimer);
  }catch(e){_hrmsAiErrorHtml('hrms-ai-comp-result','Audit failed: '+e.message);}
  finally{_hrmsAiBtn('hrms-ai-comp-btn','Run Compliance Audit',false);}
}

// 5. Leave Pattern Analysis
async function hrmsAiLeaveAnalysis(){
  _hrmsAiBtn('hrms-ai-leave-btn','Analyse Leave Patterns',true);
  _hrmsAiResultHtml('hrms-ai-leave-result','<div style="color:var(--text3)">Collecting leave data…</div>');
  try{
    // Gather leave data from HR module DOM
    const leaveRows=[...document.querySelectorAll('#hr-leave-tbody tr:not([data-empty-state])')].map(row=>{
      const cells=[...row.querySelectorAll('td')].map(td=>td.textContent.trim());
      return {employee:cells[0]||'',type:cells[1]||'',from:cells[2]||'',to:cells[3]||'',days:cells[4]||'',status:cells[5]||''};
    }).filter(r=>r.employee);
    const res=await moduleApi('/ai/hr/leave-analysis',{method:'POST',body:{leave_data:leaveRows}});
    if(res.error){_hrmsAiErrorHtml('hrms-ai-leave-result',res.error);return;}
    const patterns=res.patterns||[];
    const sevColor={Alert:'var(--red)',Watch:'var(--amber)',Info:'var(--accent)'};
    const rows=patterns.map(p=>`
      <div style="padding:8px;border:1px solid var(--border);border-radius:7px;margin-bottom:6px">
        <div style="display:flex;align-items:center;gap:6px;margin-bottom:3px">
          <span class="b" style="font-size:10px;color:${sevColor[p.severity]||'var(--text3)'};background:${sevColor[p.severity]||'var(--bg3)'}22">${escapeHtml(p.severity||'')}</span>
          <strong style="font-size:12px">${escapeHtml(p.pattern_type||'')}</strong>
        </div>
        <div style="font-size:11.5px;color:var(--text2)">${escapeHtml(p.description||'')}</div>
        ${(p.affected_employees||[]).length?`<div style="font-size:11px;color:var(--text3);margin-top:2px">Employees: ${p.affected_employees.map(e=>escapeHtml(e)).join(', ')}</div>`:''}
        ${p.recommendation?`<div style="font-size:11px;color:var(--accent);margin-top:2px">→ ${escapeHtml(p.recommendation)}</div>`:''}
      </div>`).join('');
    const burnout=(res.burnout_risk_employees||[]);
    const summary=`<div style="background:var(--bg2);border-radius:8px;padding:8px;margin-bottom:8px;font-size:12px">
      <div style="margin-bottom:4px">${escapeHtml(res.summary||'')}</div>
      ${(res.insights||[]).map(i=>`<div style="color:var(--text3);margin-top:2px">• ${escapeHtml(i)}</div>`).join('')}
      ${burnout.length?`<div style="color:var(--red);margin-top:4px;font-weight:600">Burnout risk: ${burnout.map(e=>escapeHtml(e)).join(', ')}</div>`:''}
    </div>`;
    _hrmsAiResultHtml('hrms-ai-leave-result',summary+(patterns.length?rows:'<div style="color:var(--green);font-size:12px;text-align:center;padding:8px">No concerning leave patterns detected</div>'));
  }catch(e){_hrmsAiErrorHtml('hrms-ai-leave-result','Analysis failed: '+e.message);}
  finally{_hrmsAiBtn('hrms-ai-leave-btn','Analyse Leave Patterns',false);}
}

// 6. JD Generator
async function hrmsAiJdGenerate(){
  const title=(document.getElementById('hrms-ai-jd-title')?.value||'').trim();
  const dept=(document.getElementById('hrms-ai-jd-dept')?.value||'').trim();
  if(!title){toast('Enter job title first','warn');return;}
  _hrmsAiBtn('hrms-ai-jd-btn','Generate JD',true);
  _hrmsAiResultHtml('hrms-ai-jd-result','<div style="color:var(--text3)">Generating job description…</div>');
  try{
    const res=await moduleApi('/ai/hr/jd-generate',{method:'POST',body:{
      title,department:dept,
      salary_range:document.getElementById('hrms-ai-jd-salary')?.value||'',
      experience_years:document.getElementById('hrms-ai-jd-exp')?.value||'',
      requirements:document.getElementById('hrms-ai-jd-req')?.value||''
    }});
    if(res.error){_hrmsAiErrorHtml('hrms-ai-jd-result',res.error);return;}
    const section=(label,items)=>Array.isArray(items)&&items.length?`<div style="margin-top:8px"><div style="font-size:10.5px;font-weight:700;color:var(--text3);text-transform:uppercase;letter-spacing:.05em;margin-bottom:3px">${label}</div>${items.map(i=>`<div style="font-size:11.5px;color:var(--text2);padding:2px 0">• ${escapeHtml(String(i))}</div>`).join('')}</div>`:'';
    const html=`<div style="padding:8px;background:var(--bg2);border-radius:8px">
      <div style="font-size:14px;font-weight:700;color:var(--text);margin-bottom:2px">${escapeHtml(res.job_title||title)}</div>
      <div style="font-size:11px;color:var(--text3);margin-bottom:6px">${escapeHtml(res.department||dept)} · ${escapeHtml(res.location||'UAE')} · ${escapeHtml(res.employment_type||'Full-Time')}</div>
      <div style="font-size:12px;color:var(--text2);line-height:1.5;margin-bottom:4px">${escapeHtml(res.job_summary||'')}</div>
      ${section('Key Responsibilities',res.key_responsibilities)}
      ${section('Required Qualifications',res.required_qualifications)}
      ${section('Technical Skills',res.technical_skills)}
      ${section('Benefits',res.benefits)}
      ${section('UAE Requirements',res.uae_requirements)}
      <div style="margin-top:10px">
        <button class="btn btn-g btn-sm" onclick="hrmsAiJdCopy(${jsonAttr(JSON.stringify(res))})">Copy Full JD</button>
        <button class="btn btn-g btn-sm" onclick="hrmsAiJdToRecruitment(${jsonAttr(JSON.stringify(res))})">Add to Recruitment</button>
      </div>
    </div>`;
    _hrmsAiResultHtml('hrms-ai-jd-result',html);
  }catch(e){_hrmsAiErrorHtml('hrms-ai-jd-result','Generation failed: '+e.message);}
  finally{_hrmsAiBtn('hrms-ai-jd-btn','Generate JD',false);}
}

function hrmsAiJdCopy(jsonStr){
  try{
    const d=JSON.parse(jsonStr);
    const text=[
      d.job_title,'',d.department+' | '+d.location+' | '+d.employment_type,'',
      d.job_summary,'',
      'KEY RESPONSIBILITIES:',...(d.key_responsibilities||[]).map(r=>'• '+r),'',
      'REQUIRED QUALIFICATIONS:',...(d.required_qualifications||[]).map(q=>'• '+q),'',
      'TECHNICAL SKILLS:',...(d.technical_skills||[]).map(s=>'• '+s),'',
      'BENEFITS:',...(d.benefits||[]).map(b=>'• '+b),'',
      'UAE REQUIREMENTS:',...(d.uae_requirements||[]).map(u=>'• '+u),
    ].join('\n');
    navigator.clipboard.writeText(text).then(()=>toast('JD copied to clipboard','ok'));
  }catch{}
}

function hrmsAiJdToRecruitment(jsonStr){
  try{
    const d=JSON.parse(jsonStr);
    go('recruitment');
    setTimeout(()=>{
      const pos=document.getElementById('recruit-position');
      const dept=document.getElementById('recruit-dept');
      const desc=document.getElementById('recruit-desc');
      if(pos)pos.value=d.job_title||'';
      if(dept)dept.value=d.department||'';
      if(desc)desc.value=d.job_summary||'';
      toast('JD pre-filled in Recruitment form','ok');
    },400);
  }catch{}
}

// 7. HR Chatbot
const _hrmsAiChatHistory=[];

function hrmsAiChatSuggest(question){
  const el=document.getElementById('hrms-ai-chat-input');
  if(el)el.value=question;
  hrmsAiChatSend();
}

async function hrmsAiChatSend(){
  const input=document.getElementById('hrms-ai-chat-input');
  const question=(input?.value||'').trim();
  if(!question)return;
  if(input)input.value='';
  _hrmsAiChatHistory.push({role:'user',content:question});
  _hrmsAiChatAppend('user',question);
  const btn=document.getElementById('hrms-ai-chat-btn');
  if(btn){btn.disabled=true;btn.textContent='…';}
  try{
    const res=await moduleApi('/ai/hr/chatbot',{method:'POST',body:{question}});
    if(res.error){_hrmsAiChatAppend('ai','Error: '+res.error);return;}
    _hrmsAiChatHistory.push({role:'assistant',content:res.answer});
    _hrmsAiChatAppend('ai',res.answer||'No response',res.follow_up_questions||[]);
  }catch(e){
    _hrmsAiChatAppend('ai','Sorry, I could not reach the AI service. Check that the backend is running and API key is configured.');
  }finally{
    if(btn){btn.disabled=false;btn.textContent='Send';}
  }
}

function _hrmsAiChatAppend(role,text,followUps=[]){
  const log=document.getElementById('hrms-ai-chat-log');
  if(!log)return;
  // Remove empty placeholder
  const ph=log.querySelector('div[style*="text-align:center"]');
  if(ph)ph.remove();
  const isUser=role==='user';
  const div=document.createElement('div');
  div.style.cssText=`margin-bottom:8px;display:flex;gap:6px;${isUser?'flex-direction:row-reverse':''}`;
  const av=document.createElement('div');
  av.style.cssText=`width:24px;height:24px;border-radius:50%;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:700;${isUser?'background:var(--accent);color:#fff':'background:var(--purple);color:#fff'}`;
  av.textContent=isUser?'You':'AI';
  const bubble=document.createElement('div');
  bubble.style.cssText=`background:${isUser?'var(--accent)':'var(--bg3)'};color:${isUser?'#fff':'var(--text)'};padding:6px 10px;border-radius:${isUser?'12px 12px 2px 12px':'12px 12px 12px 2px'};font-size:12px;max-width:85%;line-height:1.5`;
  bubble.textContent=text;
  div.appendChild(av);
  div.appendChild(bubble);
  log.appendChild(div);
  if(followUps.length){
    const fqDiv=document.createElement('div');
    fqDiv.style.cssText='display:flex;flex-wrap:wrap;gap:4px;margin-left:30px;margin-bottom:4px';
    followUps.forEach(q=>{
      const btn=document.createElement('button');
      btn.className='btn btn-g btn-sm';
      btn.style.fontSize='10.5px';
      btn.textContent=q;
      btn.onclick=()=>hrmsAiChatSuggest(q);
      fqDiv.appendChild(btn);
    });
    log.appendChild(fqDiv);
  }
  log.scrollTop=log.scrollHeight;
}

// ── OT Rules & Department/Branch management ──────────────────────────
function selectOtRate(type){
  ['fixed','monthly','other'].forEach(t=>{
    const lbl=document.getElementById('ot-lbl-'+t)||(t==='other'?document.getElementById('ot-lbl-rate-other'):null);
    if(lbl)lbl.classList.toggle('active',t===type);
    const radio=document.querySelector(`input[name="ot-rate-type"][value="${t}"]`);
    if(radio)radio.checked=(t===type);
  });
  const cfgs={fixed:'ot-rate-fixed-cfg',monthly:'ot-rate-monthly-cfg',other:'ot-rate-other-cfg'};
  Object.entries(cfgs).forEach(([t,id])=>{
    const el=document.getElementById(id);
    if(el)el.style.display=(t===type?'':'none');
  });
  // Update monthly example when days/hours change
  if(type==='monthly'){
    const upd=()=>{
      const d=parseFloat(document.getElementById('ot-work-days')?.value||22);
      const h=parseFloat(document.getElementById('ot-work-hours')?.value||8);
      const rate=(5000/(d*h)).toFixed(2);
      const ex=document.getElementById('ot-monthly-example');
      if(ex)ex.value=`5000 ÷ (${d} × ${h}) = ${currentCurrency()} ${rate}/hr base × multiplier`;
    };
    ['ot-work-days','ot-work-hours'].forEach(id=>{
      const el=document.getElementById(id);
      if(el&&!el._otListener){el._otListener=true;el.addEventListener('input',upd);}
    });
  }
}
function selectOtHours(type){
  ['hours','days','other'].forEach(t=>{
    const idMap={hours:'ot-lbl-hrs',days:'ot-lbl-days',other:'ot-lbl-hrs-other'};
    const lbl=document.getElementById(idMap[t]);
    if(lbl)lbl.classList.toggle('active',t===type);
    const radio=document.querySelector(`input[name="ot-hours-type"][value="${t}"]`);
    if(radio)radio.checked=(t===type);
  });
  const cfgs={hours:null,days:'ot-hours-days-cfg',other:'ot-hours-other-cfg'};
  Object.entries(cfgs).forEach(([t,id])=>{
    if(!id)return;
    const el=document.getElementById(id);
    if(el)el.style.display=(t===type?'':'none');
  });
}
function saveOtRules(){
  const rateType=document.querySelector('input[name="ot-rate-type"]:checked')?.value||'fixed';
  const hoursType=document.querySelector('input[name="ot-hours-type"]:checked')?.value||'hours';
  // Named OT Rules previously lived only in #ot-rules-tbody's DOM rows —
  // addNamedOtRule() built the row and nothing else, so the whole table
  // was gone on the next page load. Bundled into this same hr_settings
  // record (same pattern hrLeavePolicy nests its leave_types/leave_policies
  // lists) rather than as separate AppDataRecord rows, since it's a small
  // admin-managed list, not per-employee data.
  const namedRules=[...document.querySelectorAll('#ot-rules-tbody tr')].map(tr=>{
    try{return JSON.parse(tr.dataset.rule||'');}catch{return null;}
  }).filter(Boolean);
  const rule={id:'ot-rules-config',rateType,hoursType,fixedRate:document.getElementById('ot-fixed-rate')?.value,workDays:document.getElementById('ot-work-days')?.value,workHours:document.getElementById('ot-work-hours')?.value,otCooloffMinutes:Math.max(0,Number(document.getElementById('ot-cooloff-minutes')?.value)||0),multNormal:document.getElementById('ot-mult-normal')?.value,multWeekend:document.getElementById('ot-mult-weekend')?.value,multHoliday:document.getElementById('ot-mult-holiday')?.value,multRamadan:document.getElementById('ot-mult-ramadan')?.value,namedRules};
  saveServer('hr_settings',rule);
  // Refresh OT policy selects
  _syncOtPolicySelects(rateType);
  toast('OT Rules saved','ok');
}

// Cached so updateOtMultiplier() can still read the configured rates on
// pages (index.html's copy of the Submit OT modal) that have no
// #ot-mult-normal/weekend/holiday/ramadan settings inputs of their own to
// read from — those inputs only exist on hrms.html's HR Settings tab, but
// this hydration function runs on every page via the shared bootstrap.
let _otRulesConfigCache=null;
function _applyOtRulesConfig(rule){
  if(!rule)return;
  _otRulesConfigCache=rule;
  const setVal=(id,v)=>{const el=document.getElementById(id);if(el&&v!==undefined&&v!==null)el.value=v;};
  const radio=document.querySelector(`input[name="ot-rate-type"][value="${rule.rateType}"]`);
  if(radio)radio.checked=true;
  const hoursRadio=document.querySelector(`input[name="ot-hours-type"][value="${rule.hoursType}"]`);
  if(hoursRadio)hoursRadio.checked=true;
  setVal('ot-fixed-rate',rule.fixedRate);
  setVal('ot-work-days',rule.workDays);
  setVal('ot-work-hours',rule.workHours);
  setVal('ot-cooloff-minutes',rule.otCooloffMinutes);
  setVal('ot-mult-normal',rule.multNormal);
  setVal('ot-mult-weekend',rule.multWeekend);
  setVal('ot-mult-holiday',rule.multHoliday);
  setVal('ot-mult-ramadan',rule.multRamadan);
  // Rebuild the Named OT Rules table from the saved list — previously
  // nothing repopulated #ot-rules-tbody on load at all, so it was always
  // empty on a fresh page visit regardless of what had been added before.
  const tbody=document.getElementById('ot-rules-tbody');
  if(tbody&&Array.isArray(rule.namedRules)){
    tbody.innerHTML='';
    rule.namedRules.forEach(r=>_renderNamedOtRuleRow(r));
  }
  _syncOtPolicySelects(rule.rateType);
}

// The company's real weekend, as a Set of JS getDay() values (0=Sun..6=Sat).
// Both renderAttendanceCalendar() and the Rota grid used to hardcode
// [0,6] (Sat/Sun) unconditionally -- for a company that actually runs
// Sun-Thu with Fri/Sat off (still the majority convention for UAE private-
// sector SMEs), that mismarks their real day off (Friday) as "Absent" and
// silently drops any real attendance/leave data that falls on their actual
// working Sunday. Defaults to Sat/Sun (the previous hardcoded behavior) so
// nothing changes for a company that never touches the setting. "custom"
// (or an unrecognized value) returns null -- meaning "don't guess", since
// there's no single global rule that can represent a rota-driven off-day
// pattern; callers should skip weekend-specific styling entirely in that case.
let _companyWeekendDaysCache=new Set([0,6]);
function _companyWeekendDaySet(){
  return _companyWeekendDaysCache;
}
function _applyWeekendPolicyConfig(cfg){
  const mode=cfg?.mode||'sat_sun';
  _companyWeekendDaysCache=mode==='fri_sat'?new Set([5,6]):mode==='custom'?null:new Set([0,6]);
  const sel=document.getElementById('hr-weekend-policy');
  if(sel)sel.value=mode;
}
function saveHrRules(){
  // Only the Weekend Policy field on this card is actually persisted today
  // -- Late Grace Period/Minimum OT/Maximum Daily OT/Approval Hierarchy
  // remain display-only, same as before this fix; not expanding that scope
  // here.
  const mode=document.getElementById('hr-weekend-policy')?.value||'sat_sun';
  saveServer('hr_settings',{id:'weekend-policy-config',mode});
  _applyWeekendPolicyConfig({mode});
  renderAttendanceCalendar();
  toast('HR rules saved','ok');
}

function _renderNamedOtRuleRow(rule){
  const tbody=document.getElementById('ot-rules-tbody');
  if(!tbody)return;
  removeEmptyState(tbody);
  const {name,rateType,hoursType,multNormal:mn,multWeekend:mw,multHoliday:mh}=rule;
  const rateLabel=rateType==='fixed'?'<span class="b b-g">Fixed</span>':rateType==='monthly'?'<span class="b b-b">Monthly-Based</span>':'<span class="b" style="background:var(--bg3)">Other</span>';
  const hoursLabel=hoursType==='hours'?'<span class="b" style="background:var(--bg3)">Based on Hours</span>':hoursType==='days'?'<span class="b b-a">Based on Days</span>':'<span class="b" style="background:var(--bg3)">Other</span>';
  const tr=document.createElement('tr');
  tr.dataset.rule=JSON.stringify(rule);
  tr.innerHTML=`<td>${escapeHtml(name)}</td><td>${rateLabel}</td><td>${hoursLabel}</td><td>${escapeHtml(String(mn))}</td><td>${escapeHtml(String(mw))}</td><td>${escapeHtml(String(mh))}</td><td>All Employees</td><td><button class="btn btn-g btn-sm" onclick="_deleteNamedOtRule(this)">Delete</button></td>`;
  tbody.appendChild(tr);
}
function _deleteNamedOtRule(btn){
  const tbody=btn.closest('tbody');
  btn.closest('tr').remove();
  _syncOtPolicySelects();
  saveOtRules();
  if(tbody&&!tbody.querySelector('tr:not([data-empty-state])')){
    emptyTableMessage(tbody,'No named OT rules yet. Click + Add Rule to create one.');
  }
}
function _syncOtPolicySelects(rateType){
  // Update emp-ot-rate select to reflect named rules from tbody
  const rows=document.querySelectorAll('#ot-rules-tbody tr');
  document.querySelectorAll('#emp-ot-rate').forEach(sel=>{
    const cur=sel.value;
    // Keep base options, add named rules
    while(sel.options.length>4)sel.remove(4);
    rows.forEach(row=>{
      const name=row.cells?.[0]?.textContent?.trim();
      if(name){const opt=document.createElement('option');opt.value=name;opt.textContent=name;sel.appendChild(opt);}
    });
    sel.value=cur||'system-default';
  });
}
function addNamedOtRule(){
  const name=prompt('Rule Name (e.g. "Weekend Premium OT"):');
  if(!name?.trim())return;
  if(!document.getElementById('ot-rules-tbody'))return;
  const rule={
    name:name.trim(),
    rateType:document.querySelector('input[name="ot-rate-type"]:checked')?.value||'fixed',
    hoursType:document.querySelector('input[name="ot-hours-type"]:checked')?.value||'hours',
    multNormal:document.getElementById('ot-mult-normal')?.value||'1.25',
    multWeekend:document.getElementById('ot-mult-weekend')?.value||'1.50',
    multHoliday:document.getElementById('ot-mult-holiday')?.value||'1.50',
  };
  _renderNamedOtRuleRow(rule);
  _syncOtPolicySelects();
  // Previously DOM-only (tbody.appendChild and nothing else) — the whole
  // Named OT Rules table was gone on the next page load.
  saveOtRules();
  toast(`OT rule "${rule.name}" added`,'ok');
}
// -- HR USERS & ROLES ------------------------------------------------------
// Backed by the real Employee.username/password_hash/role_id columns and the
// RBAC Role table (backend/app/routers/hr_access.py), not local mock state —
// what's set here is exactly what Employee Self-Service (/ess/login) and the
// GPS/RBAC endpoints (/hr/login) check against.
let _hrEmployeesCache=[];
let _hrRolesCache=[];

async function loadHrUsersAndRoles(){
  const tbody=document.getElementById('hr-users-tbody');
  if(tbody)tbody.innerHTML='<tr data-empty-state><td colspan="7" style="text-align:center;color:var(--text3);padding:20px">Loading…</td></tr>';
  try{
    const [empRes,roleRes]=await Promise.all([
      fetch(`${apiBaseUrl()}/hr/admin/employees`,{headers:backendHeaders()}),
      fetch(`${apiBaseUrl()}/hr/admin/roles`,{headers:backendHeaders()}),
    ]);
    _hrEmployeesCache=empRes.ok?await empRes.json():[];
    _hrRolesCache=roleRes.ok?await roleRes.json():[];
    _renderHrUsersTable();
  }catch(e){
    if(tbody)tbody.innerHTML='<tr data-empty-state><td colspan="7" style="text-align:center;color:var(--red)">Failed to load employees.</td></tr>';
  }
}

function _renderHrUsersTable(){
  const tbody=document.getElementById('hr-users-tbody');
  if(!tbody)return;
  if(!_hrEmployeesCache.length){
    tbody.innerHTML='<tr data-empty-state><td colspan="7" style="text-align:center;color:var(--text3);padding:20px">No employees found. Add employees in the Employees tab first.</td></tr>';
    return;
  }
  tbody.innerHTML=_hrEmployeesCache.map(e=>{
    const hasAccess=!!e.username;
    let statusBadge;
    if(!hasAccess) statusBadge='<span class="b" style="background:var(--bg3)">No Access</span>';
    else if(!e.has_password) statusBadge='<span class="b b-a" title="Username is set but no password was ever saved — login with the custom username will fail until a password is set">No Password Set</span>';
    else statusBadge=e.is_active?'<span class="b b-g">Active</span>':'<span class="b b-r">Disabled</span>';
    const deptScope=e.department_scope||[];
    const roleCell=e.role_name
      ?`<span class="b b-p" style="font-size:11px">${escapeHtml(e.role_name)}</span>`+(deptScope.length?`<div style="margin-top:3px;color:var(--accent);font-size:10px" title="Sees this department's roster in ESS once portal access is active">Team: ${_deptScopeLabel(deptScope).map(escapeHtml).join(', ')}</div>`:'')
      :'<span style="color:var(--text3);font-size:12px">—</span>';
    return `<tr>
      <td style="font-size:12px">${escapeHtml(e.full_name)}</td>
      <td class="mono" style="font-size:12px">${escapeHtml(e.employee_no)}</td>
      <td style="font-size:12px">${escapeHtml(e.department||'—')}</td>
      <td><strong style="font-size:12px">${escapeHtml(e.username||'—')}</strong></td>
      <td>${roleCell}</td>
      <td>${statusBadge}</td>
      <td style="white-space:nowrap">
        <button class="btn btn-g btn-xs" onclick="openAddHrUserModal('${escapeHtml(e.id)}')">${hasAccess?'Edit':'Grant Access'}</button>
        ${hasAccess?`<button class="btn btn-r btn-xs" onclick="deleteHrUser('${escapeHtml(e.id)}')">Revoke</button>`:''}
      </td>
    </tr>`;
  }).join('');
}

function openAddHrUserModal(employeeId){
  const modal=document.getElementById('m-hr-user');
  if(!modal||!employeeId)return;
  const emp=_hrEmployeesCache.find(e=>e.id===employeeId);
  if(!emp)return;
  modal.dataset.employeeId=employeeId;
  const hasAccess=!!emp.username;
  document.getElementById('hr-user-modal-title').textContent=hasAccess?'Edit Portal Access':'Grant Portal Access';
  document.getElementById('hr-user-modal-sub').textContent=`Employee Self-Service login for ${emp.full_name}`;
  document.getElementById('hr-user-employee-display').textContent=`${emp.full_name} (${emp.employee_no})${emp.department?' — '+emp.department:''}`;

  const roleSel=document.getElementById('hr-user-role');
  if(roleSel){
    roleSel.innerHTML='<option value="">— Select Role —</option>'+_hrRolesCache.map(r=>`<option value="${escapeHtml(r.id)}">${escapeHtml(r.role_name)}${r.department_scope&&r.department_scope.length?` (Team: ${_deptScopeLabel(r.department_scope).map(escapeHtml).join(', ')})`:''}</option>`).join('');
    roleSel.value=emp.role_id||'';
  }
  document.getElementById('hr-user-username').value=emp.username||'';
  document.getElementById('hr-user-status').value=emp.is_active===false?'inactive':'active';
  document.getElementById('hr-user-password').value='';
  const pwHint=document.getElementById('hr-user-pw-hint');
  if(pwHint)pwHint.textContent=emp.has_password?'(leave blank to keep current password)':'(required — no password has ever been set for this employee; leaving this blank means their password stays their Employee No., not left as-is)';

  showM('m-hr-user');
}

async function saveHrUser(){
  const modal=document.getElementById('m-hr-user');
  const employeeId=modal?.dataset.employeeId;
  if(!employeeId)return;
  const emp=_hrEmployeesCache.find(e=>e.id===employeeId);
  const username=document.getElementById('hr-user-username')?.value.trim();
  const roleId=document.getElementById('hr-user-role')?.value||null;
  const status=document.getElementById('hr-user-status')?.value||'active';
  const password=document.getElementById('hr-user-password')?.value||'';

  if(!username){toast('Enter a portal username','warn');return;}
  if(!emp?.has_password&&!password){toast('Set a password — this employee has never had one saved (their default is currently their Employee No.)','warn');return;}
  if(password&&password.length<6){toast('Password must be at least 6 characters','warn');return;}

  const body={username,role_id:roleId||null,is_active:status==='active'};
  if(password)body.password=password;

  try{
    const r=await fetch(`${apiBaseUrl()}/hr/admin/employees/${employeeId}/portal-access`,{
      method:'PUT',headers:backendHeaders(),body:JSON.stringify(body)
    });
    if(r.ok){
      toast('Portal access saved','ok');
      closeM('m-hr-user');
      loadHrUsersAndRoles();
    }else{
      const d=await r.json();
      toast(d.detail||'Failed to save portal access','err');
    }
  }catch(e){toast('Cannot reach server','err');}
}

async function deleteHrUser(employeeId){
  const emp=_hrEmployeesCache.find(e=>e.id===employeeId);
  if(!(await appConfirm({title:'Revoke Portal Access',message:`Revoke Employee Self-Service access for ${emp?emp.full_name:'this employee'}? They will no longer be able to sign in with their username/password.`,okText:'Revoke'})))return;
  try{
    const r=await fetch(`${apiBaseUrl()}/hr/admin/employees/${employeeId}/portal-access`,{method:'DELETE',headers:backendHeaders()});
    if(r.ok){toast('Portal access revoked','ok');loadHrUsersAndRoles();}
    else{toast('Failed to revoke access','err');}
  }catch(e){toast('Cannot reach server','err');}
}

// -- LEAVE POLICY --------------------------------------------------
function saveLeavePolicies(){
  const types=[...document.querySelectorAll('#leave-types-tbody tr[data-leave-type]')].map(tr=>{
    const cells=[...tr.querySelectorAll('input,select')];
    return{
      type:tr.dataset.leaveType,
      days:cells[0]?.value||'',
      paid:cells[1]?.value||'Yes',
      basis:cells[2]?.value||'Calendar',
      carry_forward:cells[3]?.value||'No',
      max_carry:cells[4]?.value||'0',
      encash:cells[5]?.value||'No',
    };
  });
  const policies=[...document.querySelectorAll('#leave-policies-tbody tr')].map(tr=>{
    const cells=[...tr.querySelectorAll('input,select')];
    const name=tr.querySelector('strong')?.textContent?.trim()||'';
    return{
      name,
      // Matches the #emp-leave-policy <option value>. Built-in rows carry
      // their own short value (e.g. "UAE 30 Calendar") distinct from the
      // longer display name; a custom policy added via addLeavePolicy()
      // has no such attribute, so its own name IS its value -- falling
      // back to null here (as this used to) meant a custom policy was
      // silently skipped by both _applyLeavePolicyDaysToMap() and the
      // backend's _effective_leave_policy_configs() (leave.py), which both
      // ignore any entry with an empty value: a custom policy could be
      // named and saved but never actually applied to anyone.
      value:tr.dataset.policyValue||name,
      days:cells[0]?.value||'',
      basis:cells[1]?.value||'Calendar',
      encash:cells[2]?.value||'No',
      carry_forward:cells[3]?.value||'No',
    };
  });
  const yearStart=document.getElementById('leave-year-start')?.value||'January';
  const accrual=document.getElementById('leave-accrual')?.value||'Monthly (1/12 per month)';
  const carryDeadline=document.getElementById('leave-carry-deadline')?.value||'End of March';
  const encashTiming=document.getElementById('leave-encash-timing')?.value||'On resignation / gratuity';
  const data={leave_types:types,leave_policies:policies,year_start:yearStart,accrual,carry_deadline:carryDeadline,encash_timing:encashTiming};
  saveServer('hrLeavePolicy',{id:'leave-policy',...data});
  _applyLeavePolicyDaysToMap(policies);
  toast('Leave policy saved','ok');
}

// Previously leaveEntitlementDays() only ever read the hardcoded
// _LEAVE_POLICY_DAYS map — an admin editing a policy's day-count in HR
// Settings > Leave Policy had zero effect on real entitlement/balance
// calculations. This keeps the map in sync with whatever was last saved.
function _applyLeavePolicyDaysToMap(policies){
  (policies||[]).forEach(p=>{
    if(p.value&&p.days!==''&&p.days!=null&&!isNaN(Number(p.days))){
      _LEAVE_POLICY_DAYS[p.value]=Number(p.days);
    }
  });
}

async function loadLeavePoliciesFromServer(){
  try{
    const response=await authenticatedFetch(`${apiBaseUrl()}/app-data/records/hrLeavePolicy?limit=10`);
    if(!response.ok)return;
    const data=await response.json();
    const rec=(Array.isArray(data.records)?data.records:[]).find(r=>r.id==='leave-policy');
    if(!rec)return;
    _applyLeavePolicyDaysToMap(rec.leave_policies);
    // Reflect the saved day-counts back into the settings table itself —
    // previously this table always showed its 5 hardcoded defaults on every
    // page load, even after an admin had edited and saved different values.
    (rec.leave_policies||[]).forEach(p=>{
      if(!p.value)return;
      const row=document.querySelector(`#leave-policies-tbody tr[data-policy-value="${CSS.escape(p.value)}"]`);
      if(row){
        const daysInput=row.querySelector('input');
        if(daysInput&&p.days!=null&&p.days!=='')daysInput.value=p.days;
        return;
      }
      // A custom policy (added via addLeavePolicy(), not one of the
      // built-in hardcoded rows) has no matching row in the static HTML
      // at all -- append one, or it silently disappears from this table
      // (and from the Add Employee "Leave Policy" dropdown, which is
      // sourced from this same table) on every reload.
      const tbody=document.getElementById('leave-policies-tbody');
      if(!tbody||!p.name)return;
      const tr=document.createElement('tr');
      tr.dataset.policyValue=p.value;
      tr.innerHTML=_leavePolicyRowHtml(p.name,p.days,p.basis,p.encash,p.carry_forward);
      tbody.appendChild(tr);
    });
    // Same gap existed for Leave Types & Entitlements — this table always
    // re-showed its hardcoded 30/90/5/60/5/30 defaults too, even though
    // those saved values are exactly what /leave/balance and /ess/leave-
    // balance actually compute Leave Balance from — an admin had no way to
    // see (or confirm) what was really configured.
    (rec.leave_types||[]).forEach(t=>{
      if(!t.type)return;
      const row=document.querySelector(`#leave-types-tbody tr[data-leave-type="${CSS.escape(t.type)}"]`);
      if(!row)return;
      const cells=[...row.querySelectorAll('input,select')];
      if(cells[0]&&t.days!=null&&t.days!=='')cells[0].value=t.days;
      if(cells[1]&&t.paid)cells[1].value=t.paid;
      if(cells[2]&&t.basis)cells[2].value=t.basis;
      if(cells[3]&&t.carry_forward)cells[3].value=t.carry_forward;
      if(cells[4]&&t.max_carry!=null&&t.max_carry!=='')cells[4].value=t.max_carry;
      if(cells[5]&&t.encash)cells[5].value=t.encash;
    });
    const setSelVal=(id,v)=>{const el=document.getElementById(id);if(el&&v)el.value=v;};
    setSelVal('leave-year-start',rec.year_start);
    setSelVal('leave-accrual',rec.accrual);
    setSelVal('leave-carry-deadline',rec.carry_deadline);
    setSelVal('leave-encash-timing',rec.encash_timing);
  }catch(e){console.warn('Failed to load leave policy settings:',e);}
}

// Shared by addLeavePolicy() and loadLeavePoliciesFromServer() (which
// appends a row for any saved custom policy the static HTML doesn't
// already have a row for -- previously a custom policy vanished from
// this table on every reload, since the load function only ever patched
// EXISTING rows' day counts and never re-created rows for ones it didn't
// find).
function _leavePolicyRowHtml(name,days,basis,encash,carryForward){
  const sel=(opts,current)=>opts.map(o=>`<option${o===current?' selected':''}>${o}</option>`).join('');
  return `
    <td><strong>${escapeHtml(name)}</strong></td>
    <td><input class="fi mono" style="width:80px;padding:3px 6px" value="${escapeHtml(String(days??21))}"></td>
    <td><select class="fi" style="padding:3px 4px;font-size:12px">${sel(['Calendar','Working'],basis||'Calendar')}</select></td>
    <td><span style="font-size:12px">All Staff</span></td>
    <td><select class="fi" style="padding:3px 4px;font-size:12px">${sel(['Yes','No'],encash||'No')}</select></td>
    <td><select class="fi" style="padding:3px 4px;font-size:12px">${sel(['Yes','No'],carryForward||'No')}</select></td>
    <td><button class="btn btn-g btn-xs" onclick="this.closest('tr').remove();toast('Policy removed','ok')">×</button></td>`;
}

// Generic single-field "+ Add X" modal (#m-quick-add in hrms.html) --
// replaces the native prompt() every one-field "add a named item" flow in
// this app used to reach for (Leave Policy, Job Grade, and previously
// Holiday before it grew into its own multi-field modal). A native
// prompt() is an unstyled OS popup that ignores dark mode and blocks the
// main thread; this reuses the same showM()/hideM() modal system as
// every other "+ Add" button already does.
function _openQuickAddModal(opts){
  const titleEl=document.getElementById('quick-add-title');
  const labelEl=document.getElementById('quick-add-label');
  const inputEl=document.getElementById('quick-add-input');
  const btnEl=document.getElementById('quick-add-confirm-btn');
  if(titleEl)titleEl.textContent=opts.title||'Add Item';
  if(labelEl)labelEl.textContent=opts.label||'Name';
  if(inputEl){inputEl.value='';inputEl.placeholder=opts.placeholder||'';}
  if(btnEl)btnEl.onclick=function(){
    const value=(inputEl?.value||'').trim();
    if(!value){toast((opts.label||'This field')+' is required','warn');return;}
    hideM('m-quick-add');
    opts.onConfirm(value);
  };
  showM('m-quick-add');
  setTimeout(()=>inputEl?.focus(),120);
}

function addLeavePolicy(){
  _openQuickAddModal({
    title:'Add Leave Policy', label:'Policy Name', placeholder:'e.g. "Part-Time Pro-Rata"',
    onConfirm:function(name){
      const tbody=document.getElementById('leave-policies-tbody');
      if(!tbody)return;
      const tr=document.createElement('tr');
      tr.dataset.policyValue=name;
      tr.innerHTML=_leavePolicyRowHtml(name);
      tbody.appendChild(tr);
      toast(`Policy "${name}" added`,'ok');
    }
  });
}

function addHrJobGrade(){
  _openQuickAddModal({
    title:'Add Job Grade', label:'Job Grade', placeholder:'e.g. Grade E — Intern',
    onConfirm:function(name){
      const wrap=document.getElementById('job-grade-tags-wrap');
      if(!wrap)return;
      const span=document.createElement('span');
      span.className='dept-tag';
      span.innerHTML=`${escapeHtml(name)}<button onclick="removeHrJobGrade(this)" title="Remove">×</button>`;
      wrap.appendChild(span);
      toast(`Job grade "${name}" added`,'ok');
    }
  });
}
async function removeHrJobGrade(btn){
  const tag=btn.closest('.dept-tag');
  const name=tag?.childNodes[0]?.textContent?.trim()||'';
  if(!(await appConfirm({title:'Remove Job Grade',message:`Remove grade "${name}"?`,okText:'Remove'})))return;
  tag?.remove();
}
// Read current department names from data store
// A role's department list can contain "@own" = "only the login's own department".
function _deptScopeLabel(list){
  return (list||[]).map(d=>d==='@own'?'own department':d);
}
function _getDeptNames(){
  const all=(typeof _deptList!=='undefined'&&_deptList.length)
    ?_deptList.map(d=>d.name)
    :[...document.querySelectorAll('#dept-tags-wrap .dept-tag')].map(t=>t.childNodes[0]?.textContent?.trim()).filter(Boolean);
  // A department-scoped HRMS login (its role has departments ticked) is only
  // offered those departments -- Add Employee, Add Task, the role modal...
  // The server enforces the same limit; this just keeps the dropdowns honest.
  const scope=window.HRMS_DEPT_SCOPE;
  if(!Array.isArray(scope)||!scope.length)return all;
  // A non-admin login is never sent the company's department list (it lives
  // in hr_settings), so a scoped login's own departments ARE the list.
  const seen=new Set();
  return scope.map(d=>String(d).trim()).filter(d=>d&&!seen.has(d.toLowerCase())&&seen.add(d.toLowerCase()));
}
function _getBranchNames(){
  if(typeof _branchList!=='undefined'&&_branchList.length)return _branchList.map(b=>b.name);
  return [...document.querySelectorAll('#branch-tags-wrap .dept-tag')]
    .map(t=>t.childNodes[0]?.textContent?.trim()).filter(Boolean);
}

function _populateEmpSelects(){
  const deptSel=document.getElementById('emp-department');
  if(deptSel){
    const cur=deptSel.value;
    const depts=_getDeptNames();
    deptSel.innerHTML='<option value="">— Select Department —</option>'+
      (depts.length
        ?depts.map(d=>`<option value="${escapeHtml(d)}">${escapeHtml(d)}</option>`).join('')
        :'<option disabled>No departments — add in HR Settings</option>');
    if(cur)deptSel.value=cur;
  }
  const branchSel=document.getElementById('emp-branch');
  if(branchSel){
    const cur=branchSel.value;
    const branches=_getBranchNames();
    branchSel.innerHTML='<option value="">— Select Branch —</option>'+
      (branches.length
        ?branches.map(b=>`<option value="${escapeHtml(b)}">${escapeHtml(b)}</option>`).join('')
        :'<option disabled>No branches — add in HR Settings</option>');
    if(cur)branchSel.value=cur;
  }
  const leaveSel=document.getElementById('emp-leave-policy');
  if(leaveSel){
    const cur=leaveSel.value;
    const options=_getLeavePolicyOptions();
    leaveSel.innerHTML='<option value="">— Select Leave Policy —</option>'+
      (options.length
        ?options.map(o=>`<option value="${escapeHtml(o.value)}">${escapeHtml(o.label)}</option>`).join('')
        :'<option disabled>No leave policies — add in HR Settings &gt; Leave Policy</option>');
    if(cur)leaveSel.value=cur;
  }
  if(document.getElementById('emp-role'))filterEmpRoles();
}

// Reads the live HR Settings > Leave Policy table (#leave-policies-tbody,
// kept in sync with the server by loadLeavePoliciesFromServer()) instead
// of the emp-leave-policy select's own hardcoded <option>s -- the Add/Edit
// Employee form previously offered a fixed set of 8 built-in policies
// regardless of what an admin actually configured (or renamed/added) in
// HR Settings, so a custom policy could be created there but never
// assigned to anyone.
function _getLeavePolicyOptions(){
  return [...document.querySelectorAll('#leave-policies-tbody tr')].map(tr=>{
    const label=tr.querySelector('strong')?.textContent?.trim()||'';
    if(!label)return null;
    return{value:tr.dataset.policyValue||label,label};
  }).filter(Boolean);
}

function openEmpModal(){
  _populateEmpSelects();
  // Reset title/button for "add" mode
  const titleEl=document.querySelector('#m-emp .modal-title');
  const subEl=document.querySelector('#m-emp .modal-sub');
  const btnEl=document.querySelector('#m-emp .btn-p');
  if(titleEl)titleEl.textContent='Add Employee';
  if(subEl)subEl.textContent='Register new employee details';
  if(btnEl)btnEl.textContent='Save Employee';
  showM('m-emp');
}

// Persist the department list as one document in hr_settings collection
// (kept for the role list, and as a fallback), AND write departments
// through to the real Company record. The main dashboard and HRMS both
// call applyDeptsBranchesFromCompany(company) from the *same* early
// bootstrap step (Company.departments), so writing there — rather than
// relying solely on the idle-scheduled hr_settings blob hydration — is
// what keeps both pages showing the same list immediately, not just
// eventually once/if that later hydration step runs.
// NOTE: branches are NOT saved here — they're real Branch rows now
// (see saveBranchModal()/deleteBranch(), backend/app/routers/branches.py),
// not a JSON blob on Company. Kept the name to avoid touching every
// saveDeptModal()/deleteDept() call site for a departments-only rename.
async function _saveDeptsBranchesToDb(){
  saveServer('hr_settings',{
    id:'dept-branch-role-config',
    departments:_deptList,
  });
  try{
    const response=await authenticatedFetch(`${apiBaseUrl()}/companies/current`,{
      method:'PUT',
      body:JSON.stringify({
        name:currentCompany?.name||'Company',
        trn:currentCompany?.trn||null,
        country:currentCompany?.country||'United Arab Emirates',
        departments:JSON.stringify(_deptList),
      }),
    });
    if(response.ok){
      const company=await response.json();
      if(currentCompany){currentCompany.departments=company.departments;}
    }
  }catch(e){ /* hr_settings blob above still has the latest list even if this sync fails */ }
}

// ── Department data store ─────────────────────────────────────────────
let _deptList=[];

// Active-only, matching the "Total Employees" dashboard KPI's own headcount
// rule (an Inactive employee's department shouldn't look more staffed than
// it really is).
function _deptEmployeeCount(name){
  return [...document.querySelectorAll('#employee-tbody tr:not([data-empty-state])')].filter(r=>{
    const cells=[...r.querySelectorAll('td')];
    const dept=(cells[3]?.textContent||'').trim();
    const status=(cells[8]?.textContent||'').trim();
    return dept===name&&status!=='Inactive';
  }).length;
}

function renderDeptTable(){
  const row=d=>{
    const cnt=_deptEmployeeCount(d.name);
    const statusCls=d.status==='Active'?'b-g':'b-gray';
    return `<tr>
      <td class="mono" style="font-size:11px">${escapeHtml(d.code||'—')}</td>
      <td style="font-weight:600">${escapeHtml(d.name)}</td>
      <td>${escapeHtml(d.head||'—')}</td>
      <td style="color:var(--text3);font-size:12px">${escapeHtml(d.description||'—')}</td>
      <td class="mono">${cnt}</td>
      <td><span class="b ${statusCls}">${escapeHtml(d.status)}</span></td>
      <td style="white-space:nowrap"><button class="icon-btn edit" title="Edit department" onclick="showDeptModal('${d.id}')">${editIconSvg()}</button><button class="btn btn-r btn-xs" title="Delete department" onclick="deleteDept('${d.id}')" style="margin-left:4px">×</button></td>
    </tr>`;
  };
  const empty='<tr><td colspan="7" style="color:var(--text3);text-align:center;padding:24px">No departments yet. Click + Add Department.</td></tr>';
  const html=_deptList.length?_deptList.map(row).join(''):empty;

  // Populate every dept table on the page
  document.querySelectorAll('#dept-tbody,#hr-policy-dept-tbody').forEach(tb=>{tb.innerHTML=html;});
}

function showDeptModal(id){
  const titleEl=document.getElementById('dept-modal-title');
  const d=id?_deptList.find(x=>x.id===id):null;
  if(titleEl)titleEl.textContent=d?'Edit Department':'Add Department';
  document.getElementById('dept-edit-id').value=id||'';
  document.getElementById('dept-name').value=d?.name||'';
  document.getElementById('dept-code').value=d?.code||'';
  document.getElementById('dept-head').value=d?.head||'';
  document.getElementById('dept-desc').value=d?.description||'';
  document.getElementById('dept-status').value=d?.status||'Active';
  // Show Delete button only in edit mode
  const delBtn=document.getElementById('dept-delete-btn');
  if(delBtn)delBtn.style.display=id?'':'none';
  showM('m-dept');
  setTimeout(()=>document.getElementById('dept-name').focus(),120);
}

function saveDeptModal(){
  const name=(document.getElementById('dept-name')?.value||'').trim();
  if(!name){toast('Department name is required','err');return;}
  const id=document.getElementById('dept-edit-id')?.value;
  const obj={
    id:id||('dept-'+Date.now()),
    name,
    code:(document.getElementById('dept-code')?.value||'').trim().toUpperCase().slice(0,6)||name.slice(0,3).toUpperCase(),
    head:(document.getElementById('dept-head')?.value||'').trim(),
    description:(document.getElementById('dept-desc')?.value||'').trim(),
    status:document.getElementById('dept-status')?.value||'Active',
  };
  if(_deptList.find(x=>x.name.toLowerCase()===name.toLowerCase()&&x.id!==id)){toast('Department name already exists','warn');return;}
  if(id){
    const idx=_deptList.findIndex(x=>x.id===id);
    if(idx>=0)_deptList[idx]=obj;
  } else {
    _deptList.push(obj);
  }
  hideM('m-dept');
  renderDeptTable();
  _syncDeptBranchSelectsFromList();
  _saveDeptsBranchesToDb();
  toast(`Department "${name}" ${id?'updated':'added'}`,'ok');
}

async function deleteDept(id){
  const d=_deptList.find(x=>x.id===id);
  if(!d)return;
  if(!(await appConfirm({title:'Remove Department',message:`Remove department "${d.name}"?`,okText:'Remove'})))return;
  _deptList=_deptList.filter(x=>x.id!==id);
  renderDeptTable();
  _syncDeptBranchSelectsFromList();
  _saveDeptsBranchesToDb();
  toast(`Department "${d.name}" removed`,'ok');
}
function deleteDeptFromModal(){
  const id=document.getElementById('dept-edit-id')?.value;
  if(!id)return;
  hideM('m-dept');
  deleteDept(id);
}

// Load/save departments from company record
function applyDeptsBranchesFromCompany(company){
  if(!company)return;
  try{
    if(company.departments){
      const p=JSON.parse(company.departments);
      if(Array.isArray(p)&&p.length){
        // Support both old format (string[]) and new format (object[])
        if(typeof p[0]==='string'){
          _deptList=p.map((n,i)=>({id:'dept-'+(i+1),name:n,code:n.slice(0,3).toUpperCase(),head:'',description:'',status:'Active'}));
        } else {
          _deptList=p;
        }
      }
    }
  }catch{}
  // Note: roles are NOT part of the Company record — they're real backend
  // RBAC roles (see /hr/admin/roles), loaded on demand by
  // loadRolesAndPermissionsTab() when that HR Settings tab is opened.
  // Branches likewise aren't part of the Company record anymore — they're
  // real Branch rows (backend/app/routers/branches.py), loaded separately.
  renderDeptTable();
  _syncDeptBranchSelectsFromList();
  loadBranchesFromDb();
}

async function loadBranchesFromDb(){
  try{
    const response=await authenticatedFetch(`${apiBaseUrl()}/branches`);
    if(!response.ok)throw new Error('Branches API returned '+response.status);
    _branchList=await response.json();
  }catch(e){ console.warn('[loadBranchesFromDb]',e); }
  renderBranchTable();
  _syncBranchSelects(_branchList.filter(b=>b.status!=='Inactive').map(b=>b.name));
}

function _syncDeptBranchSelectsFromList(){
  const names=_deptList.filter(d=>d.status!=='Inactive').map(d=>d.name);
  const deptOpts='<option value="">— Select Department —</option>'+names.map(d=>`<option>${escapeHtml(d)}</option>`).join('');
  const deptAllOpts='<option value="">All Departments</option>'+names.map(d=>`<option>${escapeHtml(d)}</option>`).join('');
  document.querySelectorAll('#emp-department,#req-dept,#task-department').forEach(sel=>{
    const cur=sel.value; sel.innerHTML=deptOpts; if(cur)sel.value=cur;
  });
  document.querySelectorAll('[id$="-department-filter"],[id="hrms-dept-filter"],#rota-week-department,#rota-month-department,#rota-dept-department').forEach(sel=>{
    const cur=sel.value; sel.innerHTML=deptAllOpts; if(cur)sel.value=cur;
  });
}

function _syncBranchSelects(branches){
  const opts='<option value="">— Select Branch —</option>'+branches.map(b=>`<option>${escapeHtml(b)}</option>`).join('');
  const locOpts='<option value="">All Locations</option>'+branches.map(b=>`<option>${escapeHtml(b)}</option>`).join('');
  document.querySelectorAll('#emp-branch,#emp-location,#req-location').forEach(sel=>{
    const cur=sel.value; sel.innerHTML=opts; if(cur)sel.value=cur;
  });
  document.querySelectorAll('#rota-week-location').forEach(sel=>{
    const cur=sel.value; sel.innerHTML=locOpts; if(cur)sel.value=cur;
  });
}

// Keep legacy sync signature working (called in a few places)
function _syncDeptBranchSelects(depts,branches){
  document.querySelectorAll('#emp-department').forEach(sel=>{
    const cur=sel.value;
    sel.innerHTML='<option value="">— Select Department —</option>'+depts.map(d=>`<option${d===cur?' selected':''}>${escapeHtml(d)}</option>`).join('');
  });
  _syncBranchSelects(branches);
}

// ── Branch data store ─────────────────────────────────────────────────
let _branchList=[];

// ── Roles & Permissions ──────────────────────────────────────────────────
// Backed by the real RBAC Role/Permission tables (backend/app/routers/
// hr_access.py) via the admin-token endpoints — the exact same roles
// assignable in Users & Roles, not a separate list. _hrRolesCache is
// shared with that screen (declared earlier, in the HR USERS & ROLES
// section) so both stay in sync from whichever loads last.
let _hrPermissionsCatalogCache=[];

async function ensureHrRolesLoaded(){
  if(_hrRolesCache.length)return _hrRolesCache;
  try{
    const r=await fetch(`${apiBaseUrl()}/hr/admin/roles`,{headers:backendHeaders()});
    if(r.ok)_hrRolesCache=await r.json();
  }catch(e){ /* dropdowns just stay empty on failure */ }
  return _hrRolesCache;
}

async function loadRolesAndPermissionsTab(){
  const tbody=document.getElementById('role-tbody');
  if(tbody)tbody.innerHTML='<tr><td colspan="5" style="color:var(--text3);text-align:center;padding:24px">Loading…</td></tr>';
  try{
    const [roleRes,permRes]=await Promise.all([
      fetch(`${apiBaseUrl()}/hr/admin/roles`,{headers:backendHeaders()}),
      fetch(`${apiBaseUrl()}/hr/admin/permissions`,{headers:backendHeaders()}),
    ]);
    _hrRolesCache=roleRes.ok?await roleRes.json():[];
    _hrPermissionsCatalogCache=permRes.ok?await permRes.json():[];
    renderRoleTable();
  }catch(e){
    if(tbody)tbody.innerHTML='<tr><td colspan="5" style="color:var(--red);text-align:center;padding:24px">Failed to load roles.</td></tr>';
  }
}

function renderRoleTable(){
  const tbody=document.getElementById('role-tbody');
  if(!tbody)return;
  if(!_hrRolesCache.length){
    tbody.innerHTML='<tr><td colspan="5" style="color:var(--text3);text-align:center;padding:24px">No roles yet.</td></tr>';
    return;
  }
  tbody.innerHTML=_hrRolesCache.map(r=>{
    const perms=r.permissions||[];
    const permBadges=perms.slice(0,6).map(p=>`<span class="b b-b" style="margin:1px 2px;font-size:9px">${escapeHtml(p)}</span>`).join('')
      +(perms.length>6?`<span style="font-size:10px;color:var(--text3)"> +${perms.length-6} more</span>`:'');
    const typeBadge=r.is_system_role?'<span class="b b-gray" title="Built-in default role">System</span>':'<span class="b b-b">Custom</span>';
    const editBtn=`<button class="icon-btn edit" title="Edit role" onclick="showRoleModal('${escapeHtml(r.id)}')">${editIconSvg()}</button>`;
    // Built-in roles can be edited (not renamed or deleted) — except the self-service Employee role.
    const actions=r.is_system_role
      ?(r.role_name==='Employee'?'<span style="font-size:11px;color:var(--text3)">Default role</span>':editBtn)
      :`<button class="icon-btn edit" title="Edit role" onclick="showRoleModal('${escapeHtml(r.id)}')">${editIconSvg()}</button> <button class="icon-btn danger" title="Delete role" onclick="deleteRole('${escapeHtml(r.id)}')">${deleteIconSvg()}</button>`;
    const deptScope=r.department_scope||[];
    const deptNote=deptScope.length
      ?`<div style="margin-top:4px;color:var(--accent);font-size:10.5px">Team: ${_deptScopeLabel(deptScope).map(escapeHtml).join(', ')}</div>`
      :'';
    return `<tr>
      <td style="font-weight:600">${escapeHtml(r.role_name)}</td>
      <td style="color:var(--text3);font-size:12px">${escapeHtml(r.description||'—')}${deptNote}</td>
      <td style="max-width:280px;line-height:1.8">${permBadges||'<span style="color:var(--text3)">—</span>'}</td>
      <td>${typeBadge}</td>
      <td style="white-space:nowrap">${actions}</td>
    </tr>`;
  }).join('');
}

async function deleteRole(id){
  const role=_hrRolesCache.find(r=>r.id===id);
  if(!role)return;
  if(!(await appConfirm({title:'Delete Role',message:`Delete role "${role.role_name}"? Any employees still assigned this role must be reassigned first.`,okText:'Delete'})))return;
  fetch(`${apiBaseUrl()}/hr/admin/roles/${id}`,{method:'DELETE',headers:backendHeaders()})
    .then(async r=>{
      if(r.ok){toast(`Role "${role.role_name}" deleted`,'ok');loadRolesAndPermissionsTab();}
      else{const d=await r.json().catch(()=>({}));toast(d.detail||'Failed to delete role','err');}
    })
    .catch(()=>toast('Cannot reach server','err'));
}

// Human names for the permission groups (the API sends raw keys such as
// "hr_workflow"). Order = the HRMS sidebar, then the main-dashboard modules.
const ROLE_MODULE_INFO={
  dashboard:{label:'Dashboards',section:'HRMS'},
  employees:{label:'Employees',section:'HRMS'},
  attendance:{label:'Attendance',section:'HRMS'},
  rota:{label:'Rota & Shift',section:'HRMS'},
  leave:{label:'Leave',section:'HRMS'},
  payroll:{label:'Payroll',section:'HRMS'},
  overtime:{label:'Overtime',section:'HRMS'},
  loans:{label:'Loans & Advances',section:'HRMS'},
  recruitment:{label:'Recruitment (ATS)',section:'HRMS'},
  performance:{label:'Performance, Training & Assets',section:'HRMS'},
  hr_workflow:{label:'Task Management',section:'HRMS'},
  reports:{label:'Reports & Analytics',section:'HRMS'},
  ai_insights:{label:'AI Insights',section:'HRMS'},
  hr_settings:{label:'HR Settings',section:'HRMS'},
  hr:{label:'HR Administration (roles, locations, GPS)',section:'HRMS'},
  sales:{label:'Sales & Invoices',section:'Main Dashboard'},
  quotations:{label:'Quotations',section:'Main Dashboard'},
  pos:{label:'Point of Sale',section:'Main Dashboard'},
  purchase:{label:'Purchases',section:'Main Dashboard'},
  inventory:{label:'Inventory',section:'Main Dashboard'},
  expense:{label:'Expenses',section:'Main Dashboard'},
  bank:{label:'Bank & Payments',section:'Main Dashboard'},
  accounting:{label:'Accounting',section:'Main Dashboard'},
  corporate:{label:'Corporate Accounting',section:'Main Dashboard'},
  notifications:{label:'Notifications',section:'Main Dashboard'},
  expert:{label:'Expert Review',section:'Main Dashboard'}
};
const ROLE_PERM_LABELS={
  view:'View',edit:'Edit',delete:'Delete',view_salary:'View salary figures',view_all_branches:'See all branches',
  manage_roles:'Manage roles',manage_locations:'Manage locations',manage_employees:'Manage employees',
  view_all_attendance:"View everyone's attendance",check_in_out:'Check in / out',view_own_attendance:'View own attendance',
  run_payroll:'Run payroll',view_payroll:'View payroll',admin:'Admin dashboard',hr:'HR dashboard',payroll:'Payroll dashboard',
  manager:'Manager dashboard',employee:'Employee dashboard'
};
function _roleModuleTitle(mod){return ROLE_MODULE_INFO[mod]?.label||mod.replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());}
function _rolePermTitle(name){return ROLE_PERM_LABELS[name]||name.replace(/_/g,' ').replace(/^\w/,c=>c.toUpperCase());}

function showRoleModal(id){
  const isEdit=!!id;
  const role=id?_hrRolesCache.find(r=>r.id===id):null;
  const modal=document.getElementById('m-role');
  if(!modal)return;
  modal.dataset.editId=id||'';
  document.getElementById('role-edit-id').value=id||'';
  const titleEl=document.getElementById('role-modal-title');
  if(titleEl)titleEl.textContent=isEdit?'Edit Role':'Add Custom Role';
  const subEl=document.getElementById('role-modal-sub');
  if(subEl)subEl.textContent=isEdit?`Editing role: ${role?.role_name||''}`:"Employees assigned this role will only see/do what's checked below — same permissions enforced everywhere (ESS portal, GPS attendance, dashboards)";
  const nameEl=document.getElementById('role-name');
  nameEl.value=role?.role_name||'';
  nameEl.readOnly=!!role?.is_system_role;
  nameEl.title=role?.is_system_role?'Built-in role names are fixed':'';
  document.getElementById('role-description').value=role?.description||'';

  const deptGrid=document.getElementById('role-dept-grid');
  if(deptGrid){
    const depts=_getDeptNames();
    const checkedDepts=new Set(role?.department_scope||[]);
    const ownCb=document.getElementById('role-dept-own');
    if(ownCb)ownCb.checked=checkedDepts.has('@own');
    deptGrid.innerHTML=depts.length
      ?depts.map(d=>`<label style="display:flex;align-items:center;gap:8px;font-size:13px;cursor:pointer"><input type="checkbox" class="role-dept-cb" value="${escapeHtml(d)}" ${checkedDepts.has(d)?'checked':''}> ${escapeHtml(d)}</label>`).join('')
      :'<div style="color:var(--text3);font-size:12px">No departments — add one in HR Settings first.</div>';
  }

  const grid=document.getElementById('role-perm-grid');
  if(grid){
    if(!_hrPermissionsCatalogCache.length){
      grid.innerHTML='<div style="color:var(--text3);font-size:12px">No permissions available.</div>';
    }else{
      const byModule={};
      _hrPermissionsCatalogCache.forEach(p=>{(byModule[p.module]=byModule[p.module]||[]).push(p);});
      const checked=new Set(role?.permissions||[]);
      const order=Object.keys(ROLE_MODULE_INFO);
      const rank=m=>{const i=order.indexOf(m);return i<0?order.length:i;};
      const mods=Object.keys(byModule).sort((a,b)=>rank(a)-rank(b)||a.localeCompare(b));
      let lastSection='';
      grid.innerHTML=mods.map(mod=>{
        const section=ROLE_MODULE_INFO[mod]?.section||'Other';
        const sectionHead=section!==lastSection
          ?`<div style="font-size:12px;font-weight:800;color:var(--accent);margin:${lastSection?'14px':'2px'} 0 2px;padding-bottom:4px;border-bottom:1px solid var(--border)">${escapeHtml(section)}</div>`:'';
        lastSection=section;
        return `${sectionHead}
        <div>
          <div style="font-size:11.5px;font-weight:700;letter-spacing:.2px;color:var(--text2);margin-bottom:6px">${escapeHtml(_roleModuleTitle(mod))}</div>
          <div style="display:grid;grid-template-columns:repeat(2,1fr);gap:8px">
            ${byModule[mod].map(p=>`<label style="display:flex;align-items:center;gap:8px;font-size:13px;cursor:pointer"><input type="checkbox" class="role-perm-cb" value="${escapeHtml(p.key)}" ${checked.has(p.key)?'checked':''}> ${escapeHtml(_rolePermTitle(p.permission_name))}</label>`).join('')}
          </div>
        </div>`;
      }).join('');
    }
  }
  const delBtn=document.getElementById('role-delete-btn');
  if(delBtn)delBtn.style.display=(isEdit&&!role?.is_system_role)?'':'none';
  showM('m-role');
}

async function saveRoleModal(){
  const modal=document.getElementById('m-role');
  const editId=modal?.dataset.editId||'';
  const roleName=(document.getElementById('role-name')?.value||'').trim();
  const description=(document.getElementById('role-description')?.value||'').trim()||null;
  const permissionKeys=[...document.querySelectorAll('#m-role .role-perm-cb:checked')].map(cb=>cb.value);
  // Keep permissions the grid doesn't offer (e.g. a module switched off for the company) instead of dropping them.
  const shown=new Set([...document.querySelectorAll('#m-role .role-perm-cb')].map(cb=>cb.value));
  const editing=editId?_hrRolesCache.find(r=>r.id===editId):null;
  (editing?.permissions||[]).forEach(k=>{if(!shown.has(k))permissionKeys.push(k);});
  const departmentScope=[...document.querySelectorAll('#m-role .role-dept-cb:checked')].map(cb=>cb.value);
  if(document.getElementById('role-dept-own')?.checked)departmentScope.push('@own'); // marker: only the login's own department
  if(!roleName){toast('Enter a role name','warn');return;}
  const body={role_name:roleName,description,permission_keys:permissionKeys,department_scope:departmentScope};
  try{
    const url=editId?`${apiBaseUrl()}/hr/admin/roles/${editId}`:`${apiBaseUrl()}/hr/admin/roles`;
    const r=await fetch(url,{method:editId?'PUT':'POST',headers:backendHeaders(),body:JSON.stringify(body)});
    if(r.ok){
      toast(editId?'Role updated':'Role created','ok');
      hideM('m-role');
      loadRolesAndPermissionsTab();
    }else{
      const d=await r.json().catch(()=>({}));
      toast(d.detail||'Failed to save role','err');
    }
  }catch(e){toast('Cannot reach server','err');}
}

function deleteRoleFromModal(){
  const modal=document.getElementById('m-role');
  const id=modal?.dataset.editId;
  if(!id)return;
  hideM('m-role');
  deleteRole(id);
}

async function filterEmpRoles(){
  const roleEl=document.getElementById('emp-role');
  if(!roleEl)return;
  const cur=roleEl.value;
  roleEl.innerHTML='<option value="">Loading roles…</option>';
  await ensureHrRolesLoaded();
  if(!_hrRolesCache.length){
    roleEl.innerHTML='<option value="">No roles yet — add one in HR Settings &gt; Roles &amp; Permissions</option>';
    return;
  }
  roleEl.innerHTML='<option value="">— Select Role —</option>'+
    _hrRolesCache.map(r=>`<option value="${escapeHtml(r.id)}">${escapeHtml(r.role_name)}</option>`).join('');
  if(cur)roleEl.value=cur;
}

function renderBranchTable(){
  // Header is Code | Branch Name | City/Emirate | Status | (actions) — 5
  // columns. Country/currency (reference-only, see BRANCH_COUNTRIES) is
  // folded into the City cell rather than given its own column so the
  // row shape matches the header exactly; previously this row emitted
  // country as its own 4th <td>, which silently pushed the status badge
  // into the actions column and left country data mislabeled under the
  // "Status" header — with no View/Edit buttons ever rendered at all.
  const canViewAs=_isAdminPrincipal();
  const row=b=>{
    const statusCls=b.status==='Active'?'b-g':'b-gray';
    const cityLabel=[b.city,b.country].filter(Boolean).join(', ')||'—';
    // Real login-as-branch (branches.py's impersonate_branch()). "View as"
    // (the lightweight client-only dashboard filter, viewDashboardAsBranch())
    // used to sit next to this -- removed by request, this is the only
    // branch switch offered here now. Restricted to Active branches: an
    // inactive branch isn't meant to be browsed day-to-day. data-branch-id +
    // a delegated lookup, not the name inlined into onclick="" -- a branch
    // name containing a quote/apostrophe there corrupts the HTML (same bug
    // class fixed elsewhere for POS/rota).
    const impersonateBtn=(canViewAs&&b.status==='Active')
      ?`<button class="btn btn-g btn-sm" style="padding:2px 8px;font-size:10.5px;color:var(--purple)" title="Log in as this branch's own dashboard session" data-branch-id="${escapeHtml(b.id)}" data-branch-name="${escapeHtml(b.name)}" onclick="impersonateBranch(this.dataset.branchId,this.dataset.branchName)">Impersonate</button>`
      :'';
    return `<tr>
      <td class="mono" style="font-size:11px">${escapeHtml(b.code||'—')}</td>
      <td style="font-weight:600">${escapeHtml(b.name)}</td>
      <td style="color:var(--text3);font-size:12px">${escapeHtml(cityLabel)}</td>
      <td><span class="b ${statusCls}">${escapeHtml(b.status)}</span></td>
      <td style="white-space:nowrap;display:flex;gap:4px;align-items:center">
        ${impersonateBtn}
        <button class="icon-btn" title="View branch" onclick="showBranchModal('${escapeHtml(b.id)}',true)">${viewIconSvg()}</button>
        <button class="icon-btn edit" title="Edit branch" onclick="showBranchModal('${escapeHtml(b.id)}')">${editIconSvg()}</button>
      </td>
    </tr>`;
  };
  const empty='<tr><td colspan="5" style="color:var(--text3);text-align:center;padding:24px">No branches yet. Click + Add Branch.</td></tr>';
  const html=_branchList.length?_branchList.map(row).join(''):empty;
  document.querySelectorAll('#branch-tbody').forEach(tb=>{tb.innerHTML=html;});
}

// GCC + UK — same list/derivation as signup.html's SIGNUP_COUNTRIES and
// superadmin.html's SA_CREATE_COUNTRIES. A branch may legitimately operate
// in a different country than its parent Company; this is reference data
// only (see the Branch model comment) — a branch's invoices/VAT still use
// the parent Company's own currency/vat_rate, unchanged.
const BRANCH_COUNTRIES=[
  {name:'United Arab Emirates',currency:'AED'},
  {name:'Saudi Arabia',currency:'SAR'},
  {name:'Bahrain',currency:'BHD'},
  {name:'Kuwait',currency:'KWD'},
  {name:'Oman',currency:'OMR'},
  {name:'Qatar',currency:'QAR'},
  {name:'United Kingdom',currency:'GBP'},
];

function populateBranchCountrySelect(selectedName){
  const sel=document.getElementById('branch-country');
  if(!sel)return;
  const known=BRANCH_COUNTRIES.some(c=>c.name===selectedName);
  const options=selectedName&&!known?[{name:selectedName,currency:''},...BRANCH_COUNTRIES]:BRANCH_COUNTRIES;
  sel.innerHTML=options.map(c=>`<option value="${escapeHtml(c.name)}"${c.name===selectedName?' selected':''}>${escapeHtml(c.name)}</option>`).join('');
  onBranchCountryChange();
}

function onBranchCountryChange(){
  const sel=document.getElementById('branch-country');
  const currencyEl=document.getElementById('branch-currency');
  if(!sel||!currencyEl)return;
  const match=BRANCH_COUNTRIES.find(c=>c.name===sel.value);
  currencyEl.value=match?.currency||'';
}

// Branch Login Phase 1 — the Main-Dashboard-business subset of company
// modules a Branch entity's own module toggle can restrict (kept in sync
// with backend/app/module_catalog.py::BRANCH_ELIGIBLE_MODULES by comment
// reference — deliberately excludes hrms/ess/settings, see that file's
// docstring for why).
const BRANCH_MODULE_DEFS=[
  {key:'sales',        label:'Sales & Invoices'},
  {key:'quotations',   label:'Quotations'},
  {key:'pos',          label:'Point of Sale'},
  {key:'purchase',     label:'Purchases'},
  {key:'inventory',    label:'Inventory'},
  {key:'expense',      label:'Expenses'},
  {key:'bank',         label:'Bank & Payments'},
  {key:'accounting',   label:'Accounting'},
  {key:'corporate',    label:'Corporate Accounting'},
  {key:'reports',      label:'Reports'},
  {key:'notifications',label:'Notifications'},
  {key:'expert',       label:'Expert Review'},
  {key:'exception',    label:'Exception Center'},
  {key:'ai',           label:'AI Features'},
];

function buildBranchModGrid(enabledKeysOrNull){
  const grid=document.getElementById('branch-mod-grid');
  if(!grid)return;
  // Company-disabled modules simply don't render as options at all here —
  // the backend still re-validates (branches.py::_validate_branch_modules),
  // this is UI convenience, not the enforcement boundary. window.
  // COMPANY_ALLOWED_MODULES is a Set when the company is restricted, or
  // null when unrestricted (see applyModulePermissionNav()).
  const companyAllowed=window.COMPANY_ALLOWED_MODULES;
  const offerable=BRANCH_MODULE_DEFS.filter(m=>!companyAllowed||companyAllowed.has(m.key));
  if(!offerable.length){
    grid.innerHTML='<div style="color:var(--text3);font-size:12px">No modules enabled for this company yet — enable modules in Settings first.</div>';
    return;
  }
  // NULL (new branch, or an existing branch never explicitly restricted)
  // pre-checks every offerable module, visually matching the NULL=
  // unrestricted convention. Saving from here always writes an explicit
  // array from then on (even if it equals the full offerable set) — same
  // trade-off already accepted for Company.modules_enabled's own admin UI.
  const checkedSet=new Set(enabledKeysOrNull===null?offerable.map(m=>m.key):enabledKeysOrNull);
  grid.innerHTML=offerable.map(m=>`
    <label style="display:flex;align-items:center;gap:8px;font-size:12.5px;cursor:pointer">
      <input type="checkbox" class="branch-mod-cb" value="${escapeHtml(m.key)}" ${checkedSet.has(m.key)?'checked':''}>
      ${escapeHtml(m.label)}
    </label>`).join('');
}

function getCheckedBranchModules(){
  return [...document.querySelectorAll('#branch-mod-grid .branch-mod-cb:checked')].map(cb=>cb.value);
}

// viewOnly renders the same modal read-only (fields disabled, Save hidden)
// instead of a separate view modal — Branches / Locations offers View +
// Edit per row but Delete was deliberately dropped entirely (not just from
// the table), so branch-delete-btn always stays hidden here regardless of
// mode; deleteBranch()/deleteBranchFromModal() are kept for the seeded
// scripts/history that reference them but are unreachable from this UI.
function showBranchModal(id,viewOnly){
  const titleEl=document.getElementById('branch-modal-title');
  const b=id?_branchList.find(x=>x.id===id):null;
  if(titleEl)titleEl.textContent=viewOnly?'View Branch':(b?'Edit Branch':'Add Branch');
  document.getElementById('branch-edit-id').value=id||'';
  document.getElementById('branch-name').value=b?.name||'';
  document.getElementById('branch-code').value=b?.code||'';
  document.getElementById('branch-city').value=b?.city||'';
  document.getElementById('branch-status').value=b?.status||'Active';
  populateBranchCountrySelect(b?.country||currentCompany?.country||'United Arab Emirates');
  buildBranchModGrid(b?(b.modules_enabled??null):null);
  document.getElementById('branch-username').value=b?.username||'';
  document.getElementById('branch-password').value='';
  const pwHint=document.getElementById('branch-pw-hint');
  if(pwHint)pwHint.textContent=b?.has_password?'(leave blank to keep current password)':'(required to enable branch login)';
  const delBtn=document.getElementById('branch-delete-btn');
  if(delBtn)delBtn.style.display='none';
  ['branch-name','branch-code','branch-city','branch-status','branch-country','branch-username','branch-password'].forEach(fid=>{
    const el=document.getElementById(fid);
    if(el)el.disabled=!!viewOnly;
  });
  document.querySelectorAll('#branch-mod-grid input').forEach(cb=>{cb.disabled=!!viewOnly;});
  const saveBtn=document.getElementById('branch-save-btn');
  if(saveBtn)saveBtn.style.display=viewOnly?'none':'';
  const cancelBtn=document.getElementById('branch-cancel-btn');
  if(cancelBtn)cancelBtn.textContent=viewOnly?'Close':'Cancel';
  showM('m-branch');
  if(!viewOnly)setTimeout(()=>document.getElementById('branch-name').focus(),120);
}

async function saveBranchModal(){
  const name=(document.getElementById('branch-name')?.value||'').trim();
  if(!name){toast('Branch name is required','err');return;}
  const id=document.getElementById('branch-edit-id')?.value;
  const payload={
    name,
    code:(document.getElementById('branch-code')?.value||'').trim().toUpperCase().slice(0,6)||name.slice(0,3).toUpperCase(),
    city:(document.getElementById('branch-city')?.value||'').trim(),
    country:(document.getElementById('branch-country')?.value||'').trim(),
    currency:(document.getElementById('branch-currency')?.value||'').trim(),
    status:document.getElementById('branch-status')?.value||'Active',
    modules_enabled:getCheckedBranchModules(),
  };
  // Branch Login Phase 2: username/password are optional and omitted
  // entirely when left blank — never sent as an empty string, which would
  // null out an existing credential on an edit save (same "None = don't
  // touch" convention as set_employee_portal_access's own PUT endpoint).
  const branchUsername=(document.getElementById('branch-username')?.value||'').trim();
  if(branchUsername)payload.username=branchUsername;
  const branchPassword=document.getElementById('branch-password')?.value||'';
  if(branchPassword){
    if(branchPassword.length<6){toast('Branch password must be at least 6 characters','warn');return;}
    payload.password=branchPassword;
  }
  if(_branchList.find(x=>x.name.toLowerCase()===name.toLowerCase()&&x.id!==id)){toast('Branch name already exists','warn');return;}
  try{
    const response=await authenticatedFetch(`${apiBaseUrl()}/branches${id?'/'+id:''}`,{
      method:id?'PUT':'POST',
      body:JSON.stringify(payload),
    });
    if(!response.ok)throw new Error('Save failed ('+response.status+')');
    const saved=await response.json();
    if(id){
      const idx=_branchList.findIndex(x=>x.id===id);
      if(idx>=0)_branchList[idx]=saved;
    } else {
      _branchList.push(saved);
    }
    hideM('m-branch');
    renderBranchTable();
    _syncBranchSelects(_branchList.filter(b=>b.status!=='Inactive').map(b=>b.name));
    toast(`Branch "${name}" ${id?'updated':'added'}`,'ok');
  }catch(err){toast('Save failed: '+err.message,'err');}
}

async function deleteBranch(id){
  const b=_branchList.find(x=>x.id===id);
  if(!b)return;
  if(!(await appConfirm({title:'Remove Branch',message:`Remove branch "${b.name}"?`,okText:'Remove'})))return;
  try{
    const response=await authenticatedFetch(`${apiBaseUrl()}/branches/${id}`,{method:'DELETE'});
    if(!response.ok)throw new Error('Delete failed ('+response.status+')');
    _branchList=_branchList.filter(x=>x.id!==id);
    renderBranchTable();
    _syncBranchSelects(_branchList.filter(x=>x.status!=='Inactive').map(x=>x.name));
    toast(`Branch "${b.name}" removed`,'ok');
  }catch(err){toast('Delete failed: '+err.message,'err');}
}

function deleteBranchFromModal(){
  const id=document.getElementById('branch-edit-id')?.value;
  if(!id)return;
  hideM('m-branch');
  deleteBranch(id);
}

function addHrBranch(){showBranchModal();}
function removeHrBranch(btn,name){
  const b=_branchList.find(x=>x.name===name);
  if(b)deleteBranch(b.id);
}

function refreshExpiryAlerts(){
  const tbody=document.getElementById('expiry-tbody');
  if(!tbody)return;
  const empRows=[...document.querySelectorAll('#employee-tbody tr:not([data-empty-state])')];
  if(!empRows.length){
    tbody.innerHTML='<tr data-empty-state><td colspan="6" style="text-align:center;color:var(--text3);padding:32px">Add employees with document expiry dates to see alerts here.</td></tr>';
    ['expiry-30','expiry-90','expiry-valid','expiry-missing','hrms-dash-expiry'].forEach(id=>{const el=document.getElementById(id);if(el)el.textContent='0';});
    return;
  }
  const today=new Date();today.setHours(0,0,0,0);
  const docs=[];
  empRows.forEach(row=>{
    const emp=employeeFromDirectoryRow(row);
    // A departed employee's visa/EID/etc. isn't actionable HR work — don't
    // alert on it (same "Inactive stays in the Directory, not anywhere
    // else" rule as the employee-picker dropdowns).
    if(!emp.name||emp.status==='Inactive')return;
    const add=(label,dateStr)=>{
      if(!dateStr)return docs.push({emp:emp.name,label,date:null,days:null});
      // Parsed as LOCAL midnight (matching `today` above), not UTC midnight
      // — new Date("2026-08-27") parses as 2026-08-27T00:00:00Z, which in
      // any timezone ahead of UTC (e.g. UAE, +4) is still "yesterday
      // evening" locally. Diffing that against a local-midnight `today`
      // made every expiry look ~1 day further away than it really is — a
      // document expiring TODAY showed "Due in 1 day" instead of "Expired".
      const d=new Date(`${dateStr}T00:00:00`);if(isNaN(d))return docs.push({emp:emp.name,label,date:null,days:null});
      const days=Math.round((d-today)/86400000);
      docs.push({emp:emp.name,label,date:d,days,dateStr});
    };
    add('Visa / Work Permit',emp.visa_expiry||emp.visaExpiry);
    add('Passport',emp.passport_expiry||emp.passportExpiry);
    add('Emirates ID',emp.eid_expiry||emp.eidExpiry);
    add('Insurance',emp.insurance_expiry||emp.insuranceExpiry);
    add('Driving License',emp.driving_expiry||emp.drivingExpiry);
    // Previously never scanned at all, despite this tracker's own card-sub
    // text already advertising "...Labor Card" as covered.
    add('Labor Card',emp.labor_card_expiry||emp.laborCardExpiry);
  });
  let cnt30=0,cnt90=0,cntValid=0,cntMissing=0;
  const typeCnt30={passport:0,visa:0,eid:0,insurance:0,driving:0};
  docs.forEach(d=>{
    if(d.days===null){cntMissing++;return;}
    if(d.days<=30){
      cnt30++;
      if(d.label==='Passport')typeCnt30.passport++;
      else if(d.label==='Visa / Work Permit')typeCnt30.visa++;
      else if(d.label==='Emirates ID')typeCnt30.eid++;
      else if(d.label==='Insurance')typeCnt30.insurance++;
      else if(d.label==='Driving License')typeCnt30.driving++;
    } else if(d.days<=90)cnt90++;
    else cntValid++;
  });
  const set=(id,v)=>{const el=document.getElementById(id);if(el)el.textContent=v;};
  set('expiry-30',cnt30);set('expiry-90',cnt90);set('expiry-valid',cntValid);set('expiry-missing',cntMissing);
  // Update dashboard compliance alert counters
  set('hrms-compl-passport',typeCnt30.passport);
  set('hrms-compl-visa',typeCnt30.visa);
  set('hrms-compl-eid',typeCnt30.eid);
  set('hrms-compl-ins',typeCnt30.insurance);
  set('hrms-dash-expiry',cnt30);
  // Update document expiry bar chart (counts expiring within 90 days)
  const typeAll={passport:0,visa:0,eid:0,insurance:0,driving:0};
  docs.forEach(d=>{if(d.days!==null&&d.days<=90){
    if(d.label==='Passport')typeAll.passport++;
    else if(d.label==='Visa / Work Permit')typeAll.visa++;
    else if(d.label==='Emirates ID')typeAll.eid++;
    else if(d.label==='Insurance')typeAll.insurance++;
    else if(d.label==='Driving License')typeAll.driving++;
  }});
  const maxBar=Math.max(1,typeAll.passport,typeAll.visa,typeAll.eid,typeAll.insurance,typeAll.driving);
  const setBar=(valId,barId,n)=>{set(valId,n);const el=document.getElementById(barId);if(el)el.style.height=Math.round(n/maxBar*90)+'px';};
  setBar('hrms-expbar-passport-val','hrms-expbar-passport-bar',typeAll.passport);
  setBar('hrms-expbar-visa-val','hrms-expbar-visa-bar',typeAll.visa);
  setBar('hrms-expbar-eid-val','hrms-expbar-eid-bar',typeAll.eid);
  setBar('hrms-expbar-ins-val','hrms-expbar-ins-bar',typeAll.insurance);
  setBar('hrms-expbar-drv-val','hrms-expbar-drv-bar',typeAll.driving);
  const badge=document.getElementById('hrms-badge-expiry');
  if(badge)badge.textContent=(cnt30+cnt90)+' alerts';
  const toShow=docs.filter(d=>d.days!==null&&d.days<=90).sort((a,b)=>a.days-b.days);
  if(!toShow.length){
    tbody.innerHTML='<tr data-empty-state><td colspan="6" style="text-align:center;color:var(--text3);padding:32px">No documents expiring within 90 days.</td></tr>';
    return;
  }
  tbody.innerHTML='';
  toShow.forEach(d=>{
    const cls=d.days<=30?'b-r':d.days<=60?'b-a':'b-g';
    const status=d.days<=0?'Expired':d.days<=30?'Critical':d.days<=60?'Warning':'Due Soon';
    const tr=document.createElement('tr');
    tr.innerHTML=`<td>${escapeHtml(d.emp)}</td><td>${escapeHtml(d.label)}</td><td class="mono">${d.dateStr}</td><td class="mono" ${d.days<=30?'style="color:var(--red);font-weight:600"':d.days<=60?'style="color:var(--amber)"':''}>${d.days} days</td><td><span class="b ${cls}">${status}</span></td><td><button class="btn btn-g btn-sm" onclick="toast('Open employee record to update document','info')">Update</button></td>`;
    tbody.appendChild(tr);
  });
}

function calcLoanEmi(){
  const amount=parseFloat(document.getElementById('loan-amount')?.value)||0;
  const months=parseInt(document.getElementById('loan-months')?.value)||1;
  const emiEl=document.getElementById('loan-emi');
  if(emiEl&&amount&&months)emiEl.value=(amount/months).toFixed(2);
}

function saveLoan(){
  const empSel=document.getElementById('loan-employee');
  const emp=empSel?.value||'';
  const empId=empSel?.selectedOptions?.[0]?.dataset.empId||'';
  const type=document.getElementById('loan-type')?.value||'Personal Loan';
  const amount=parseFloat(document.getElementById('loan-amount')?.value)||0;
  const months=parseInt(document.getElementById('loan-months')?.value)||1;
  const reason=document.getElementById('loan-reason')?.value.trim()||'';
  const date=document.getElementById('loan-date')?.value||new Date().toISOString().slice(0,10);
  const deductFrom=document.getElementById('loan-deduct-from')?.value||'';
  if(!emp||!amount){toast('Employee and amount are required','warn');return;}
  const emi=parseFloat((amount/months).toFixed(2));
  const record={id:`LN-${Date.now()}`,employee:emp,employee_id:empId,type,amount,emi,months,balance:amount,deduct_from:deductFrom,reason,date,status:'Pending'};
  renderLoanRecord(record);
  saveServer('employeeLoans',record);
  closeM('m-loan');
  toast(`Loan request for ${emp} submitted ✓`,'ok');
  audit('Loan request submitted',emp,'Pending');
}

function renderLoanRecord(rec){
  const tbody=document.getElementById('loans-tbody');
  if(!tbody)return;
  if(tbody.querySelector(`[data-record-id="${CSS.escape(rec.id)}"]`))return;
  removeEmptyState(tbody);
  const statusCls=rec.status==='Approved'?'b-g':rec.status==='Rejected'?'b-r':'b-a';
  const isPending=rec.status==='Pending'||!rec.status;
  const actions=isPending
    ?`<div class="flx"><button class="btn btn-success btn-sm" onclick="approveLoan(this)">Approve</button><button class="btn btn-danger btn-sm" onclick="rejectLoan(this)">Reject</button></div>`
    :`<button class="btn btn-g btn-sm" onclick="toast('Loan detail','info')">View</button>`;
  const amount=Number(rec.amount)||0;
  const balance=Number(rec.balance??rec.amount)||0;
  const tr=document.createElement('tr');
  tr.dataset.recordId=rec.id;
  tr.dataset.record=JSON.stringify(rec);
  tr.innerHTML=`<td>${escapeHtml(rec.employee)}</td><td>${escapeHtml(rec.type)}</td><td class="mono">${formatAed(amount)}</td><td class="mono">${formatAed(rec.emi)}</td><td class="mono">${formatAed(balance)}</td><td><span class="b ${statusCls}">${escapeHtml(rec.status||'Pending')}</span></td><td>${actions}</td>`;
  tbody.prepend(tr);
  _refreshPayrollLoansCard();
}

// The Payroll page's own "Loans, Advances & Recurring Deductions" card used
// to be static demo markup with a fake "+ New Advance" toast — it never
// showed any of this real data even though the feature (Employee
// Loans/Salary Advances tabs above) was already fully working. Mirrors
// only Approved records (Rejected/Pending don't affect payroll yet) by
// reading the two source tables' own dataset.record, so there's a single
// source of truth and this card can't drift from what HR actually approved.
function _refreshPayrollLoansCard(){
  const target=document.getElementById('pay-loans-tbody');
  if(!target)return;
  const rows=[];
  document.querySelectorAll('#loans-tbody tr[data-record-id]').forEach(tr=>{
    let rec={};try{rec=JSON.parse(tr.dataset.record||'{}');}catch{}
    if(rec.status!=='Approved')return;
    const balance=Number(rec.balance??rec.amount)||0;
    if(balance<=0)return;
    rows.push({employee:rec.employee,type:rec.type||'Loan',original:Number(rec.amount)||0,monthly:Number(rec.emi)||0,balance,start:rec.deduct_from||rec.date||'—',status:rec.status});
  });
  document.querySelectorAll('#advances-tbody tr[data-record-id]').forEach(tr=>{
    let rec={};try{rec=JSON.parse(tr.dataset.record||'{}');}catch{}
    if(rec.status!=='Approved')return;
    const amount=Number(rec.amount)||0;
    rows.push({employee:rec.employee,type:'Salary Advance',original:amount,monthly:amount,balance:amount,start:rec.month||'—',status:rec.status});
  });
  if(!rows.length){emptyTableMessage(target,'No approved loans or advances yet.');return;}
  target.innerHTML=rows.map(r=>`<tr><td>${escapeHtml(r.employee)}</td><td>${escapeHtml(r.type)}</td><td class="mono">${formatAed(r.original)}</td><td class="mono">${formatAed(r.monthly)}</td><td class="mono">${formatAed(r.balance)}</td><td>${escapeHtml(r.start)}</td><td><span class="b b-g">${escapeHtml(r.status)}</span></td></tr>`).join('');
}

// Previously saved only {id,status} — save_app_record() does a full payload
// overwrite, not a merge, so that silently destroyed employee_id/balance/
// emi on approval, and _employee_loan_deductions() (payroll.py) could never
// match the record again — every approved loan deducted AED 0.00 forever.
// Spreading the full stored record first (same pattern approveOT() uses)
// keeps them intact.
function approveLoan(btn){
  const row=btn.closest('tr');
  row.querySelector('.b').className='b b-g';
  row.querySelector('.b').textContent='Approved';
  row.querySelector('td:last-child').innerHTML='<button class="btn btn-g btn-sm" onclick="toast(\'Loan detail\',\'info\')">View</button>';
  let payload={};try{payload=JSON.parse(row.dataset.record||'{}');}catch{}
  payload={...payload,status:'Approved'};
  row.dataset.record=JSON.stringify(payload);
  const id=row.dataset.recordId;
  if(id)saveServer('employeeLoans',{...payload,id});
  toast('Loan approved ✓','ok');
  audit('Loan approved',row.children[0]?.textContent||'','Approved');
  _refreshPayrollLoansCard();
}

function rejectLoan(btn){
  const row=btn.closest('tr');
  row.querySelector('.b').className='b b-r';
  row.querySelector('.b').textContent='Rejected';
  row.querySelector('td:last-child').innerHTML='<button class="btn btn-g btn-sm" onclick="toast(\'Loan detail\',\'info\')">View</button>';
  let payload={};try{payload=JSON.parse(row.dataset.record||'{}');}catch{}
  payload={...payload,status:'Rejected'};
  row.dataset.record=JSON.stringify(payload);
  const id=row.dataset.recordId;
  if(id)saveServer('employeeLoans',{...payload,id});
  toast('Loan rejected','warn');
  audit('Loan rejected',row.children[0]?.textContent||'','Rejected');
  _refreshPayrollLoansCard();
}

