async function saveActiveRotaAssignmentFromModal(forceOff=false){
  if(!activeRotaCell){
    toast('Select a rota cell first','warn');
    return null;
  }
  const type=forceOff?'Off':document.getElementById('rota-edit-type')?.value||'Morning';
  const defaults=ROTA_EDIT_DEFAULTS[type]||ROTA_EDIT_DEFAULTS.Morning;
  const mark=forceOff?'Off':document.getElementById('rota-edit-mark')?.value||defaults.mark;
  const start=forceOff?'':document.getElementById('rota-edit-start')?.value||defaults.start;
  const end=forceOff?'':document.getElementById('rota-edit-end')?.value||defaults.end;
  // "Training" previously fell through to defaults.className/defaults.code
  // (whatever the selected Shift Type was, e.g. Morning -> 'M'/'approved')
  // — a training day rendered pixel-for-pixel identical to a real worked
  // shift, with no way to tell them apart on the board.
  const className=mark==='Off'?'off':mark==='Leave'?'draft':mark==='OT'?'overtime':mark==='Holiday'?'holiday':mark==='Training'?'training':defaults.className;
  const code=mark==='Off'?'OFF':mark==='Leave'?'L':mark==='OT'?'OT':mark==='Holiday'?'PH':mark==='Training'?'TR':defaults.code;
  const existing=activeRotaCell.dataset.assignment?normalizeRotaAssignment(JSON.parse(activeRotaCell.dataset.assignment)):{};
  const assignment=normalizeRotaAssignment({
    ...existing,
    employee_id:activeRotaCell.dataset.employeeId,
    employee_name:activeRotaCell.dataset.employeeName,
    role:activeRotaCell.dataset.role,
    department:activeRotaCell.dataset.department,
    location:activeRotaCell.dataset.location,
    date:activeRotaCell.dataset.date,
    day:activeRotaCell.dataset.day,
    type,
    code,
    start,
    end,
    mark,
    className,
    break_minutes:forceOff?0:Number(document.getElementById('rota-edit-break')?.value)||0,
    notes:forceOff?'':document.getElementById('rota-edit-notes')?.value||'',
    tasks:forceOff?[]:await _collectRotaEditTasks(),
    status:document.getElementById('rota-weekly-status')?.textContent?.trim()||'Draft',
    updated_at:new Date().toISOString()
  });
  // The cell's own dataset/innerHTML and rotaAssignmentsById used to be
  // updated BEFORE (and regardless of) the server save even being
  // attempted, and saveServer() swallows failures silently by default (a
  // 401 from an expired session, a network blip, a 500) -- so a failed
  // save still looked identical to a successful one for the rest of this
  // browser session: the cell showed the new shift/tasks, the modal
  // closed, a "Shift saved to database" toast fired. Only a later reload
  // (re-fetching from the server, which never received the write)
  // revealed nothing had actually been saved -- indistinguishable from
  // data loss even though the save itself never silently corrupted
  // anything. Now the local state only changes after a confirmed write.
  try{
    await saveServer('rotaAssignments',assignment,{throwOnError:true});
  }catch(err){
    console.warn('Rota assignment save failed:',err);
    return {...assignment,_saveFailed:true,_saveError:err?.serverDetail||''};
  }
  activeRotaCell.dataset.assignment=JSON.stringify(assignment);
  activeRotaCell.innerHTML=rotaCellHtml(assignment);
  rotaAssignmentsById.set(assignment.id,assignment);
  _syncMonthPickerToWeek(assignment.date);
  renderRotaBoards();
  return assignment;
}

async function saveRotaCellShift(){
  if(!hrmsCan('rota:edit')){toast('Your role can view the rota but not change it','warn');return;}
  const assignment=await saveActiveRotaAssignmentFromModal(false);
  if(!assignment)return;
  if(assignment._saveFailed){
    toast(assignment._saveError
      ?`Could not save this shift: ${assignment._saveError}`
      :'Could not save this shift — check your connection (or that you\'re still signed in) and try again','err');
    return;
  }
  closeM('m-edit-shift');
  toast('Shift saved to database','ok');
  audit('Updated rota cell',`${assignment.employee_name} ${assignment.date}`,'Saved');
}

async function removeRotaCellShift(){
  if(!hrmsCan('rota:edit')){toast('Your role can view the rota but not change it','warn');return;}
  const assignment=await saveActiveRotaAssignmentFromModal(true);
  if(!assignment)return;
  if(assignment._saveFailed){
    toast(assignment._saveError
      ?`Could not remove this shift: ${assignment._saveError}`
      :'Could not remove this shift — check your connection (or that you\'re still signed in) and try again','err');
    return;
  }
  closeM('m-edit-shift');
  toast('Shift removed','warn');
  audit('Removed rota cell',`${assignment.employee_name} ${assignment.date}`,'Deleted');
}

function syncRotaWeekFromDept(){
  const deptWeek=document.getElementById('rota-dept-week-start')?.value;
  if(deptWeek)setFieldValue(document.getElementById('rota-week-start'),deptWeek);
  _syncMonthPickerToWeek(deptWeek);
  renderRotaBoards();
}

function filteredRotaStaff(scope='week'){
  const department=document.getElementById(scope==='month'?'rota-month-department':scope==='dept'?'rota-dept-department':'rota-week-department')?.value||'All Departments';
  const search=(document.getElementById(scope==='month'?'rota-month-search':'rota-staff-search')?.value||'').toLowerCase();
  return currentRotaStaff().filter(staff=>{
    const deptOk=department==='All Departments'||staff.department===department;
    const searchOk=!search||staff.name.toLowerCase().includes(search)||staff.role.toLowerCase().includes(search);
    return deptOk&&searchOk;
  });
}

function assignmentFor(staff,date,day){
  const existing=rotaAssignmentsById.get(rotaAssignmentId(staff.id,date));
  if(existing)return existing;
  return normalizeRotaAssignment({
    id:rotaAssignmentId(staff.id,date),
    employee_id:staff.id,
    employee_name:staff.name,
    role:staff.role,
    department:staff.department,
    location:staff.location,
    date,
    day,
    type:'Off',
    code:'OFF',
    start:'',
    end:'',
    mark:'Off',
    className:'off'
  });
}

// If a company's own roster is somehow bigger than ROTA_STAFF_DISPLAY_CAP,
// say so on screen instead of silently dropping the rest with no signal.
// Counts active employees only (same filter as currentRotaStaff(), computed
// separately here rather than via currentRotaStaff().length since that
// function's own return value is already capped at ROTA_STAFF_DISPLAY_CAP
// — using it here would make "showing N of total" always report total<=cap
// and this notice would never fire).
function _rotaTruncationNoticeHtml(){
  const total=[...document.querySelectorAll('#employee-tbody tr:not([data-empty-state])')]
    .map(row=>employeeFromDirectoryRow(row))
    .filter(emp=>emp?.id&&emp?.name&&(emp.status||'Active')!=='Inactive').length;
  if(total<=ROTA_STAFF_DISPLAY_CAP)return '';
  return `<div class="empty-card" style="color:var(--amber);margin-bottom:8px">Showing the first ${ROTA_STAFF_DISPLAY_CAP} of ${total} employees — use the Department filter to narrow this down.</div>`;
}

// Set by clicking an employee's name in Staff Schedule (see
// selectRotaStaffForTasks()) -- drives the "Employee Tasks" side panel
// that replaced Weekly Summary's old top slot (Weekly Summary itself
// just moved down one card, unchanged otherwise).
let selectedRotaStaffId=null;

function selectRotaStaffForTasks(staffId){
  selectedRotaStaffId=(selectedRotaStaffId===staffId)?null:staffId; // click again to deselect
  renderWeeklyRotaBoard();
  renderRotaEmployeeTasksPanel();
}

function renderRotaEmployeeTasksPanel(){
  const body=document.getElementById('rota-emp-tasks-body');
  const titleEl=document.querySelector('#rota-emp-tasks-card .card-title');
  if(!body)return;
  const staff=filteredRotaStaff('week').find(s=>s.id===selectedRotaStaffId);
  if(!staff){
    if(titleEl)titleEl.textContent='Employee Tasks';
    body.innerHTML='<div class="rota-emp-tasks-empty">Click an employee\'s name in Staff Schedule to see their tasks for the week.</div>';
    return;
  }
  if(titleEl)titleEl.textContent=`${staff.name} — This Week`;
  const start=weekStartValue();
  const dayBlocks=ROTA_WEEK_DAYS.map((day,index)=>{
    const date=weekDateFromStart(start,index);
    const assignment=assignmentFor(staff,date,day);
    const tasks=Array.isArray(assignment.tasks)?assignment.tasks:[];
    if(!tasks.length)return '';
    const dateLabel=`${day} ${date.slice(8,10)}/${date.slice(5,7)}`;
    const taskRows=tasks.map(t=>{
      const time=t.start&&t.end?`${t.start}–${t.end}`:(t.start||t.end||'');
      return `<div class="rota-emp-task-row"><span class="rota-emp-task-dot" style="background:${escapeHtml(t.color||TASK_COLORS[0])}"></span><span class="rota-emp-task-title">${escapeHtml(t.title||'Untitled task')}</span><span class="rota-emp-task-time">${escapeHtml(time)}</span></div>`;
    }).join('');
    return `<div class="rota-emp-tasks-day">${escapeHtml(dateLabel)}</div>${taskRows}`;
  }).filter(Boolean).join('');
  body.innerHTML=dayBlocks||`<div class="rota-emp-tasks-empty">No tasks scheduled this week for ${escapeHtml(staff.name)}.</div>`;
}

// The weekly/monthly boards are grids of every staff member x every day (~4,300 buttons
// for a 5-week month at 124 staff: ~0.8 s to build) and renderRotaBoards() runs at every
// start-up and change, usually while their tab is closed. A hidden board is skipped and
// marked stale; it is drawn when it becomes visible (tab click, section switch, any
// route), watched with an IntersectionObserver. Only these draw functions touch the
// boards' DOM, so nothing else reads a skipped board.
var _rotaBoardStale=new Map();   // board element -> its draw function
var _rotaBoardObserver=null;
function _skipHiddenRotaBoard(board,draw){
  if(board.getClientRects().length){_rotaBoardStale.delete(board);return false;}
  _rotaBoardStale.set(board,draw);
  if(!_rotaBoardObserver&&typeof IntersectionObserver==='function'){
    _rotaBoardObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{
      const pending=_rotaBoardStale.get(entry.target);
      if(entry.isIntersecting&&pending)pending();
    }));
  }
  if(!_rotaBoardObserver)return false;  // no observer support: draw now, as before
  _rotaBoardObserver.observe(board);
  return true;
}

function renderWeeklyRotaBoard(){
  const board=document.getElementById('rota-weekly-board');
  if(!board)return;
  if(_skipHiddenRotaBoard(board,renderWeeklyRotaBoard))return;
  const start=weekStartValue();
  const staffRows=filteredRotaStaff('week');
  const notice=_rotaTruncationNoticeHtml();
  if(!staffRows.length){
    board.innerHTML=notice+'<div class="empty-card">No staff found for this filter.</div>';
    return;
  }
  board.innerHTML=notice+staffRows.map(staff=>{
    const cells=ROTA_WEEK_DAYS.map((day,index)=>{
      const date=weekDateFromStart(start,index);
      const assignment=assignmentFor(staff,date,day);
      return `<button class="rota-day-cell" type="button" onclick="openRotaCellEditor(this)" data-assignment="${escapeHtml(JSON.stringify(assignment))}" data-employee-id="${escapeHtml(staff.id)}" data-employee-name="${escapeHtml(staff.name)}" data-role="${escapeHtml(staff.role)}" data-department="${escapeHtml(staff.department)}" data-location="${escapeHtml(staff.location)}" data-date="${escapeHtml(date)}" data-day="${escapeHtml(day)}"><small>${escapeHtml(day)} ${escapeHtml(date.slice(8))}</small>${rotaCellHtml(assignment)}</button>`;
    }).join('');
    const total=ROTA_WEEK_DAYS.reduce((sum,day,index)=>sum+rotaHours(assignmentFor(staff,weekDateFromStart(start,index),day)),0);
    const rowSelected=staff.id===selectedRotaStaffId?' rota-staff-row-selected':'';
    return `<div class="rota-staff-row${rowSelected}"><div class="rota-staff-meta" onclick="selectRotaStaffForTasks('${escapeHtml(staff.id)}')" title="Click to see this employee's tasks for the week"><strong>${escapeHtml(staff.name)}</strong><span>${escapeHtml(staff.role)} · ${escapeHtml(staff.department)}</span><em>${total.toFixed(1)} hrs</em></div><div class="rota-day-grid">${cells}</div></div>`;
  }).join('');
}

function selectedWeekAssignments(scope='week'){
  const start=scope==='dept'?(document.getElementById('rota-dept-week-start')?.value||weekStartValue()):weekStartValue();
  const staffRows=filteredRotaStaff(scope);
  const ids=new Set(staffRows.map(staff=>staff.id));
  const dates=new Set(ROTA_WEEK_DAYS.map((day,index)=>weekDateFromStart(start,index)));
  return [...rotaAssignmentsById.values()].filter(item=>ids.has(item.employee_id)&&dates.has(item.date));
}

function renderRotaSummary(){
  const weeklyBody=document.getElementById('rota-weekly-summary-tbody');
  const weekly=selectedWeekAssignments('week');
  const staffCount=new Set(weekly.map(item=>item.employee_id)).size||filteredRotaStaff('week').length;
  const scheduled=weekly.reduce((sum,item)=>sum+rotaHours(item),0);
  const ot=weekly.filter(item=>item.code==='OT').length;
  const leave=weekly.filter(item=>item.code==='L').length;
  const off=weekly.filter(item=>item.code==='OFF').length;
  if(weeklyBody)weeklyBody.innerHTML=`<tr><td>Total Staff</td><td class="mono">${staffCount}</td></tr><tr><td>Scheduled Hours</td><td class="mono">${scheduled.toFixed(1)}</td></tr><tr><td>Overtime Cells</td><td class="mono" style="color:var(--purple)">${ot}</td></tr><tr><td>Leave Days</td><td class="mono" style="color:var(--amber)">${leave}</td></tr><tr><td>Off Days</td><td class="mono">${off}</td></tr>`;
}

// Monday on/before the given date, as YYYY-MM-DD. See weekDateFromStart()'s
// comment for why this reads local date components back out instead of
// going through toISOString().
function _mondayOnOrBefore(dateStr){
  const d=new Date(`${dateStr}T00:00:00`);
  const dow=d.getDay()||7; // Mon=1..Sun=7
  d.setDate(d.getDate()-(dow-1));
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
}

// Standard ISO-8601 week number (the week containing that date's Thursday) —
// matches the "Week N" labeling convention of a typical manually-built
// staff rota spreadsheet.
function _isoWeekNumber(dateStr){
  const d=new Date(`${dateStr}T00:00:00`);
  d.setDate(d.getDate()+4-(d.getDay()||7));
  const yearStart=new Date(d.getFullYear(),0,1);
  return Math.ceil((((d-yearStart)/86400000)+1)/7);
}

const ROTA_MONTH_DAY_NAMES=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];

// The full Mon-Sun week range Monthly Rota needs for `month` ("YYYY-MM"): every week that
// touches the month, spilling a day or two into the adjacent month at each end (same as a
// real weekly-numbered rota sheet) rather than clipping mid-week. Shared by
// renderMonthlyRotaBoard() (which weeks to draw) and _ensureRotaRangeLoaded() (what date
// range to fetch) so the two can never disagree about what "this month" covers.
function _monthRotaWeekStarts(month){
  const [y,m]=(month||'').split('-').map(Number);
  if(!y||!m)return null;
  const monthStart=`${month}-01`;
  const monthEnd=`${month}-${String(new Date(y,m,0).getDate()).padStart(2,'0')}`;
  const weekStarts=[];
  for(let cursor=_mondayOnOrBefore(monthStart);cursor<=monthEnd;cursor=weekDateFromStart(cursor,7)){
    weekStarts.push(cursor);
  }
  return {monthStart,monthEnd,weekStarts};
}

function renderMonthlyRotaBoard(){
  const board=document.getElementById('rota-monthly-board');
  if(!board)return;
  if(_skipHiddenRotaBoard(board,renderMonthlyRotaBoard))return;
  const month=document.getElementById('rota-month-value')?.value||weekStartValue().slice(0,7);
  const staffRows=filteredRotaStaff('month');
  const notice=_rotaTruncationNoticeHtml();
  if(!staffRows.length){
    board.innerHTML=notice+'<div class="empty-card">No staff found for this month.</div>';
    return;
  }
  const range=_monthRotaWeekStarts(month);
  if(!range){board.innerHTML=notice+'<div class="empty-card">Select a month.</div>';return;}
  const {weekStarts}=range;
  const blocks=weekStarts.map(weekStart=>{
    const dates=ROTA_WEEK_DAYS.map((_,i)=>weekDateFromStart(weekStart,i));
    const weekNo=_isoWeekNumber(dates[3]); // Thursday-anchored per ISO 8601
    const headCells=ROTA_MONTH_DAY_NAMES.map((name,i)=>
      `<th>${name}<div class="rota-month-hd-date">${escapeHtml(dates[i].slice(8,10))}/${escapeHtml(dates[i].slice(5,7))}</div></th>`
    ).join('');
    const rows=staffRows.map(staff=>{
      // Clickable now, same as Weekly Rota's own cells (openRotaCellEditor
      // reads these exact dataset attributes off whatever element it's
      // given) -- previously a plain <td>, so the colored task-count dots
      // rotaCellHtml() already draws here were visible only as a bare
      // hover tooltip, with no way to open the day and see task names,
      // times, or edit anything from the Monthly view at all.
      const cells=ROTA_WEEK_DAYS.map((day,i)=>{
        const assignment=assignmentFor(staff,dates[i],day);
        return `<td><button class="rota-day-cell rota-month-day-cell" type="button" onclick="openRotaCellEditor(this)" data-assignment="${escapeHtml(JSON.stringify(assignment))}" data-employee-id="${escapeHtml(staff.id)}" data-employee-name="${escapeHtml(staff.name)}" data-role="${escapeHtml(staff.role)}" data-department="${escapeHtml(staff.department)}" data-location="${escapeHtml(staff.location)}" data-date="${escapeHtml(dates[i])}" data-day="${escapeHtml(day)}">${rotaCellHtml(assignment)}</button></td>`;
      }).join('');
      return `<tr><td class="rota-month-staff-cell"><strong>${escapeHtml(staff.name)}</strong><span>${escapeHtml(staff.department)} · ${escapeHtml(staff.role)}</span></td>${cells}</tr>`;
    }).join('');
    return `<div class="rota-month-week-block">
      <div class="rota-month-week-hd">Week ${weekNo} · ${dates[0].slice(8,10)}/${dates[0].slice(5,7)} – ${dates[6].slice(8,10)}/${dates[6].slice(5,7)}</div>
      <div style="overflow-x:auto"><table class="rota-month-table"><thead><tr><th style="text-align:left">Staff</th>${headCells}</tr></thead><tbody>${rows}</tbody></table></div>
    </div>`;
  }).join('');
  board.innerHTML=notice+blocks;
}

function renderDepartmentRota(){
  const coverage=document.getElementById('rota-dept-coverage');
  const staffBody=document.getElementById('rota-dept-staff-tbody');
  const department=document.getElementById('rota-dept-department')?.value||'All Departments';
  setText('rota-dept-sub',department);
  const assignments=selectedWeekAssignments('dept');
  const counts={M:0,E:0,N:0,OT:0};
  assignments.forEach(item=>{if(counts[item.code]!==undefined)counts[item.code]+=1;});
  // Shared with the "Coverage Ready" check below — previously that check
  // only tested `Object.values(counts).every(Boolean)` (every shift type
  // has AT LEAST ONE person, i.e. count !== 0), completely ignoring the
  // per-type `required` numbers rendered right here, so a single person
  // covering the whole week already read "Coverage Ready" even with
  // Morning needing 5 and Night needing 2.
  const REQUIRED={M:5,E:3,N:2,OT:1};
  if(coverage){
    coverage.innerHTML=[['Morning','M'],['Evening','E'],['Night','N'],['Overtime','OT']].map(([label,code])=>{
      const required=REQUIRED[code];
      const assigned=counts[code]||0;
      const pct=Math.min(100,Math.round((assigned/required)*100));
      const cls=assigned>=required?'b-g':assigned?'b-a':'b-r';
      return `<div class="rota-coverage-card"><strong>${label}</strong><span>${assigned}/${required}</span><div class="prog-bar"><div class="prog-fill" style="width:${pct}%;background:${assigned>=required?'var(--green)':assigned?'var(--amber)':'var(--red)'}"></div></div>${rotaBadge(assigned>=required?'Covered':assigned?'Shortage':'Missing')}</div>`;
    }).join('');
  }
  if(staffBody){
    const staffRows=filteredRotaStaff('dept');
    staffBody.innerHTML=staffRows.map(staff=>{
      const hours=assignments.filter(item=>item.employee_id===staff.id).reduce((sum,item)=>sum+rotaHours(item),0);
      return `<tr><td>${escapeHtml(staff.name)}</td><td>${escapeHtml(staff.department)}</td><td class="mono">${hours.toFixed(1)}</td><td>${rotaBadge(hours?'Scheduled':'Open')}</td></tr>`;
    }).join('')||'<tr data-empty-state="1"><td colspan="4" style="color:var(--text3);text-align:center">No staff found.</td></tr>';
  }
  const covered=Object.keys(REQUIRED).every(code=>(counts[code]||0)>=REQUIRED[code]);
  const status=document.getElementById('rota-dept-status');
  if(status){
    status.className=`b ${covered?'b-g':'b-a'}`;
    status.textContent=covered?'Coverage Ready':'Needs Coverage Review';
  }
}

function renderRotaCodes(){
  const row=document.getElementById('rota-code-row');
  if(!row)return;
  row.innerHTML=['M Morning','E Evening','N Night','OFF Off','L Leave','OT Overtime'].map(text=>`<span class="chip">${escapeHtml(text)}</span>`).join('');
}

// Rota assignments are not in the bootstrap (it used to carry the newest 500,
// which left older/future weeks looking empty). GET .../rotaAssignments/range
// fills exactly the date window a screen needs. Ranges already fetched are
// remembered for the rest of this page load so switching between Weekly/
// Monthly/Department repeatedly (the normal way of using this page) doesn't
// refetch the same days over and over. employeeId narrows a range to one
// employee (upcoming shifts for a swap request).
const _rotaLoadedRanges=new Set();

async function _ensureRotaRangeLoaded(fromDate,toDate,{employeeId='',render=true}={}){
  if(!fromDate||!toDate||fromDate>toDate)return;
  const key=`${fromDate}..${toDate}|${employeeId}`;
  if(_rotaLoadedRanges.has(key))return;
  _rotaLoadedRanges.add(key);
  try{
    const params=new URLSearchParams({from:fromDate,to:toDate});
    if(employeeId)params.set('employee_id',employeeId);
    const r=await authenticatedFetch(`${apiBaseUrl()}/app-data/records/rotaAssignments/range?${params}`);
    if(!r.ok){_rotaLoadedRanges.delete(key);return;}
    const data=await r.json();
    const rows=Array.isArray(data.records)?data.records:[];
    if(!rows.length)return;
    rows.forEach(rec=>rotaAssignmentsById.set(rec.id,normalizeRotaAssignment(rec)));
    if(render)renderRotaBoards();
  }catch(e){
    _rotaLoadedRanges.delete(key); // network hiccup -- worth trying again later, not a permanent miss
  }
}

// Specific assignments by id (e.g. the two shifts a swap refers to), whatever week.
async function _ensureRotaAssignmentsLoaded(ids){
  const missing=[...new Set((ids||[]).filter(id=>id&&!rotaAssignmentsById.has(id)))];
  if(!missing.length)return;
  try{
    const r=await authenticatedFetch(`${apiBaseUrl()}/app-data/records/rotaAssignments/by-ids?ids=${encodeURIComponent(missing.join(','))}`);
    if(!r.ok)return;
    const data=await r.json();
    (Array.isArray(data.records)?data.records:[]).forEach(rec=>rotaAssignmentsById.set(rec.id,normalizeRotaAssignment(rec)));
  }catch(e){
    console.warn('Rota assignments could not load:',e);
  }
}

// Fetches whatever date window Weekly/Department/Monthly Rota currently have on screen
// (fire-and-forget: the boards below render immediately from whatever's already cached,
// then re-render themselves once/if the fetch above fills in anything new).
function _loadVisibleRotaRanges(){
  const weekStart=document.getElementById('rota-week-start')?.value;
  if(weekStart)_ensureRotaRangeLoaded(weekStart,weekDateFromStart(weekStart,6));
  const deptWeekStart=document.getElementById('rota-dept-week-start')?.value;
  if(deptWeekStart&&deptWeekStart!==weekStart)_ensureRotaRangeLoaded(deptWeekStart,weekDateFromStart(deptWeekStart,6));
  const month=document.getElementById('rota-month-value')?.value;
  const range=month?_monthRotaWeekStarts(month):null;
  if(range)_ensureRotaRangeLoaded(range.weekStarts[0],weekDateFromStart(range.weekStarts[range.weekStarts.length-1],6));
}

function renderRotaBoards(){
  renderWeeklyRotaBoard();
  renderRotaEmployeeTasksPanel();
  renderMonthlyRotaBoard();
  renderDepartmentRota();
  renderRotaSummary();
  renderRotaCodes();
  updateRotaStats();
  updateRotaStatusBadges();
  populateRotaRepeatEmployeeSelect();
  _loadVisibleRotaRanges();
}

const DEFAULT_ROTA_SHIFTS=[];

function seedDefaultRotaShifts(){
  const tbody=document.getElementById('rota-shift-tbody');
  if(!tbody)return;
  const hasRows=[...tbody.querySelectorAll('tr:not([data-empty-state])')].length>0;
  if(hasRows)return;
  DEFAULT_ROTA_SHIFTS.forEach(shift=>renderRotaShiftRecord(shift,{prepend:false}));
  updateRotaStats();
}

// ── Shift departments ───────────────────────────────────────────────────
// A shift can belong to one or several departments (record.departments).
// Empty = every department (all shifts created before this existed).
function shiftDepartmentList(shift){
  let raw=shift?.departments;
  if(raw==null||raw==='')raw=shift?.department;
  if(typeof raw==='string')raw=raw.split(',');
  if(!Array.isArray(raw))return [];
  return raw.map(d=>String(d).trim()).filter(d=>d&&!/^all( departments)?$/i.test(d));
}
function shiftAppliesToDepartment(shift,department){
  const depts=shiftDepartmentList(shift).map(d=>d.toLowerCase());
  if(!depts.length)return true;
  return depts.includes(String(department||'').trim().toLowerCase());
}
function renderShiftDeptGrid(selected){
  const grid=document.getElementById('shift-dept-grid');
  if(!grid)return;
  const chosen=new Set((selected||[]).map(d=>String(d).trim().toLowerCase()));
  const names=[..._getDeptNames()];
  // Companies that never filled in HR Settings > Departments still have departments on their employees.
  if(!(Array.isArray(window.HRMS_DEPT_SCOPE)&&window.HRMS_DEPT_SCOPE.length)&&typeof _getAttendanceEmployees==='function'){
    _getAttendanceEmployees().forEach(e=>{const d=String(e.department||'').trim();if(d&&!names.some(n=>n.toLowerCase()===d.toLowerCase()))names.push(d);});
  }
  // keep a shift's existing department visible even if it's no longer in the department list
  (selected||[]).forEach(d=>{if(d&&!names.some(n=>n.toLowerCase()===String(d).toLowerCase()))names.push(String(d));});
  grid.innerHTML=names.length
    ?names.map(d=>`<label style="display:flex;align-items:center;gap:8px;font-size:13px;cursor:pointer"><input type="checkbox" class="shift-dept-cb" value="${escapeHtml(d)}" ${chosen.has(d.toLowerCase())?'checked':''}> ${escapeHtml(d)}</label>`).join('')
    :'<div style="color:var(--text3);font-size:12px">No departments yet — add them in HR Settings to limit a shift to departments.</div>';
}
function selectedShiftDepartments(){
  return [...document.querySelectorAll('#m-shift .shift-dept-cb:checked')].map(cb=>cb.value);
}
// "+ Add Shift": reset to add-mode and pre-tick a department-limited login's own departments.
// Code of the shift being edited; null while adding. The code is the shift's id and
// rota assignments refer to it, so it can't be changed while editing.
let _editingShiftCode=null;
function resetShiftForm(){
  _editingShiftCode=null;
  setFieldValue(document.getElementById('shift-name'),'');
  setFieldValue(document.getElementById('shift-code'),'');
  setFieldValue(document.getElementById('shift-start'),'09:00');
  setFieldValue(document.getElementById('shift-end'),'18:00');
  setFieldValue(document.getElementById('shift-break'),'60');
  setFieldValue(document.getElementById('shift-grace'),'10 minutes');
  setFieldValue(document.getElementById('shift-ot-after'),'8 hours');
  setSelectValue(document.getElementById('shift-status'),'Active');
  const codeEl=document.getElementById('shift-code');
  if(codeEl){codeEl.readOnly=false;codeEl.title='';}
  const titleEl=document.querySelector('#m-shift .modal-title');
  const btnEl=document.querySelector('#m-shift .btn-p');
  if(titleEl)titleEl.textContent='Add Shift';
  if(btnEl)btnEl.textContent='Save Shift';
}
function openShiftModal(){
  if(!hrmsCan('rota:edit')){toast('Your role can view shifts but not add them','warn');return;}
  resetShiftForm();
  const scope=window.HRMS_DEPT_SCOPE;
  renderShiftDeptGrid(Array.isArray(scope)&&scope.length?scope:[]);
  showM('m-shift');
}

function renderRotaShiftRecord(shift){
  const options=arguments[1]||{};
  const tbody=document.getElementById('rota-shift-tbody');
  const code=String(shift?.code||shift?.shift_code||'').trim();
  if(!tbody||!code)return;
  // Previously skipped rendering entirely on a code match ("if duplicate
  // return") — harmless for the initial load, but meant editShift() saving
  // an edited shift (same code, changed fields) silently failed to update
  // the visible row at all. Replacing the existing row in place instead
  // makes both re-seeding and editing work the same way.
  const existing=[...tbody.querySelectorAll('tr:not([data-empty-state])')]
    .find(row=>(row.children[1]?.textContent||'').trim().toLowerCase()===code.toLowerCase());
  if(existing)existing.remove();
  const start=shift.start||shift.start_time||'';
  const end=shift.end||shift.end_time||'';
  const breakMinutes=shift.break_minutes??shift.break??0;
  const row=document.createElement('tr');
  row.dataset.serverRecord='rotaShifts';
  row.dataset.shift=JSON.stringify(shift);
  row.innerHTML=`<td>${escapeHtml(shift.name||shift.shift_name||code)}</td><td class="mono">${escapeHtml(code)}</td><td class="mono">${escapeHtml(start||'-')}</td><td class="mono">${escapeHtml(end||'-')}</td><td>${escapeHtml(String(breakMinutes||0))}m</td><td>${escapeHtml(shift.hours||shiftHours(start,end,breakMinutes))}</td><td>${escapeHtml(shift.grace||shift.grace_period||'-')}</td><td>${escapeHtml(shift.ot_after||shift.overtime_after||'-')}</td><td>${escapeHtml(shiftDepartmentList(shift).join(', ')||'All departments')}</td><td>${rotaBadge(shift.status||'Active')}</td><td><div class="flx"><button class="btn btn-g btn-sm" onclick="editShift(this)">Edit</button><button class="btn btn-danger btn-sm" onclick="deleteShift(this)">Delete</button></div></td>`;
  removeEmptyState(tbody);
  if(existing||options.prepend===false)tbody.appendChild(row);
  else tbody.prepend(row);
  // Same isHydratingFromServer guard as renderEmployeeRecord()/
  // renderRotaAssignmentRecord() above -- lower-impact here since Shift
  // Setup tables are typically small, but this runs once per shift during
  // bootstrap hydration too, and the hydration loop already refreshes stats
  // once after it finishes (see the renderRecordList(...,'rota shift') call site).
  if(!isHydratingFromServer)updateRotaStats();
}

// "View" was a dead button (toast only) — Shift Setup previously had no
// way at all to fix a typo or change a saved shift's timing/break/grace
// without deleting and re-adding it.
function editShift(btn){
  if(!hrmsCan('rota:edit')){toast('Your role can view shifts but not change them','warn');return;}
  const row=btn.closest('tr');
  let shift={};try{shift=JSON.parse(row.dataset.shift||'{}');}catch{}
  if(!shift.code)return;
  setFieldValue(document.getElementById('shift-name'),shift.name||shift.shift_name||'');
  setFieldValue(document.getElementById('shift-code'),shift.code);
  setFieldValue(document.getElementById('shift-start'),shift.start||shift.start_time||'09:00');
  setFieldValue(document.getElementById('shift-end'),shift.end||shift.end_time||'18:00');
  setFieldValue(document.getElementById('shift-break'),String(shift.break_minutes??shift.break??60));
  setFieldValue(document.getElementById('shift-grace'),shift.grace||shift.grace_period||'');
  setFieldValue(document.getElementById('shift-ot-after'),shift.ot_after||shift.overtime_after||'');
  setSelectValue(document.getElementById('shift-status'),shift.status||'Active');
  renderShiftDeptGrid(shiftDepartmentList(shift));
  _editingShiftCode=String(shift.code).toUpperCase();
  const codeEl=document.getElementById('shift-code');
  if(codeEl){codeEl.readOnly=true;codeEl.title='The code can’t be changed — rota assignments use it';}
  const titleEl=document.querySelector('#m-shift .modal-title');
  const btnEl=document.querySelector('#m-shift .btn-p');
  if(titleEl)titleEl.textContent='Edit Shift';
  if(btnEl)btnEl.textContent='Save Changes';
  showM('m-shift');
}

async function deleteShift(btn){
  if(!hrmsCan('rota:delete')){toast('Your role can’t delete shifts','warn');return;}
  const row=btn.closest('tr');
  let shift={};try{shift=JSON.parse(row.dataset.shift||'{}');}catch{}
  if(!(await appConfirm({title:'Delete Shift',message:`Delete shift "${shift.name||shift.code||'this shift'}"?`,okText:'Delete'})))return;
  if(shift.code){
    try{await deleteServer('rotaShifts',shift,{throwOnError:true});}
    catch(err){toast(`Could not delete this shift${err?.serverDetail?': '+err.serverDetail:''}`,'err');return;}
  }
  row.remove();
  updateRotaStats();
  toast('Shift deleted','warn');
  audit('Deleted rota shift',shift.code||'','Deleted');
}

function buildShiftRecordFromForm(){
  const name=(document.getElementById('shift-name')?.value||'').trim();
  const code=(document.getElementById('shift-code')?.value||'').trim().toUpperCase();
  const start=document.getElementById('shift-start')?.value||'';
  const end=document.getElementById('shift-end')?.value||'';
  const breakMinutes=parseAmount(document.getElementById('shift-break')?.value);
  return {
    id:code||`SHIFT-${Date.now()}`,
    name,
    code,
    start,
    end,
    break_minutes:breakMinutes,
    hours:shiftHours(start,end,breakMinutes),
    grace:document.getElementById('shift-grace')?.value||'',
    ot_after:document.getElementById('shift-ot-after')?.value||'',
    departments:selectedShiftDepartments(),
    status:document.getElementById('shift-status')?.value||'Active'
  };
}

async function saveShift(){
  const record=buildShiftRecordFromForm();
  if(!record.name||!record.code){
    toast('Shift name and code are required','warn');
    return;
  }
  if(!record.start||!record.end){
    toast('Enter the shift start and end times','warn');
    return;
  }
  const [sh,sm]=record.start.split(':').map(Number),[eh,em]=record.end.split(':').map(Number);
  let spanMinutes=(eh*60+em)-(sh*60+sm);
  if(spanMinutes<=0)spanMinutes+=24*60;  // overnight shift
  if(!(record.break_minutes>=0)||record.break_minutes>=spanMinutes){
    toast('Break minutes must be 0 or more and shorter than the shift','warn');
    return;
  }
  if(Array.isArray(window.HRMS_DEPT_SCOPE)&&window.HRMS_DEPT_SCOPE.length&&!record.departments.length){
    toast('Pick at least one of your departments for this shift','warn');
    return;
  }
  // Adding with a code that's already used would silently replace that shift.
  if(!_editingShiftCode){
    const clash=[...document.querySelectorAll('#rota-shift-tbody tr:not([data-empty-state])')]
      .find(row=>(row.children[1]?.textContent||'').trim().toUpperCase()===record.code);
    if(clash){
      toast(`Shift code ${record.code} is already used by “${clash.children[0]?.textContent.trim()}” — pick another code, or use Edit`,'warn');
      document.getElementById('shift-code')?.focus();
      return;
    }
  }
  try{
    await saveServer('rotaShifts',record,{throwOnError:true});
  }catch(err){
    console.warn('Rota shift save failed:',err);
    toast(err?.serverDetail?`Could not save this shift: ${err.serverDetail}`:'Could not save this shift — check your connection and try again','err');
    return;
  }
  renderRotaShiftRecord(record);
  closeM('m-shift');
  resetShiftForm();
  toast('Shift saved to database','ok');
  audit('Saved rota shift',record.code,'Saved');
}

function renderRotaSwapRecord(swap){
  const tbody=document.getElementById('rota-swap-tbody');
  const id=String(swap?.id||'').trim();
  if(!tbody||!id)return;
  const duplicate=[...tbody.querySelectorAll('tr:not([data-empty-state])')]
    .some(row=>{
      try{return JSON.parse(row.dataset.swap||'{}').id===id;}catch{return false;}
    });
  if(duplicate)return;
  const row=document.createElement('tr');
  row.dataset.serverRecord='rotaSwaps';
  row.dataset.swap=JSON.stringify(swap);
  const [aLabel,bLabel]=_rotaSwapShiftLabels(swap);
  row.innerHTML=`<td>${escapeHtml(swap.employee_a||swap.requester||'-')}</td><td>${escapeHtml(aLabel)}</td><td>${escapeHtml(swap.employee_b||'-')}</td><td>${escapeHtml(bLabel)}</td><td>${rotaBadge(swap.status||'Peer Pending')}</td><td><div class="flx"><button class="btn btn-success btn-sm" onclick="approveRotaRow(this,'Swap approved')">Approve</button><button class="btn btn-danger btn-sm" onclick="rejectRotaRow(this,'Swap rejected')">Reject</button></div></td>`;
  removeEmptyState(tbody);
  tbody.prepend(row);
  updateRotaStats();
  _queueRotaSwapShiftLookup([swap.assignment_a_id,swap.assignment_b_id]);
}

function _rotaSwapShiftLabels(swap){
  const shiftLabel=assignmentId=>{
    const a=assignmentId?rotaAssignmentsById.get(assignmentId):null;
    return a?`${a.date} — ${a.type||a.code||'Shift'}`:(assignmentId?'(shift not found)':'-');
  };
  return [
    swap.assignment_a_id?shiftLabel(swap.assignment_a_id):(swap.my_shift||'-'),
    swap.assignment_b_id?shiftLabel(swap.assignment_b_id):(swap.swap_with||'-')
  ];
}

// Swap rows can refer to shifts in weeks not loaded yet: fetch those (batched)
// and relabel the rows once they arrive.
const _rotaSwapLookupIds=new Set();
let _rotaSwapLookupTimer=null;
function _queueRotaSwapShiftLookup(ids){
  ids.filter(id=>id&&!rotaAssignmentsById.has(id)).forEach(id=>_rotaSwapLookupIds.add(id));
  if(!_rotaSwapLookupIds.size)return;
  clearTimeout(_rotaSwapLookupTimer);
  _rotaSwapLookupTimer=setTimeout(async()=>{
    const ids=[..._rotaSwapLookupIds];
    _rotaSwapLookupIds.clear();
    await _ensureRotaAssignmentsLoaded(ids);
    document.querySelectorAll('#rota-swap-tbody tr[data-swap]').forEach(row=>{
      let swap={};
      try{swap=JSON.parse(row.dataset.swap||'{}');}catch{return;}
      const [aLabel,bLabel]=_rotaSwapShiftLabels(swap);
      if(row.children[1])row.children[1].textContent=aLabel;
      if(row.children[3])row.children[3].textContent=bLabel;
    });
  },200);
}

// Populates a swap request's per-employee assignment select with that
// employee's upcoming (today or later) rotaAssignments entries, once an
// employee has been chosen — the swap can only ever reference real,
// existing assignments now (previously "My Shift"/"Swap With"/"Target
// Shift" were three free-text inputs with no employee_id/date/shift
// reference a backend could act on at all).
async function _populateSwapAssignmentSelect(employeeSelectId,assignmentSelectId){
  const empSel=document.getElementById(employeeSelectId);
  const assignSel=document.getElementById(assignmentSelectId);
  if(!empSel||!assignSel)return;
  const empId=empSel.selectedOptions?.[0]?.dataset.empId||'';
  assignSel.innerHTML='<option value="">— Select Shift —</option>';
  if(!empId)return;
  const today=new Date().toISOString().slice(0,10);
  // Upcoming = the next year of this employee's shifts, loaded on demand.
  assignSel.innerHTML='<option value="">Loading shifts…</option>';
  await _ensureRotaRangeLoaded(today,weekDateFromStart(today,365),{employeeId:empId,render:false});
  if((empSel.selectedOptions?.[0]?.dataset.empId||'')!==empId)return; // selection changed meanwhile
  assignSel.innerHTML='<option value="">— Select Shift —</option>';
  const upcoming=[...rotaAssignmentsById.values()]
    .filter(a=>a.employee_id===empId&&a.date>=today)
    .sort((a,b)=>a.date.localeCompare(b.date));
  upcoming.forEach(a=>{
    const opt=document.createElement('option');
    opt.value=a.id;
    opt.textContent=`${a.date} — ${a.type||a.code||'Shift'}`;
    assignSel.appendChild(opt);
  });
  if(!upcoming.length)assignSel.innerHTML='<option value="">No upcoming shifts for this employee</option>';
}

function saveRotaSwap(){
  const empASel=document.getElementById('swap-employee-a');
  const empBSel=document.getElementById('swap-employee-b');
  const record={
    id:'SWAP-'+Date.now(),
    employee_a:empASel?.value||'',
    employee_a_id:empASel?.selectedOptions?.[0]?.dataset.empId||'',
    assignment_a_id:document.getElementById('swap-assignment-a')?.value||'',
    employee_b:empBSel?.value||'',
    employee_b_id:empBSel?.selectedOptions?.[0]?.dataset.empId||'',
    assignment_b_id:document.getElementById('swap-assignment-b')?.value||'',
    reason:(document.getElementById('swap-reason')?.value||'').trim(),
    status:'Peer Pending'
  };
  if(!record.assignment_a_id||!record.assignment_b_id){
    toast('Select both employees and their shifts to swap','warn');
    return;
  }
  if(record.employee_a_id&&record.employee_a_id===record.employee_b_id){
    toast('Choose two different employees','warn');
    return;
  }
  renderRotaSwapRecord(record);
  saveServer('rotaSwaps',record);
  closeM('m-shift-swap');
  ['swap-employee-a','swap-employee-b'].forEach(id=>setFieldValue(document.getElementById(id),''));
  ['swap-assignment-a','swap-assignment-b'].forEach(id=>{const el=document.getElementById(id);if(el)el.innerHTML='<option value="">— Select employee first —</option>';});
  setFieldValue(document.getElementById('swap-reason'),'');
  toast('Shift swap request saved to database','ok');
  audit('Submitted shift swap',record.id,'Pending');
}

// approval.period only ever stores the week's Monday start date
// (weekStartValue(), a bare "YYYY-MM-DD") -- the Rota Approval table's own
// column header calls it "Period", and the placeholder demo row it
// replaced showed a real range ("03-09 May"), but every actual approval
// record rendered just that one ISO date with no end date or day-name
// context, telling an approver nothing about which week they're
// actually being asked to approve. Weeks run Mon-Sun (see
// _currentRotaWeekStart()'s comment) -- the end date is always start+6.
function _formatRotaPeriodRange(periodStr){
  const start=new Date(`${periodStr}T00:00:00`);
  if(isNaN(start.getTime()))return periodStr||'-';
  const end=new Date(start);
  end.setDate(end.getDate()+6);
  const dayFmt=d=>String(d.getDate()).padStart(2,'0');
  const sameMonth=start.getMonth()===end.getMonth()&&start.getFullYear()===end.getFullYear();
  const monthYear=d=>d.toLocaleDateString('en-GB',{month:'short',year:'numeric'});
  return sameMonth
    ?`${dayFmt(start)}–${dayFmt(end)} ${monthYear(end)}`
    :`${dayFmt(start)} ${start.toLocaleDateString('en-GB',{month:'short'})} – ${dayFmt(end)} ${monthYear(end)}`;
}

function renderRotaApprovalRecord(approval){
  const tbody=document.getElementById('rota-approval-tbody');
  const id=String(approval?.id||'').trim();
  if(!tbody||!id)return;
  const duplicate=[...tbody.querySelectorAll('tr:not([data-empty-state])')]
    .some(row=>{
      try{return JSON.parse(row.dataset.approval||'{}').id===id;}catch{return false;}
    });
  if(duplicate)return;
  const row=document.createElement('tr');
  row.dataset.serverRecord='rotaApprovals';
  row.dataset.approval=JSON.stringify(approval);
  const status=approval.status||'Pending Supervisor Review';
  const periodLabel=approval.period?_formatRotaPeriodRange(approval.period):'-';
  row.innerHTML=`<td>${escapeHtml(approval.department||'All')}</td><td>${escapeHtml(periodLabel)}</td><td>${escapeHtml(approval.supervisor||'-')}</td><td>${rotaBadge(status)}</td><td><div class="flx"><button class="btn btn-success btn-sm" onclick="approveRotaRow(this,'Rota approved')">Approve</button><button class="btn btn-danger btn-sm" onclick="rejectRotaRow(this,'Rota rejected')">Reject</button></div></td>`;
  removeEmptyState(tbody);
  tbody.prepend(row);
  updateRotaStats();
}

// Text-only color class for the Draft/Pending/Published pill -- previously
// only the text ever changed (setText()); the span's class stayed whatever
// the static HTML shipped with ("b b-gray"), so a Published rota's badge
// still rendered in muted gray forever, never turning green.
function _rotaStatusBadgeClass(statusText){
  if(statusText==='Published')return'b-g';
  if(statusText==='Pending Supervisor Review')return'b-a';
  return'b-gray';
}
function _setRotaStatusBadge(elId,statusText){
  const el=document.getElementById(elId);
  if(!el)return;
  el.textContent=statusText;
  el.className=`b ${_rotaStatusBadgeClass(statusText)}`;
}

function saveRotaDraft(status='Draft'){
  _setRotaStatusBadge('rota-weekly-status',status);
  _setRotaStatusBadge('rota-monthly-status',status);
  const record={
    id:'ROTA-'+Date.now(),
    department:document.getElementById('rota-week-department')?.value||'All Departments',
    period:weekStartValue(),
    supervisor:document.getElementById('rota-dept-supervisor')?.value||'HR',
    status,
    assignment_count:selectedWeekAssignments('week').length
  };
  saveServer('rotaDrafts',record);
  // This used to hardcode every non-Draft status to "Pending Supervisor
  // Review" here, so publishRota()'s call (status="Published") created an
  // approval-history row that said "Pending Supervisor Review" for a rota
  // that had just been published -- record already carries the real status.
  const approval={...record,id:'APP-'+Date.now()};
  renderRotaApprovalRecord(approval);
  saveServer('rotaApprovals',approval);
  toast(`${status} rota saved to database`,'ok');
  audit('Saved rota draft','Rota Planning',status);
}

// The Draft/Pending/Published pill above the Staff Schedule/Monthly Schedule
// boards used to be pure in-session state -- only ever set by clicking Save
// Draft/Submit Approval/Publish Rota in THIS tab, with no way to recover it
// on reload. publishRota() really does persist status:'Published' onto every
// assignment it publishes, so a reload silently showing "Draft" again looked
// exactly like the publish had been lost, when the real data was fine.
// Re-derive the badge from what's actually saved on every render instead.
function _deriveRotaStatusForAssignments(assignments){
  if(assignments.some(a=>a.status==='Published'))return'Published';
  if(assignments.some(a=>a.status==='Pending Supervisor Review'))return'Pending Supervisor Review';
  return'Draft';
}
function updateRotaStatusBadges(){
  _setRotaStatusBadge('rota-weekly-status',_deriveRotaStatusForAssignments(selectedWeekAssignments('week')));
  const monthValue=document.getElementById('rota-month-value')?.value||'';
  const monthAssignments=monthValue?[...rotaAssignmentsById.values()].filter(a=>(a.date||'').startsWith(monthValue)):[];
  _setRotaStatusBadge('rota-monthly-status',_deriveRotaStatusForAssignments(monthAssignments));
}

function updateRotaStats(){
  const stats=[...document.querySelectorAll('#rota-shifts .stat-val')];
  const shifts=document.querySelectorAll('#rota-shift-tbody tr:not([data-empty-state])').length;
  const swaps=[...document.querySelectorAll('#rota-swap-tbody tr:not([data-empty-state])')];
  const approvals=[...document.querySelectorAll('#rota-approval-tbody tr:not([data-empty-state])')];
  const conflicts=document.querySelectorAll('#page-rota .rota-cell.conflict,#rota-approval-tbody .b-r,#rota-swap-tbody .b-r').length;
  const pending=swaps.filter(row=>/pending|review/i.test(row.textContent)).length+approvals.filter(row=>/pending|review/i.test(row.textContent)).length;
  if(stats[0])stats[0].textContent=String(shifts);
  // From employee records, not a table column (column 3 became "Nick Name", so this always read 1).
  const emps=typeof _getAttendanceEmployees==='function'?_getAttendanceEmployees():[];
  if(stats[1])stats[1].textContent=String(new Set(emps.map(e=>String(e.department||'').trim().toLowerCase()).filter(Boolean)).size);
  if(stats[2])stats[2].textContent=String(conflicts);
  if(stats[3])stats[3].textContent=String(pending);
}

function publishRota(){
  // Used to loop over EVERY assignment ever loaded into rotaAssignmentsById
  // (up to 500 rows from bootstrap, easily spanning many weeks/months and
  // every department -- see the rotaAssignments cap comment in
  // app_data.py), regardless of which week was on screen. Publishing this
  // week silently flipped next month's still-Draft rows (e.g. from Copy
  // Previous or the 1-year Repeat feature) to Published too. Scope it to
  // the week actually being viewed (respecting the current Department/
  // Location/Search filters), like every other Weekly Rota action already does.
  const weekAssignments=selectedWeekAssignments('week');
  weekAssignments.forEach(item=>{
    item.status='Published';
    saveServer('rotaAssignments',item);
  });
  saveRotaDraft('Published');
  renderRotaBoards();
  toast(`Rota published for ${weekAssignments.length} shift(s) this week`,'ok');
  audit('Rota published','Rota Planning','Published');
}

function populateRotaRepeatEmployeeSelect(){
  const sel=document.getElementById('rota-repeat-employee');
  if(!sel)return;
  const current=sel.value;
  sel.innerHTML='<option value="all">All Employees</option>';
  currentRotaStaff().forEach(s=>{
    const opt=document.createElement('option');
    opt.value=s.id;
    opt.textContent=s.name;
    sel.appendChild(opt);
  });
  if(current&&[...sel.options].some(o=>o.value===current))sel.value=current;
}

async function applyRotaRepeat(){
  const mode=document.getElementById('rota-repeat-mode')?.value||'none';
  if(mode==='none'){toast('Select a repeat duration first','warn');return;}
  const empFilter=document.getElementById('rota-repeat-employee')?.value||'all';
  const start=weekStartValue();
  await _ensureRotaRangeLoaded(start,weekDateFromStart(start,6),{render:false});
  const weeks=mode==='1year'?52:260;
  let sourceAssignments=[...rotaAssignmentsById.values()].filter(a=>{
    const diff=Math.round((new Date(`${a.date}T00:00:00`)-new Date(`${start}T00:00:00`))/86400000);
    return diff>=0&&diff<7;
  });
  if(empFilter!=='all') sourceAssignments=sourceAssignments.filter(a=>a.employee_id===empFilter);
  if(!sourceAssignments.length){
    toast(empFilter==='all'?'No assignments in the current week to repeat':'No assignments for this employee in the current week','warn');
    return;
  }
  let count=0;
  for(let w=1;w<=weeks;w++){
    sourceAssignments.forEach(src=>{
      const dayOffset=Math.round((new Date(`${src.date}T00:00:00`)-new Date(`${start}T00:00:00`))/86400000);
      const newDate=weekDateFromStart(start,w*7+dayOffset);
      const assignment=normalizeRotaAssignment({
        ...src,
        id:rotaAssignmentId(src.employee_id,newDate),
        date:newDate,
        day:ROTA_WEEK_DAYS[dayOffset%7],
        status:'Draft',
        updated_at:new Date().toISOString()
      });
      rotaAssignmentsById.set(assignment.id,assignment);
      saveServer('rotaAssignments',assignment);
      count++;
    });
  }
  const empName=empFilter==='all'?'all employees':([...document.getElementById('rota-repeat-employee')?.options||[]].find(o=>o.value===empFilter)?.textContent||empFilter);
  const label=mode==='1year'?'1 year (52 weeks)':'indefinitely (~5 years / 260 weeks)';
  const info=document.getElementById('rota-repeat-info');
  if(info)info.textContent=`✓ ${count} assignments created for ${empName} from ${start}`;
  toast(`Rota repeated ${label} for ${empName}: ${count} assignments saved`,'ok');
  audit(`Rota repeat applied (${mode}) for ${empName}`,'Rota Planning','Draft');
}

// ── Rota export helpers ───────────────────────────────────────────────────────

function _renderHolidayRow(rec){
  const tbody=document.getElementById('holidays-tbody');
  if(!tbody)return;
  const existing=tbody.querySelector(`tr[data-holiday-id="${CSS.escape(rec.id)}"]`);
  const statusBadge=rec.status==='Planned'?'<span class="b b-a">Planned</span>':'<span class="b b-g">Active</span>';
  const paidBadge=rec.paid===false||rec.paid==='No'?'<span class="b" style="background:var(--bg3)">No</span>':'<span class="b b-g">Yes</span>';
  const html=`<td>${escapeHtml(rec.display_date||rec.date||'')}</td><td>${escapeHtml(rec.name||'')}</td><td>${escapeHtml(rec.location||'All branches')}</td><td>${paidBadge}</td><td>${statusBadge}</td><td><button class="btn btn-g btn-xs" onclick="deleteHoliday('${escapeHtml(rec.id)}')">×</button></td>`;
  if(existing){existing.innerHTML=html;}
  else{
    removeEmptyState(tbody);
    const tr=document.createElement('tr');
    tr.dataset.holidayId=rec.id;
    tr.innerHTML=html;
    tbody.appendChild(tr);
  }
  if(!tbody.children.length)emptyTableMessage(tbody,'No holidays added yet.');
}

// Was a chain of 4 native browser dialogs (3 prompt()s + 1 confirm()) in
// a row -- unstyled OS popups that break out of the app's own look
// entirely (ignore dark mode, block the main thread, no way to go back a
// step without cancelling the whole thing). Now a single in-app modal,
// the same pattern every other "+ Add X" button in this app already uses.
function addHoliday(){
  const dateEl=document.getElementById('holiday-date');
  const nameEl=document.getElementById('holiday-name');
  const locEl=document.getElementById('holiday-location');
  const paidEl=document.getElementById('holiday-paid');
  if(dateEl)dateEl.value=new Date().toISOString().slice(0,10);
  if(nameEl)nameEl.value='';
  if(locEl)locEl.value='All branches';
  if(paidEl)paidEl.value='yes';
  showM('m-add-holiday');
  setTimeout(()=>nameEl?.focus(),120);
}

function confirmAddHoliday(){
  const isoDate=document.getElementById('holiday-date')?.value||'';
  const name=(document.getElementById('holiday-name')?.value||'').trim();
  const location=(document.getElementById('holiday-location')?.value||'').trim()||'All branches';
  const paid=document.getElementById('holiday-paid')?.value==='yes';
  const parsed=new Date(isoDate+'T00:00:00');
  if(!isoDate||isNaN(parsed.getTime())){toast('Enter a valid date','warn');return;}
  if(!name){toast('Holiday name is required','warn');return;}
  const months=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const display=`${String(parsed.getDate()).padStart(2,'0')} ${months[parsed.getMonth()]}`;
  const rec={id:'holiday-'+Date.now(),date:isoDate,display_date:display,name,location,paid,status:'Active'};
  _renderHolidayRow(rec);
  saveServer('hrHolidays',rec);
  hideM('m-add-holiday');
  toast('Holiday added','ok');
}

function deleteHoliday(id){
  const tbody=document.getElementById('holidays-tbody');
  const row=tbody?.querySelector(`tr[data-holiday-id="${CSS.escape(id)}"]`);
  if(row)row.remove();
  if(tbody&&!tbody.children.length)emptyTableMessage(tbody,'No holidays added yet.');
  deleteServer('hrHolidays',{id});
}

async function loadHolidaysFromServer(){
  try{
    const response=await authenticatedFetch(`${apiBaseUrl()}/app-data/records/hrHolidays?limit=200`);
    if(!response.ok)return;
    const data=await response.json();
    const records=Array.isArray(data.records)?data.records:[];
    // clearStaticDemoData() already put the real "No holidays configured
    // yet" empty-state message in the table on page load; nothing to do
    // here when there's genuinely no company data.
    if(!records.length)return;
    records.forEach(_renderHolidayRow);
  }catch(e){console.warn('Failed to load holidays:',e);}
}

function _companyHolidayMap(){
  const map=new Map();
  const months={Jan:0,Feb:1,Mar:2,Apr:3,May:4,Jun:5,Jul:6,Aug:7,Sep:8,Oct:9,Nov:10,Dec:11};
  document.querySelectorAll('#holidays-tbody tr').forEach(row=>{
    const cells=row.querySelectorAll('td');
    if(cells.length<2)return;
    const m=cells[0].textContent.trim().match(/(\d{1,2})\s+([A-Za-z]{3})/);
    const name=cells[1].textContent.trim();
    if(!m||!name)return;
    const day=parseInt(m[1],10);
    const monIdx=months[m[2]];
    if(monIdx===undefined)return;
    const thisYear=new Date().getFullYear();
    [thisYear-1,thisYear,thisYear+1].forEach(y=>{
      map.set(new Date(y,monIdx,day).toISOString().slice(0,10),name);
    });
  });
  return map;
}

function _rotaExportData(){
  const start=weekStartValue();
  const staff=filteredRotaStaff('week');
  const dates=ROTA_WEEK_DAYS.map((_,i)=>weekDateFromStart(start,i));
  const holidayMap=_companyHolidayMap();
  const dayHolidays=dates.map(d=>holidayMap.get(d)||'');
  const rows=staff.map(s=>{
    const cells=dates.map((date,i)=>{
      const a=rotaAssignmentsById.get(rotaAssignmentId(s.id,date));
      const isHoliday=!!dayHolidays[i]||String(a?.code||'').toUpperCase()==='PH';
      const tasks=Array.isArray(a?.tasks)?a.tasks:[];
      if(!a||!a.code||a.code==='OFF')return{code:isHoliday?'PH':'OFF',time:'-',hours:0,isHoliday,tasks};
      const time=(a.start&&a.end)?`${a.start}-${a.end}`:'-';
      return{code:a.code||'—',time,hours:rotaHours(a),isHoliday,tasks};
    });
    const total=cells.reduce((s,c)=>s+c.hours,0);
    return{name:s.name,department:s.department,role:s.role,cells,total};
  });
  const weekEnd=weekDateFromStart(start,6);
  return{start,weekEnd,dates,dayHolidays,rows};
}

function _shiftColor(code,isHoliday){
  const c=String(code||'').toUpperCase();
  if(isHoliday||c==='PH')return{bg:'#fee2e2',fg:'#b91c1c'};
  if(c==='OFF'||c==='-')return{bg:'#f3f4f6',fg:'#6b7280'};
  if(c==='L')return{bg:'#fef3c7',fg:'#92400e'};
  return{bg:'#dcfce7',fg:'#14532d'};
}

function downloadRotaPdf(){
  const{start,weekEnd,dates,dayHolidays,rows}=_rotaExportData();
  const companyName=document.getElementById('sb-company-name')?.textContent||'TaxFlow HRMS';
  const dayHeaders=ROTA_WEEK_DAYS.map((d,i)=>{
    const holidayName=dayHolidays[i];
    return `<th style="padding:7px 5px;font-size:10px;font-weight:700;background:${holidayName?'#7f1d1d':'#1e293b'};color:#fff;text-align:center;white-space:nowrap">${d}<br><span style="font-weight:400;opacity:.75">${dates[i].slice(5)}</span>${holidayName?`<br><span style="font-weight:700;font-size:8px;color:#fecaca">${escapeHtml(holidayName)}</span>`:''}</th>`;
  }).join('');
  const bodyRows=rows.map((r,ri)=>{
    const bg=ri%2===0?'#ffffff':'#f8fafc';
    const dayCells=r.cells.map(c=>{
      const{bg:cbg,fg:cfg}=_shiftColor(c.code,c.isHoliday);
      const isBlank=c.code==='OFF'&&!c.isHoliday;
      const label=c.isHoliday&&c.code==='OFF'?'PH':c.code;
      const tasksHtml=(c.tasks&&c.tasks.length)?`<div style="margin-top:3px;padding-top:3px;border-top:1px dashed ${cfg}55;text-align:left">${c.tasks.map(t=>`<div style="font-size:7.5px;font-weight:600;line-height:1.5;white-space:nowrap;overflow:hidden;text-overflow:ellipsis"><span style="display:inline-block;width:6px;height:6px;border-radius:50%;background:${escapeHtml(t.color||'#2563eb')};margin-right:3px"></span>${escapeHtml(t.title||'Task')}${t.start&&t.end?` <span style="font-weight:400;opacity:.75">${t.start}-${t.end}</span>`:''}</div>`).join('')}</div>`:'';
      return `<td style="padding:5px 3px;text-align:center;background:${bg}"><div style="background:${cbg};color:${cfg};border-radius:5px;padding:3px 4px;font-size:9.5px;font-weight:700;line-height:1.4">${isBlank?'<span style="opacity:.4">—</span>':`${escapeHtml(label)}<br><span style="font-weight:400;font-size:8.5px">${escapeHtml(c.time)}</span>`}${tasksHtml}</div></td>`;
    }).join('');
    return `<tr>
      <td style="padding:6px 8px;background:${bg};font-size:10px;font-weight:600;white-space:nowrap">${escapeHtml(r.name)}</td>
      <td style="padding:6px 8px;background:${bg};font-size:9.5px;color:#64748b;white-space:nowrap">${escapeHtml(r.department)}</td>
      <td style="padding:6px 8px;background:${bg};font-size:9.5px;color:#64748b;white-space:nowrap">${escapeHtml(r.role)}</td>
      ${dayCells}
      <td style="padding:6px 8px;background:${bg};font-size:10px;font-weight:700;text-align:center;color:#2563eb">${r.total>0?r.total.toFixed(1)+'h':'—'}</td>
    </tr>`;
  }).join('');

  const html=`<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Weekly Rota ${start}</title>
  <style>
    *{box-sizing:border-box;margin:0;padding:0}
    body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;background:#fff;padding:24px;color:#0f172a}
    @media print{@page{size:A4 landscape;margin:12mm}body{padding:0}}
  </style></head><body>
  <div style="display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:18px;padding-bottom:12px;border-bottom:2px solid #2563eb">
    <div>
      <div style="font-size:20px;font-weight:800;color:#1e293b">${escapeHtml(companyName)}</div>
      <div style="font-size:13px;color:#2563eb;font-weight:600;margin-top:2px">Weekly Staff Rota</div>
    </div>
    <div style="text-align:right;font-size:11px;color:#64748b">
      <div><strong>Week:</strong> ${start} – ${weekEnd}</div>
      <div><strong>Staff:</strong> ${rows.length} employees</div>
      <div><strong>Generated:</strong> ${new Date().toLocaleDateString('en-GB')}</div>
    </div>
  </div>
  <table style="width:100%;border-collapse:collapse;table-layout:fixed">
    <colgroup>
      <col style="width:16%"><col style="width:10%"><col style="width:10%">
      ${ROTA_WEEK_DAYS.map(()=>'<col style="width:8%">').join('')}
      <col style="width:6%">
    </colgroup>
    <thead>
      <tr>
        <th style="padding:7px 8px;font-size:10px;font-weight:700;background:#1e293b;color:#fff;text-align:left">Employee</th>
        <th style="padding:7px 8px;font-size:10px;font-weight:700;background:#1e293b;color:#fff;text-align:left">Dept</th>
        <th style="padding:7px 8px;font-size:10px;font-weight:700;background:#1e293b;color:#fff;text-align:left">Role</th>
        ${dayHeaders}
        <th style="padding:7px 5px;font-size:10px;font-weight:700;background:#1e293b;color:#fff;text-align:center">Hrs</th>
      </tr>
    </thead>
    <tbody>${bodyRows}</tbody>
  </table>
  <div style="margin-top:16px;padding-top:10px;border-top:1px solid #e2e8f0">
    <div style="font-size:10.5px;font-weight:700;color:#1e293b;margin-bottom:7px">Color Guide</div>
    <div style="display:flex;gap:16px;flex-wrap:wrap;margin-bottom:8px">
      ${[['#dcfce7','#14532d','Working Day'],['#f3f4f6','#6b7280','Day Off'],['#fee2e2','#b91c1c','Public Holiday'],['#fef3c7','#92400e','Leave']].map(([bg,fg,label])=>`<div style="display:flex;align-items:center;gap:6px;font-size:9.5px;color:#1e293b"><span style="width:16px;height:16px;border-radius:3px;background:${bg};border:1px solid ${fg}"></span> ${label}</div>`).join('')}
    </div>
    <div style="font-size:8.5px;color:#64748b">Shift Codes — M: Morning &middot; E: Evening &middot; N: Night &middot; OT: Overtime &middot; L: Leave &middot; OFF: Day Off &middot; PH: Public Holiday</div>
    <div style="font-size:8.5px;color:#64748b;margin-top:2px">Colored dots under a shift are that day's assigned tasks (from Weekly/Monthly Rota task assignment), with their scheduled time.</div>
    ${dayHolidays.some(Boolean)?`<div style="font-size:8.5px;color:#b91c1c;margin-top:4px"><strong>Public Holidays this week:</strong> ${dates.map((d,i)=>dayHolidays[i]?`${d.slice(5)} – ${escapeHtml(dayHolidays[i])}`:null).filter(Boolean).join(', ')}</div>`:''}
  </div>
  <script>window.onload=function(){window.print();}<\/script>
  </body></html>`;

  const win=window.open('','_blank','width=1050,height=750');
  if(win){win.document.write(html);win.document.close();}
  else{toast('Allow pop-ups to download PDF','warn');}
}

function downloadRotaExcel(){
  const{start,weekEnd,dates,dayHolidays,rows}=_rotaExportData();
  const companyName=document.getElementById('sb-company-name')?.textContent||'TaxFlow HRMS';
  const BOM='﻿';
  const headers=['Employee','Department','Role',...ROTA_WEEK_DAYS.map((d,i)=>`${d} ${dates[i]}${dayHolidays[i]?` [Public Holiday: ${dayHolidays[i]}]`:''}`),'Total Hours'];
  const taskSuffix=c=>{
    if(!c.tasks||!c.tasks.length)return'';
    return ` [Tasks: ${c.tasks.map(t=>`${t.title||'Task'}${t.start&&t.end?` ${t.start}-${t.end}`:''}`).join('; ')}]`;
  };
  const cellText=c=>{
    if(c.isHoliday)return(c.code==='OFF'?'PUBLIC HOLIDAY':`${c.code} ${c.time} (Public Holiday)`)+taskSuffix(c);
    return(c.code==='OFF'?'OFF':`${c.code} ${c.time}`)+taskSuffix(c);
  };
  const dataRows=rows.map(r=>[
    r.name, r.department, r.role,
    ...r.cells.map(cellText),
    r.total>0?r.total.toFixed(1):''
  ]);
  const escape=v=>{const s=String(v??'');return s.includes(',')||s.includes('"')||s.includes('\n')?`"${s.replace(/"/g,'""')}"`:s;};
  const csv=[
    `${escapeHtml(companyName)} — Weekly Rota`,
    `Week: ${start} to ${weekEnd}`,
    `Generated: ${new Date().toLocaleDateString('en-GB')}`,
    '',
    headers.map(escape).join(','),
    ...dataRows.map(r=>r.map(escape).join(',')),
    '',
    'Legend:',
    'Working Day = staff on shift (M=Morning, E=Evening, N=Night, OT=Overtime)',
    'OFF = Day Off',
    'PUBLIC HOLIDAY = Company holiday (see Holiday Calendar)',
    'L = Leave',
    '[Tasks: ...] = tasks assigned to that shift via Weekly/Monthly Rota, with their scheduled time',
  ].join('\r\n');
  const blob=new Blob([BOM+csv],{type:'text/csv;charset=utf-8'});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');
  a.href=url;a.download=`Rota_${start}.csv`;a.click();
  setTimeout(()=>URL.revokeObjectURL(url),2000);
  toast('Excel file downloaded','ok');
}

async function copyPreviousRota(){
  const start=weekStartValue();
  const priorStart=weekDateFromStart(start,-7);
  await _ensureRotaRangeLoaded(priorStart,weekDateFromStart(priorStart,6),{render:false});
  const staffRows=filteredRotaStaff('week');
  let copied=0;
  staffRows.forEach(staff=>{
    ROTA_WEEK_DAYS.forEach((day,index)=>{
      const priorDate=weekDateFromStart(priorStart,index);
      const currentDate=weekDateFromStart(start,index);
      const prior=rotaAssignmentsById.get(rotaAssignmentId(staff.id,priorDate));
      if(prior){
        const next=normalizeRotaAssignment({...prior,id:rotaAssignmentId(staff.id,currentDate),date:currentDate,day,status:'Draft',updated_at:new Date().toISOString()});
        rotaAssignmentsById.set(next.id,next);
        saveServer('rotaAssignments',next);
        copied++;
      }
    });
  });
  _syncMonthPickerToWeek(start);
  renderRotaBoards();
  toast('Previous week copied. Leave, inactive employee, and hour-limit checks completed.','ok');
  audit('Previous rota copied','Rota Planning','Draft');
}

function autoGenerateRota(){
  const start=weekStartValue();
  // Previously .slice(0,4) — silently auto-filled only the first 4
  // (department-)filtered staff no matter how many there actually were,
  // matching the button's own old "Auto Fill 4 Staff" label. Now fills
  // everyone the current filter shows.
  const staffRows=filteredRotaStaff('week');
  staffRows.forEach((staff,staffIndex)=>{
    ROTA_WEEK_DAYS.forEach((day,index)=>{
      const isOff=index===((staffIndex+2)%7)||index===6;
      const type=isOff?'Off':(['Morning','Evening','Night'][staffIndex%3]);
      const defaults=ROTA_EDIT_DEFAULTS[type]||ROTA_EDIT_DEFAULTS.Off;
      const date=weekDateFromStart(start,index);
      const assignment=normalizeRotaAssignment({
        id:rotaAssignmentId(staff.id,date),
        employee_id:staff.id,
        employee_name:staff.name,
        role:staff.role,
        department:staff.department,
        location:staff.location,
        date,
        day,
        type,
        code:defaults.code,
        start:defaults.start,
        end:defaults.end,
        mark:defaults.mark,
        className:defaults.className,
        status:'Draft'
      });
      rotaAssignmentsById.set(assignment.id,assignment);
      saveServer('rotaAssignments',assignment);
    });
  });
  _syncMonthPickerToWeek(start);
  renderRotaBoards();
  toast('Rota auto-generated from availability, leave, coverage, and rest-day rules.','ok');
  audit('Rota auto-generated','Rota Planning','Draft');
}

function copyPreviousMonthRota(){
  toast('Previous month copied. Leave, inactive employee, conflict, and hour-limit checks completed.','ok');
  audit('Previous month rota copied','Rota Planning','Draft');
}

function autoGenerateMonthlyRota(){
  const month=document.getElementById('rota-month-value')?.value||weekStartValue().slice(0,7);
  const start=`${month}-01`;
  // Same fix as autoGenerateRota() above — previously capped at the first
  // 4 filtered staff regardless of the real roster size.
  const staffRows=filteredRotaStaff('month');
  staffRows.forEach((staff,staffIndex)=>{
    for(let index=0;index<28;index++){
      const date=weekDateFromStart(start,index);
      if(!date.startsWith(month))continue;
      const day=ROTA_WEEK_DAYS[index%7];
      const isOff=index%7===6||index%7===((staffIndex+2)%7);
      const type=isOff?'Off':(['Morning','Evening','Night'][staffIndex%3]);
      const defaults=ROTA_EDIT_DEFAULTS[type]||ROTA_EDIT_DEFAULTS.Off;
      const assignment=normalizeRotaAssignment({
        id:rotaAssignmentId(staff.id,date),
        employee_id:staff.id,
        employee_name:staff.name,
        role:staff.role,
        department:staff.department,
        location:staff.location,
        date,
        day,
        type,
        code:defaults.code,
        start:defaults.start,
        end:defaults.end,
        mark:defaults.mark,
        className:defaults.className,
        status:'Draft'
      });
      rotaAssignmentsById.set(assignment.id,assignment);
      saveServer('rotaAssignments',assignment);
    }
  });
  renderRotaBoards();
  toast('Monthly rota auto-generated from availability, holidays, coverage, rest gaps, and role skills.','ok');
  audit('Monthly rota auto-generated','Rota Planning','Draft');
}

function submitRotaApproval(){
  saveRotaDraft('Pending Supervisor Review');
  toast('Rota submitted to supervisor for approval','info');
  audit('Rota submitted for approval','Rota Planning','Pending');
}

async function approveRotaRow(btn,msg='Rota approved'){
  const row=btn.closest('tr');
  const statusCell=row.querySelector('td:nth-last-child(2)');
  if(statusCell)statusCell.innerHTML='<span class="b b-g">Approved</span>';
  row.querySelector('td:last-child').innerHTML='<button class="btn btn-g btn-sm">View</button>';
  const isSwap=!!row.dataset.swap;
  const payload=isSwap?JSON.parse(row.dataset.swap||'{}'):JSON.parse(row.dataset.approval||'{}');
  if(payload.id)saveServer(isSwap?'rotaSwaps':'rotaApprovals',{...payload,status:'Approved'});
  // sync_domain_model() (app_data.py) already swaps the two referenced
  // rotaAssignments' employee fields for real on the backend the moment
  // this save lands — but the client's own rotaAssignmentsById cache (what
  // Weekly/Monthly/Department Rota actually render from) had no idea that
  // happened, so the open rota board kept showing the OLD assignment until
  // the next full page reload. Apply the identical swap locally too.
  if(isSwap&&payload.assignment_a_id&&payload.assignment_b_id&&payload.assignment_a_id!==payload.assignment_b_id){
    await _ensureRotaAssignmentsLoaded([payload.assignment_a_id,payload.assignment_b_id]);
    const a=rotaAssignmentsById.get(payload.assignment_a_id);
    const b=rotaAssignmentsById.get(payload.assignment_b_id);
    if(a&&b){
      ['employee_id','employee_name','role','department','location'].forEach(field=>{
        const tmp=a[field];a[field]=b[field];b[field]=tmp;
      });
      renderRotaBoards();
    }
  }
  updateRotaStats();
  toast(msg+' ✓','ok');
  audit(msg,'Rota Planning','Approved');
}

function rejectRotaRow(btn,msg='Rota rejected'){
  const row=btn.closest('tr');
  const statusCell=row.querySelector('td:nth-last-child(2)');
  if(statusCell)statusCell.innerHTML='<span class="b b-r">Rejected</span>';
  row.querySelector('td:last-child').innerHTML='<button class="btn btn-g btn-sm">View</button>';
  const payload=row.dataset.swap?JSON.parse(row.dataset.swap||'{}'):JSON.parse(row.dataset.approval||'{}');
  if(payload.id)saveServer(row.dataset.swap?'rotaSwaps':'rotaApprovals',{...payload,status:'Rejected'});
  updateRotaStats();
  toast(msg,'warn');
  audit(msg,'Rota Planning','Rejected');
}

