function _bioCopy(text,btn){
  const done=()=>{const orig=btn.textContent;btn.textContent='✓';btn.style.color='#10b981';setTimeout(()=>{btn.textContent=orig;btn.style.color='';},1500);};
  if(navigator.clipboard&&window.isSecureContext){
    navigator.clipboard.writeText(text).then(done).catch(()=>{_copyFallback(text);done();});
  }else{_copyFallback(text);done();}
}

function copyBioKey(){
  const val=document.getElementById('bio-key-val')?.value||'';
  if(!val){toast('No key to copy','warn');return;}
  if(navigator.clipboard&&window.isSecureContext){
    navigator.clipboard.writeText(val).then(()=>toast('Device Key copied!','ok')).catch(()=>{
      _copyFallback(val);
    });
  } else {
    _copyFallback(val);
  }
}
function _copyFallback(text,label='Device Key'){
  const ta=document.createElement('textarea');
  ta.value=text;ta.style.position='fixed';ta.style.left='-9999px';
  document.body.appendChild(ta);ta.focus();ta.select();
  try{document.execCommand('copy');toast(`${label} copied!`,'ok');}
  catch{toast('Copy failed — select and copy manually','warn');}
  document.body.removeChild(ta);
}

let _bioGuideModes=null;

function _buildBioGuideModes(apiKey, type, ip, port, serialNumber){
  // window.TAXFLOW_API_BASE_URL is never actually set anywhere in this app
  // (see downloadBridgeScript()'s comment) — window.location.origin is the
  // same bare-origin value apiBaseUrl() itself derives from, and works
  // correctly in local dev too instead of always pointing at production.
  const baseUrl=window.location.origin;
  const keyDisplay=apiKey||'YOUR_DEVICE_KEY';
  const hasRealKey=!!apiKey;
  const I=_BIO_ICONS;
  const tcpLabel=BIO_TCP_TYPES.has(type)?type.replace('ZKTeco ','').toUpperCase():'ZK';
  const confSnippet=`DEVICE_API_KEY=${keyDisplay}\nZK_DEVICE_IP=${ip||'192.168.1.201'}\nZK_DEVICE_PORT=${port||4370}\nAPI_BASE_URL=${baseUrl}`;
  // Only offer a one-click download when the real (not-yet-hashed) key is in
  // memory — showBioGuide() is also opened later from the device list's
  // "Guide" button with apiKey=null, where confSnippet falls back to the
  // literal placeholder text. A download button there would hand out a
  // .conf file baked with "YOUR_DEVICE_KEY" and no obvious sign it's wrong.
  const confDownloadBtn=hasRealKey
    ?`<button onclick="downloadBioConfig(${jsonAttr(confSnippet)})" style="flex-shrink:0;padding:2px 8px;font-size:10px;border-radius:5px;border:1px solid var(--border);background:var(--bg2);cursor:pointer;white-space:nowrap">⬇ Download</button>`
    :`<span title="Only available right after creating the device — its key can't be retrieved afterward. Copy it from where you saved it and fill in the file above by hand, or delete and re-add the device." style="flex-shrink:0;padding:2px 8px;font-size:10px;border-radius:5px;border:1px dashed var(--border);color:var(--text3);white-space:nowrap;cursor:help">⬇ Download (unavailable)</span>`;

  // A real key (right after creating the device) means the download can be
  // baked with everything it needs — one file, nothing left to configure by
  // hand. Reopening this guide later from the device list has no key to
  // give it (see confDownloadBtn's own comment above for why), so that case
  // falls back to the old generic-script + manual-conf two-step flow.
  const downloadStep=hasRealKey
    ? {icon:I.download, title:'Download Your Ready-to-Run Script', color:'var(--accent)',
       body:`These devices are pulled over TCP/IP by a small script that runs on a PC on the <strong>same network</strong> as the device — they are not webhook devices. This copy already has your Device Key${ip?', device IP,':''} and API address baked in — nothing left to edit.<br><button onclick="downloadBridgeScript(${jsonAttr(apiKey)},${jsonAttr(ip||'')},${jsonAttr(String(port||''))})" style="margin-top:6px;padding:5px 12px;font-size:11px;border-radius:6px;border:1px solid var(--border);background:var(--surface);cursor:pointer;font-weight:600">⬇ Download zk_bridge.py</button>
       ${!ip?`<div style="margin-top:8px;padding:7px 10px;background:var(--surface2);border:1px solid var(--border);border-radius:7px;font-size:10.5px;line-height:1.6;color:var(--text2)"><strong>No device IP was set when this device was added</strong> — open the downloaded file in a text editor and set <code>ZK_DEVICE_IP</code> in the config block near the top, or create a <code>zk_bridge.conf</code> next to it (see the details below).</div>`:''}
       <div style="margin-top:8px;padding:7px 10px;background:var(--surface2);border:1px solid var(--border);border-radius:7px;font-size:10.5px;line-height:1.6;color:var(--text2)">
        <strong>Also want a local daily CSV/Excel attendance report</strong> (Clock In/Out per session, OT, Under Time, Absent — not just live sync)? Download <code>daily_attendance_report.py</code> instead — same Device Key/IP/API address already baked in, but meant to run once a day (e.g. via Task Scheduler) rather than continuously.
        <div><button onclick="downloadReportScript(${jsonAttr(apiKey)},${jsonAttr(ip||'')},${jsonAttr(String(port||''))})" style="margin-top:6px;padding:5px 12px;font-size:11px;border-radius:6px;border:1px solid var(--border);background:var(--surface);cursor:pointer;font-weight:600">⬇ Download daily_attendance_report.py</button></div>
       </div>
       <details style="margin-top:8px"><summary style="cursor:pointer;font-size:10.5px;color:var(--text3)">Prefer a separate config file instead? (e.g. to reuse one script across several devices)</summary>
        <div style="margin-top:6px;display:flex;align-items:flex-start;gap:8px;background:var(--surface);border:1px solid var(--border);border-radius:7px;padding:8px 10px">
         <pre style="flex:1;margin:0;font-size:10.5px;line-height:1.6;white-space:pre-wrap;word-break:break-all">${escapeHtml(confSnippet)}</pre>
         <div style="display:flex;flex-direction:column;gap:5px;flex-shrink:0">
           <button onclick="_bioCopy(${jsonAttr(confSnippet)},this)" style="padding:2px 8px;font-size:10px;border-radius:5px;border:1px solid var(--border);background:var(--bg2);cursor:pointer;white-space:nowrap">Copy</button>
           ${confDownloadBtn}
         </div>
        </div>
        <div style="margin-top:5px;font-size:10.5px;color:var(--text3)">Save as <code>zk_bridge.conf</code> next to a plain (non-baked) copy of the script — a real config file always takes priority over what's baked into the script.</div>
       </details>`}
    : {icon:I.download, title:'Download the Bridge Script', color:'var(--accent)',
       body:`These devices are pulled over TCP/IP by a small script that runs on a PC on the <strong>same network</strong> as the device — they are not webhook devices.<br><button onclick="downloadBridgeScript()" style="margin-top:6px;padding:5px 12px;font-size:11px;border-radius:6px;border:1px solid var(--border);background:var(--surface);cursor:pointer;font-weight:600">⬇ Download zk_bridge.py</button>
       <div style="margin-top:8px;padding:7px 10px;background:var(--surface2);border:1px solid var(--border);border-radius:7px;font-size:10.5px;line-height:1.6;color:var(--text2)">This guide was reopened after the device was already created, so its Device Key can no longer be baked in automatically (it's only ever shown once) — create <code>zk_bridge.conf</code> by hand next to the script with the values below, using the key you saved earlier.</div>
       <div style="margin-top:6px;background:var(--surface);border:1px solid var(--border);border-radius:7px;padding:8px 10px"><pre style="margin:0;font-size:10.5px;line-height:1.6;white-space:pre-wrap;word-break:break-all">${escapeHtml(confSnippet)}</pre></div>
       <div style="margin-top:8px;font-size:10.5px;color:var(--text3)">Also want a local daily CSV/Excel attendance report instead of (or alongside) live sync? <button onclick="downloadReportScript()" style="margin-left:2px;padding:2px 8px;font-size:10px;border-radius:5px;border:1px solid var(--border);background:var(--bg2);cursor:pointer">⬇ daily_attendance_report.py</button> — same manual config as above, using the same <code>ETAXFLOW_DEVICE_KEY</code>/<code>DEVICE_IP</code> variable names.</div>`};

  const tcp={
    label:'TCP/IP Pull',
    tag:'Bridge script · ZKTeco F/K/iClock/X Face Pro/SpeedFace/ProFace/G/UA/IN/MB Series, Anviz',
    diagram:_bioDiagramTCP(tcpLabel),
    steps:[
      downloadStep,
      {icon:I.terminal, title:'Install pyzk and Run the Script', color:'var(--accent)',
       body:`On that same PC: <code>pip install pyzk requests</code>, then <code>python zk_bridge.py</code>. It connects to the device, polls every 30 seconds, and forwards new punches automatically — leave it running (use <code>pm2</code> or a service for production).`},
      {icon:I.badge, title:'Enroll Employees With Matching IDs', color:'var(--amber)',
       body:`<strong>This step is required, not optional</strong> — TaxFlow has no separate "biometric ID" field. It matches a punch to an employee by comparing the device's own <strong>User ID</strong> to that employee's <strong>Employee ID</strong> in TaxFlow (Staff → Employees), as plain text.<br><br>
       When enrolling each employee's fingerprint/face on the device, set the device's <em>User ID</em> field to their exact TaxFlow Employee ID — not their name, not a number the device assigns automatically. If it doesn't match exactly, the punch still reaches TaxFlow but won't attach to that employee anywhere (Present Today, payslips, attendance reports).`},
      {icon:I.check, title:'Test — Punch In &amp; Check Sync Log', color:'#10b981',
       body:'With <code>zk_bridge.py</code> running, scan your finger or card on the device → click <strong>⟳ Refresh</strong> on the <strong>Sync Activity Log</strong>. The punch record should appear within about 30 seconds, attributed to the employee whose ID matches. If it doesn\'t, check the device IP/port and API key — or if it appears but isn\'t linked to the right employee, re-check the enrolled User ID against the previous step.'},
    ]
  };

  const manual={
    label:'Manual / CSV',
    tag:'No live connection · any device with an export function',
    diagram:_bioDiagramCSV(),
    steps:[
      {icon:I.csv, title:'Export and Import a CSV', color:'var(--accent)',
       body:'No live connection to configure. Export the attendance log from the device\'s own software, then click <strong>↑ Import CSV</strong> in the Sync Activity Log. Required columns: <code>employee_id, punch_time</code> (optional: <code>employee_name, direction</code>).<br><br><strong>The <code>employee_id</code> column must contain each employee\'s exact TaxFlow Employee ID</strong> (Staff → Employees) — not the device\'s own internal user number, unless you enrolled employees on the device using their TaxFlow Employee ID as the User ID. A row whose ID doesn\'t match any employee still imports, it just won\'t attach to anyone.'},
    ]
  };

  return {tcp,manual};
}

function _renderBioGuideSteps(steps){
  const lastIdx=steps.length-1;
  return steps.map((s,i)=>`
    <div style="display:flex;gap:12px;align-items:flex-start;padding:10px 12px;background:${i===lastIdx?'rgba(16,185,129,.06)':'var(--surface2)'};border-radius:10px;border-left:3px solid ${s.color}">
      <div style="flex-shrink:0;width:28px;height:28px;border-radius:50%;background:${s.color};color:#fff;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:800">${i+1}</div>
      <div style="flex:1">
        <div style="display:flex;align-items:center;gap:6px;margin-bottom:3px">
          <span style="color:${s.color}">${s.icon}</span>
          <span style="font-size:12px;font-weight:700${i===lastIdx?';color:#065f46':''}">${s.title}</span>
        </div>
        <div style="font-size:11.5px;color:var(--text2);line-height:1.7">${s.body}</div>
      </div>
    </div>`).join('');
}

const BIO_MODE_ORDER=['tcp','manual'];
const _BIO_MODE_HINT={
  tcp:'Needs a script running on an office PC',
  manual:'No live connection — export/import only',
};

function switchBioGuideMode(mode){
  if(!_bioGuideModes||!_bioGuideModes.modes[mode])return;
  const m=_bioGuideModes.modes[mode];
  const subEl=document.getElementById('bio-guide-sub');
  const diagramEl=document.getElementById('bio-guide-diagram');
  const stepsEl=document.getElementById('bio-guide-steps');
  const recommended=mode===_bioGuideModes.recommended;
  if(subEl) subEl.textContent=m.tag+(recommended?' — recommended for this device':'');
  if(diagramEl) diagramEl.innerHTML=m.diagram;
  if(stepsEl) stepsEl.innerHTML=_renderBioGuideSteps(m.steps);
  document.querySelectorAll('#bio-guide-tabs [data-mode]').forEach(card=>{
    const active=card.dataset.mode===mode;
    card.style.borderColor=active?'var(--accent)':'var(--border)';
    card.style.background=active?'rgba(99,102,241,.10)':'var(--surface2)';
    card.style.boxShadow=active?'0 0 0 1px var(--accent)':'none';
    const check=card.querySelector('.bio-tab-check');
    if(check)check.style.visibility=active?'visible':'hidden';
  });
}

function showBioGuide(apiKey, type, ip, port, serialNumber){
  const keyEl=document.getElementById('bio-key-val');
  const keyRow=document.getElementById('bio-guide-key-row');
  const keyAvail=document.getElementById('bio-key-available');
  const keyMissing=document.getElementById('bio-key-missing');
  const keyDisplay_el=document.getElementById('bio-key-val-display');
  const tabsEl=document.getElementById('bio-guide-tabs');

  const isAdmsClassic=BIO_ADMS_CLASSIC_TYPES.has(type);
  if(keyEl) keyEl.value=apiKey||'';
  if(keyDisplay_el) keyDisplay_el.textContent=apiKey||'';
  // ADMS Classic never has a device key at all (identified by serial number
  // instead) — showing the "key not available, re-add the device" box would
  // be actively wrong for it, not just empty.
  if(keyRow) keyRow.style.display=isAdmsClassic?'none':'';
  if(keyAvail) keyAvail.style.display=apiKey?'':'none';
  if(keyMissing) keyMissing.style.display=apiKey?'none':'';

  const modes=_buildBioGuideModes(apiKey,type,ip,port,serialNumber);
  // Only 'tcp'/'manual' are real modes now (HTTP/ADMS Push and ADMS Classic
  // were removed) — anything else (including a legacy device of one of
  // those now-unsupported types, if one ever exists) falls back to 'tcp'
  // rather than a mode key _buildBioGuideModes() no longer builds at all.
  const recommended=type==='Manual'?'manual':'tcp';
  const defaultTab=recommended;
  _bioGuideModes={modes,recommended};

  if(tabsEl){
    tabsEl.style.gap='10px';
    tabsEl.innerHTML=BIO_MODE_ORDER.map(key=>{
      const m=modes[key];
      const isRecommended=key===recommended;
      return `<button data-mode="${key}" onclick="switchBioGuideMode('${key}')" style="flex:1 1 170px;min-width:160px;text-align:left;cursor:pointer;padding:13px 14px;border-radius:12px;border:2px solid var(--border);background:var(--surface2);transition:border-color .15s,background .15s,box-shadow .15s">
        <div style="display:flex;align-items:center;justify-content:space-between;gap:6px">
          <span style="font-size:13.5px;font-weight:800;color:var(--text1)">${m.label}</span>
          <span class="bio-tab-check" style="visibility:hidden;color:var(--accent);font-weight:900;font-size:14px">✓</span>
        </div>
        <div style="font-size:11px;color:var(--text2);line-height:1.5;margin-top:4px">${_BIO_MODE_HINT[key]||''}</div>
        ${isRecommended?`<div style="margin-top:8px;display:inline-block;font-size:9.5px;font-weight:800;letter-spacing:.02em;color:var(--accent);background:rgba(99,102,241,.12);padding:3px 8px;border-radius:6px">YOUR DEVICE</div>`:''}
      </button>`;
    }).join('');
  }

  switchBioGuideMode(defaultTab);
  showM('m-bio-key');
}

async function saveBiometricDevice(){
  const name=(document.getElementById('bio-dev-name')?.value||'').trim();
  const type=document.getElementById('bio-dev-type')?.value||'ZKTeco F Series';
  const loc=(document.getElementById('bio-dev-location')?.value||'').trim();
  if(!name){toast('Device name is required','warn');return;}

  if(BIO_BIOTIME_TYPES.has(type)){
    const baseUrl=(document.getElementById('bio-dev-biotime-url')?.value||'').trim();
    const username=(document.getElementById('bio-dev-biotime-user')?.value||'').trim();
    const password=document.getElementById('bio-dev-biotime-pass')?.value||'';
    if(!baseUrl||!username||!password){toast('Server URL, username and password are all required','warn');return;}
    try{
      await moduleApi('/attendance/devices',{method:'POST',body:{
        name,device_type:type,location:loc||null,
        biotime_base_url:baseUrl,biotime_username:username,biotime_password:password,
      }});
      toast('BioTime server connected — syncing now…','ok');
      closeM('m-bio-device');
      ['bio-dev-name','bio-dev-location','bio-dev-biotime-url','bio-dev-biotime-user','bio-dev-biotime-pass'].forEach(id=>{const el=document.getElementById(id);if(el)el.value='';});
      await loadBiometricDevices();
    }catch(e){toast('Failed to connect BioTime server: '+e,'warn');}
    return;
  }

  const ip=(document.getElementById('bio-dev-ip')?.value||'').trim();
  const port=parseInt(document.getElementById('bio-dev-port')?.value)||4370;
  try{
    const res=await moduleApi('/attendance/devices',{method:'POST',body:{name,device_type:type,ip_address:ip||null,port,location:loc||null}});
    if(res.api_key){
      closeM('m-bio-device');
      ['bio-dev-name','bio-dev-ip','bio-dev-location'].forEach(id=>{const el=document.getElementById(id);if(el)el.value='';});
      showBioGuide(res.api_key,type,ip,port);
    } else {
      toast('Device added','ok');closeM('m-bio-device');loadBiometricDevices();
    }
  }catch(e){toast('Failed to add device: '+e,'warn');}
}

async function syncBiometricDeviceNow(id,btn){
  const orig=btn.textContent;
  btn.textContent='Syncing…';btn.disabled=true;
  try{
    const res=await moduleApi(`/attendance/devices/${encodeURIComponent(id)}/biotime/sync`,{method:'POST',body:{}});
    toast(res.message||`Synced ${res.synced||0} record(s)`,'ok');
    loadBiometricDevices();
    loadBioSyncLog();
  }catch(e){
    toast('Sync failed: '+(e?.message||e),'warn');
  }
  btn.textContent=orig;btn.disabled=false;
}

async function testBiometricDevice(id,btn){
  const orig=btn.textContent;
  btn.textContent='Testing…';btn.disabled=true;
  const row=btn.closest('tr');
  // Remove any previous result row
  const prev=row?.nextElementSibling;
  if(prev?.dataset?.testResult)prev.remove();
  const showTestResult=(ok,msg)=>{
    if(row){
      const tr=document.createElement('tr');
      tr.dataset.testResult='1';
      const cols=row.querySelectorAll('td').length||8;
      tr.innerHTML=`<td colspan="${cols}" style="padding:6px 14px 8px;background:${ok?'var(--green-bg)':'var(--red-bg)'};border-bottom:1px solid var(--border)">
        <span style="font-size:12px;font-weight:700;color:${ok?'var(--green)':'var(--red)'}">${ok?'✓':'✗'} ${escapeHtml(msg)}</span>
        <button onclick="this.closest('tr').remove()" style="float:right;background:none;border:none;color:var(--text3);cursor:pointer;font-size:13px;line-height:1">×</button>
      </td>`;
      row.after(tr);
      setTimeout(()=>{if(tr.isConnected)tr.remove();},ok?8000:12000);
    } else {
      toast(msg, ok?'ok':'warn');
    }
  };
  try{
    const res=await moduleApi(`/attendance/devices/${encodeURIComponent(id)}/test`,{method:'POST',body:{}});
    showTestResult(!!res.ok, res.message||'Done');
  }catch(e){
    showTestResult(false, 'Test request failed: '+(e?.message||e));
  }
  btn.textContent=orig;btn.disabled=false;
}

async function deleteBiometricDevice(id,btn){
  if(!(await appConfirm({title:'Remove Device',message:'Remove this device?',okText:'Remove'})))return;
  try{
    await moduleApi(`/attendance/devices/${encodeURIComponent(id)}`,{method:'DELETE'});
    btn.closest('tr').remove();
    toast('Device removed','ok');
  }catch(e){toast('Failed: '+e,'warn');}
}

// ── Attendance: Today's data from API ─────────────────────────────────────────

// Maps a punch event's "source" (backend truth: "device"/"biotime" = a real
// scanner tap, "csv"/"manual"/"correction" = not) to the Today's Attendance
// badge. Previously every row said "Biometric" unconditionally.
function _attendanceSourceBadge(source){
  const map={
    device:['Biometric','b-g'],
    biotime:['Biometric','b-g'],
    csv:['CSV Import','b-b'],
    correction:['Correction','b-a'],
    manual:['Manual','b-b'],
  };
  const [label,cls]=map[source]||['Manual','b-b'];
  return `<span class="b ${cls}">${label}</span>`;
}

async function refreshAttendanceToday(){
  const tbody=document.getElementById('att-today-tbody');
  // Previously always "today" with no way to look at any other day —
  // defaults the picker to today on first load, then honors whichever
  // date is selected on every subsequent refresh/re-render.
  const dateInput=document.getElementById('att-today-date');
  if(dateInput&&!dateInput.value){
    const now=new Date();
    dateInput.value=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;
  }
  const selectedDate=dateInput?.value||'';
  try{
    const res=await moduleApi(`/attendance/today${selectedDate?`?date=${encodeURIComponent(selectedDate)}`:''}`);
    const count=res.present_count||0;
    const ids=res.employee_ids||[];
    const set=(id,v)=>{const el=document.getElementById(id);if(el)el.textContent=v;};
    set('att-stat-present',count);
    set('att-stat-sync',new Date().toLocaleTimeString('en-AE'));
    // #att-time used to be a static, never-updated "Live" label with no
    // actual date anywhere on the card. res.date is the company-LOCAL
    // today (backend's _local_today()) — using it here instead of the
    // browser's own new Date() keeps it consistent with which punches
    // this same response actually counts as "today" for this company.
    const dateStr=res.date?new Date(`${res.date}T00:00:00`):new Date();
    set('att-time',dateStr.toLocaleDateString('en-AE',{weekday:'short',day:'numeric',month:'short',year:'numeric'}));
    const kpiEl=document.getElementById('hrms-kpi-present');
    if(kpiEl&&count>0)kpiEl.textContent=count;
    // Headcount must update regardless of whether anyone's punched in today
    // — this used to sit after the empty-punches early return below, so on
    // any company with zero attendance data (i.e. most fresh companies) the
    // tile stayed frozen at its clearStaticDemoData() default of "0"
    // instead of the real employee count.
    // Active only — same "Total Employees shouldn't count Inactive staff"
    // rule already applied elsewhere (dashboard KPI, currentRotaStaff()).
    const empTotal=_getAttendanceEmployees().length;
    set('att-stat-total',empTotal||'—');
    if(!tbody)return;
    if(!ids.length){
      tbody.innerHTML='<tr data-empty-state><td colspan="5" style="text-align:center;color:var(--text3);padding:32px">No punch-ins recorded for today yet.</td></tr>';
      return;
    }
    tbody.innerHTML='';
    // Real name matched from Staff -> Employees (Employee.employee_no ==
    // punch employee_id) — previously just showed the raw device ID with
    // no lookup against the actual employee record at all.
    const employees=Array.isArray(res.employees)?res.employees:ids.map(id=>({employee_id:id,employee_name:null,matched:false}));
    employees.forEach(emp=>{
      const tr=document.createElement('tr');
      const label=emp.employee_name
        ?`${escapeHtml(emp.employee_name)} <span class="mono" style="color:var(--text3);font-size:11px">(${escapeHtml(emp.employee_id)})</span>`
        :`${escapeHtml(emp.employee_id)} <span style="color:var(--red)" title="No employee has this ID — check Staff → Employees">⚠ Unmatched</span>`;
      // check_in_time is the employee's first "in" punch of the day and
      // check_out_time the day's last checkout (null while still on the
      // clock / entry-only device), both in company-local time (HH:MM:SS).
      // Source badge previously hardcoded "Biometric" on every row no matter
      // how the punch actually got in (CSV import, manual entry, a
      // correction) — misrepresenting non-device data as a real scanner tap.
      const status=emp.check_out_time
        ?'<span class="b" style="background:var(--bg3);color:var(--text2)">Checked out</span>'
        :'<span class="b b-g">Present</span>';
      tr.innerHTML=`<td>${label}</td><td class="mono">${escapeHtml(emp.check_in_time||'—')}</td><td class="mono">${escapeHtml(emp.check_out_time||'—')}</td><td>${_attendanceSourceBadge(emp.source)}</td><td>${status}</td>`;
      tbody.appendChild(tr);
    });
  }catch(e){
    // Still show today's date even when the API call itself fails (e.g.
    // no biometric connected yet, the common case this empty-state text
    // below is written for) — falls back to the browser's own local date
    // since there's no company-local date available from a failed call.
    const dateEl=document.getElementById('att-time');
    if(dateEl)dateEl.textContent=new Date().toLocaleDateString('en-AE',{weekday:'short',day:'numeric',month:'short',year:'numeric'});
    if(tbody)tbody.innerHTML='<tr data-empty-state><td colspan="5" style="text-align:center;color:var(--text3);padding:32px">Biometric not connected yet. Import CSV or connect a device.</td></tr>';
  }
}

// ── Attendance Trend Chart from API ───────────────────────────────────────────

async function loadAttendanceTrend(){
  const container=document.getElementById('att-trend-chart');
  const sub=document.getElementById('att-trend-sub');
  if(!container)return;
  try{
    const res=await moduleApi('/attendance/trend?days=30');
    const dates=res.dates||[];
    const counts=res.counts||[];
    if(!dates.length||counts.every(c=>c===0)){
      container.innerHTML='<div style="height:100px;display:flex;align-items:center;justify-content:center;color:var(--text3);font-size:12px">No attendance data yet — connect a device or import CSV.</div>';
      if(sub)sub.textContent='No data';
      return;
    }
    const chart=_renderAttendanceTrendChart(dates,counts);
    container.innerHTML=chart.html;
    if(sub)sub.textContent=chart.subText;
    // Also update dashboard Attendance Trend card
    _updateDashboardAttTrend(dates,counts);
  }catch(e){
    container.innerHTML='<div style="height:100px;display:flex;align-items:center;justify-content:center;color:var(--text3);font-size:12px">Unable to load trend data.</div>';
  }
}

// Shared bar-chart renderer for the Attendance tab's own chart and the
// Dashboard's smaller "Workforce Attendance Trend" card. Previously both
// drew a raw line+area chart, and the average always divided by the FULL
// window even when most of it was zero because biometric tracking hadn't
// started yet — e.g. 25 pre-tracking zero days dragging a real ~22/day
// average down to a misleading "4/day", while the line chart itself wasted
// most of its width on a flat stretch at zero. Bars read better once
// "several days at zero" is an expected, real shape rather than noise
// (pre-tracking days are drawn in muted gray, not the same blue as real
// data, so they still read as "before tracking" at a glance); the average
// now only counts from the first day any company-wide punch exists.
//
// Redesign (2026-09-03): colors moved from hardcoded hex to theme tokens
// (via style="" rather than the fill="" attribute — SVG presentation
// attributes don't reliably resolve var() the way an inline style does)
// so the chart doesn't stay light-only once HRMS is viewed in dark mode;
// weekend columns get a faint background band since UAE Fri/Sat naturally
// read as near-zero and previously looked identical to a real attendance
// gap; today's bar gets an accent outline + "Today" label the same way
// the ESS "My Upcoming Shifts" redesign highlights the current day; and a
// small legend was added since the muted/tracked color split and the avg
// line previously had no key explaining what they meant.
function _renderAttendanceBarChart(dates,counts,{width:W,height:H,showLabels=false,showAvgLine=false,fullSize=false}={}){
  const PAD=4;
  const n=dates.length;
  const max=Math.max(1,...counts);
  const firstActiveIdx=counts.findIndex(c=>c>0);
  const trackedCounts=firstActiveIdx>=0?counts.slice(firstActiveIdx):counts;
  const avg=trackedCounts.length?Math.round(trackedCounts.reduce((a,b)=>a+b,0)/trackedCounts.length):0;
  const slotW=(W-PAD*2)/n;
  const barW=Math.max(1,slotW*0.64);
  const todayIso=new Date().toISOString().slice(0,10);
  const gradId='attTrendGrad'+Math.random().toString(36).slice(2,8);
  const weekendBands=dates.map((iso,i)=>{
    const dow=new Date(iso+'T00:00:00').getDay();
    if(dow!==5&&dow!==6)return ''; // UAE weekend: Friday/Saturday
    const x=(PAD+i*slotW).toFixed(1);
    return `<rect x="${x}" y="0" width="${slotW.toFixed(1)}" height="${H}" style="fill:var(--text3)" fill-opacity="0.06"/>`;
  }).join('');
  const bars=counts.map((c,i)=>{
    const barH=c>0?Math.max(2,(c/max)*(H-PAD*2)):0;
    const x=PAD+i*slotW+(slotW-barW)/2;
    const y=H-PAD-barH;
    const tracked=firstActiveIdx<0||i>=firstActiveIdx;
    const isToday=dates[i]===todayIso;
    const fillStyle=tracked?`fill:url(#${gradId})`:'fill:var(--text3);fill-opacity:0.3';
    return `<rect x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${barW.toFixed(1)}" height="${Math.max(barH,1).toFixed(1)}" rx="2" style="${fillStyle}"${isToday?` stroke="var(--accent)" stroke-width="1.5"`:''}><title>${dates[i]}: ${c} present${isToday?' (today)':''}</title></rect>`;
  }).join('');
  let avgLine='';
  if(showAvgLine&&firstActiveIdx>=0&&avg>0){
    const avgY=(H-PAD-(avg/max)*(H-PAD*2)).toFixed(1);
    const x1=(PAD+firstActiveIdx*slotW).toFixed(1);
    avgLine=`<line x1="${x1}" y1="${avgY}" x2="${(W-PAD).toFixed(1)}" y2="${avgY}" style="stroke:var(--amber)" stroke-width="1" stroke-dasharray="3,3"/>`+
      `<text x="${(W-PAD).toFixed(1)}" y="${(Number(avgY)-3).toFixed(1)}" text-anchor="end" font-size="8.5" font-weight="700" style="fill:var(--amber)">avg ${avg}</text>`;
  }
  let todayMarker='';
  if(showLabels){
    const todayIdx=dates.indexOf(todayIso);
    if(todayIdx>=0){
      const x=(PAD+todayIdx*slotW+slotW/2).toFixed(1);
      todayMarker=`<text x="${x}" y="${H+14}" text-anchor="middle" font-size="8.5" font-weight="700" style="fill:var(--accent)">Today</text>`;
    }
  }
  let labels='';
  if(showLabels){
    labels=[0,Math.floor((n-1)/2),n-1].map(i=>{
      if(!dates[i]||dates[i]===todayIso)return ''; // "Today" marker above already covers this slot
      const x=(PAD+i*slotW+slotW/2).toFixed(1);
      return `<text x="${x}" y="${H+14}" text-anchor="middle" font-size="9" style="fill:var(--text3)">${dates[i].slice(5)}</text>`;
    }).join('');
  }
  const labelSpace=showLabels?18:0;
  const svgAttrs=fullSize
    ?`viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" style="width:100%;height:100%"`
    :`viewBox="0 0 ${W} ${H+labelSpace}" width="100%" style="overflow:visible"`;
  const defs=`<defs><linearGradient id="${gradId}" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" style="stop-color:var(--accent2,var(--accent))"/><stop offset="100%" style="stop-color:var(--accent)"/></linearGradient></defs>`;
  const svg=`<svg ${svgAttrs}>${defs}${weekendBands}${bars}${avgLine}${labels}${todayMarker}</svg>`;
  const subText=firstActiveIdx>0
    ?`Avg ${avg} employees/day since tracking began (${_fmtTrendDate(dates[firstActiveIdx])}) — earlier days had no device data`
    :`Avg ${avg} employees/day over last ${n} days`;
  return {svg,subText,avg,firstActiveIdx};
}

function _fmtTrendDate(iso){
  const d=new Date(iso+'T00:00:00');
  if(isNaN(d.getTime()))return iso;
  return d.toLocaleDateString('en-US',{month:'short',day:'numeric'});
}

function _updateDashboardAttTrend(dates,counts){
  const wrap=document.querySelector('.hrms-line-chart-wrap');
  if(!wrap)return;
  // A line/area chart, not the bar chart the Attendance page's own bigger
  // trend chart uses — this compact Dashboard card's own header icon is a
  // trend-line illustration ("Attendance Trend"), so the actual chart
  // rendered underneath should match that, not bars.
  const chart=_renderAttendanceLineChart(dates,counts,{width:400,height:100,fullSize:true});
  wrap.innerHTML=`<div style="width:100%;height:100%;display:flex;flex-direction:column"><div style="flex:1;min-height:0">${chart.svg}</div><div style="font-size:10.5px;color:var(--text3);text-align:center;padding-top:4px">${escapeHtml(chart.subText)}</div></div>`;
}

function _renderAttendanceLineChart(dates,counts,{width:W,height:H,fullSize=false}={}){
  const PAD=6;
  const n=dates.length;
  const max=Math.max(1,...counts);
  const firstActiveIdx=counts.findIndex(c=>c>0);
  const trackedCounts=firstActiveIdx>=0?counts.slice(firstActiveIdx):counts;
  const avg=trackedCounts.length?Math.round(trackedCounts.reduce((a,b)=>a+b,0)/trackedCounts.length):0;
  const todayIso=new Date().toISOString().slice(0,10);
  const stepX=n>1?(W-PAD*2)/(n-1):0;
  const points=counts.map((c,i)=>[PAD+i*stepX,H-PAD-(c/max)*(H-PAD*2)]);
  const linePath=points.map(([x,y],i)=>`${i===0?'M':'L'}${x.toFixed(1)},${y.toFixed(1)}`).join(' ');
  const lastX=points.length?points[points.length-1][0].toFixed(1):PAD;
  const firstX=points.length?points[0][0].toFixed(1):PAD;
  const areaPath=points.length?`${linePath} L${lastX},${(H-PAD).toFixed(1)} L${firstX},${(H-PAD).toFixed(1)} Z`:'';
  const gradId='attTrendAreaGrad'+Math.random().toString(36).slice(2,8);
  const todayIdx=dates.indexOf(todayIso);
  const dots=points.map(([x,y],i)=>{
    const isToday=i===todayIdx;
    const r=isToday?3:1.6;
    const style=isToday?`fill:var(--accent)" stroke="var(--surface,#fff)" stroke-width="1.5`:'fill:var(--accent)" opacity="0.55';
    return `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${r}" style="${style}"><title>${dates[i]}: ${counts[i]} present${isToday?' (today)':''}</title></circle>`;
  }).join('');
  const defs=`<defs><linearGradient id="${gradId}" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" style="stop-color:var(--accent)" stop-opacity="0.3"/><stop offset="100%" style="stop-color:var(--accent)" stop-opacity="0"/></linearGradient></defs>`;
  const svgAttrs=fullSize
    ?`viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" style="width:100%;height:100%"`
    :`viewBox="0 0 ${W} ${H}" width="100%" style="overflow:visible"`;
  const svg=`<svg ${svgAttrs}>${defs}<path d="${areaPath}" style="fill:url(#${gradId})"/><path d="${linePath}" style="fill:none;stroke:var(--accent)" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/>${dots}</svg>`;
  const subText=firstActiveIdx>0
    ?`Avg ${avg} employees/day since tracking began (${_fmtTrendDate(dates[firstActiveIdx])})`
    :`Avg ${avg} employees/day over last ${n} days`;
  return {svg,subText,avg,firstActiveIdx};
}

// ── CSV Import ────────────────────────────────────────────────────────────────

async function importAttendanceCsv(input){
  const file=input.files?.[0];
  if(!file)return;
  if(!file.name.endsWith('.csv')){toast('Please select a .csv file','warn');return;}
  const formData=new FormData();
  formData.append('file',file);
  try{
    const token=localStorage.getItem('taxflow_token')||'';
    // window.TAXFLOW_API_BASE_URL is never actually set anywhere in this
    // app, so this always fell through to 'http://localhost:8000' on the
    // real deployed site — CSV import has been silently broken in
    // production ("TypeError: Failed to fetch") this whole time. A plain
    // fetch (not authenticatedFetch()) is kept deliberately: backendHeaders()
    // hardcodes Content-Type: application/json, which would corrupt this
    // multipart FormData upload's own auto-generated boundary header.
    const resp=await fetch(`${apiBaseUrl()}/attendance/import-csv`,{method:'POST',headers:{Authorization:`Bearer ${token}`},body:formData});
    const res=await resp.json();
    if(resp.ok){
      // duplicates/rejected are new — re-uploading the same file (or a file
      // with a future-dated/90+-day-old row) previously imported every row
      // again with no feedback that anything was actually skipped.
      const extra=[res.duplicates?`${res.duplicates} duplicate`:'',res.rejected?`${res.rejected} rejected`:''].filter(Boolean).join(', ');
      toast(`Imported ${res.imported} records (${res.skipped} skipped${extra?', '+extra:''})`,'ok');
      refreshAttendanceToday();
      loadAttendanceTrend();
    } else {
      toast(res.detail||'Import failed','warn');
    }
  }catch(e){toast('Import error: '+e,'warn');}
  input.value='';
}

function openAttendanceCheck(){
  // Fill table with all Present immediately — modal is only for marking absences
  markAllPresent();
  const today=new Date().toLocaleDateString('en-AE',{weekday:'long',year:'numeric',month:'long',day:'numeric'});
  const el=document.getElementById('att-check-date');
  if(el)el.textContent=today;
  showM('m-att-check');
}

function _getAttendanceEmployees(){
  return [...document.querySelectorAll('#employee-tbody tr:not([data-empty-state])')]
    .map(r=>employeeFromDirectoryRow(r))
    .filter(e=>e&&e.name&&e.name!=='Employee'&&(e.status||'Active').toLowerCase()==='active');
}

function markAllPresent(){
  const emps=_getAttendanceEmployees();
  _renderAttendanceRows(emps,[]);
}

// Wired to the "No — All Present" button, which previously just closed the
// modal with no save at all — the roll call table looked confirmed but no
// record of it existed anywhere once the modal closed.
async function confirmAllPresent(){
  closeM('m-att-check');
  const emps=_getAttendanceEmployees();
  await _saveManualAttendance(emps,[]);
  toast(`${emps.length} employee${emps.length===1?'':'s'} marked Present — attendance saved`,'ok');
}

function openAbsencePicker(){
  const emps=_getAttendanceEmployees();
  const list=document.getElementById('absence-picker-list');
  if(!list)return;
  if(!emps.length){
    list.innerHTML='<div style="color:var(--text3);text-align:center;padding:20px">No active employees found. Add employees first.</div>';
  } else {
    list.innerHTML=emps.map(e=>`
      <label style="display:flex;align-items:center;gap:10px;padding:8px 10px;border:1px solid var(--border);border-radius:7px;cursor:pointer;transition:background .12s" onmouseenter="this.style.background='var(--hover)'" onmouseleave="this.style.background=''">
        <input type="checkbox" data-emp="${escapeHtml(e.name)}" style="width:16px;height:16px;accent-color:var(--red)">
        <div class="co-av" style="width:28px;height:28px;font-size:10px;flex-shrink:0">${escapeHtml(initialsFromName(e.name))}</div>
        <div>
          <div style="font-weight:600;font-size:13px">${escapeHtml(e.name)}</div>
          <div style="font-size:11px;color:var(--text3)">${escapeHtml(e.department||'')}${e.designation?' · '+escapeHtml(e.designation):''}</div>
        </div>
      </label>`).join('');
  }
  showM('m-absence-picker');
}

async function confirmAbsences(){
  const emps=_getAttendanceEmployees();
  const absent=[...document.querySelectorAll('#absence-picker-list input[type=checkbox]:checked')]
    .map(cb=>cb.dataset.emp);
  closeM('m-absence-picker');
  // Re-render full table with absent set (all others stay Present)
  _renderAttendanceRows(emps,absent);
  await _saveManualAttendance(emps,absent);
  const presentCount=emps.length-absent.length;
  if(absent.length)
    toast(`${presentCount} Present · ${absent.length} Absent — attendance saved`,'ok');
  else
    toast(`All ${emps.length} employees marked Present`,'ok');
}

// Previously both callers showed an "attendance saved" toast with no
// saveServer()/moduleApi() call anywhere — the marked rows were DOM-only
// and vanished the next time refreshAttendanceToday() ran. Records one
// manual "in" punch per present employee (absent employees get no punch at
// all, matching how presence is already determined everywhere else in the
// app — no punch that day = absent); a failure for one employee is logged
// and skipped rather than aborting the rest of the roll call.
async function _saveManualAttendance(emps,absentNames){
  const absentSet=new Set((absentNames||[]).map(n=>n.toLowerCase()));
  const present=emps.filter(e=>!absentSet.has((e.name||'').toLowerCase()));
  for(const e of present){
    if(!e.id)continue;
    try{
      await authenticatedFetch(`${apiBaseUrl()}/attendance/punch`,{
        method:'POST',
        headers:{'Content-Type':'application/json'},
        body:JSON.stringify({employee_id:String(e.id),employee_name:e.name||'',direction:'in'}),
      });
    }catch(err){console.warn('[_saveManualAttendance] failed for',e.name,err);}
  }
  audit('Manual attendance roll call saved',`${present.length} present, ${absentSet.size} absent`,'Saved');
  if(typeof refreshAttendanceToday==='function')refreshAttendanceToday();
}

// Matches the 5 columns the #att-today-tbody header actually has
// (Employee/Check In/Check Out/Source/Status). Check Out is a permanent
// dash here — a manual present/absent roll call has no real check-out
// time (nor Hours/Late/OT, which is why those columns aren't shown at all).
function _renderAttendanceRows(emps,absentNames){
  const tbody=document.getElementById('att-today-tbody');
  if(!tbody)return;
  const now=new Date();
  const timeStr=now.toLocaleTimeString('en-AE',{hour:'2-digit',minute:'2-digit',hour12:true});
  const absentSet=new Set(absentNames.map(n=>n.toLowerCase()));
  if(!emps.length){
    tbody.innerHTML='<tr><td colspan="5" style="text-align:center;color:var(--text3);padding:24px">No active employees. Add employees to track attendance.</td></tr>';
    return;
  }
  tbody.innerHTML=emps.map(e=>{
    const isAbsent=absentSet.has(e.name.toLowerCase());
    const statusCls=isAbsent?'b-r':'b-g';
    const statusLabel=isAbsent?'Absent':'Present';
    const checkIn=isAbsent?'—':timeStr;
    return `<tr>
      <td><div style="display:flex;align-items:center;gap:8px">
        <div class="co-av" style="width:26px;height:26px;font-size:10px">${escapeHtml(initialsFromName(e.name))}</div>
        <div><div style="font-weight:600;font-size:12px">${escapeHtml(e.name)}</div><div style="font-size:10px;color:var(--text3)">${escapeHtml(e.department||'')}</div></div>
      </div></td>
      <td class="mono" style="font-size:12px">${checkIn}</td>
      <td class="mono" style="font-size:12px">—</td>
      <td><span class="b b-gray">Manual</span></td>
      <td><span class="b ${statusCls}">${statusLabel}</span></td>
    </tr>`;
  }).join('');
}

// Populated fresh by each renderAttendanceCalendar() call — see
// openAttendanceDayDetail()'s use of it below.
let _attCalLeaveNamesByDate={};

// Company-wide daily summary: Present (green) if anyone punched in that
// day, Absent (red) if a working day passed with zero punches at all, Leave
// (amber) — takes priority over both — if approved leave that day covers a
// disproportionate share of active headcount (>=20%, minimum 1 person, so
// it still means something for a small company). Only days up to today get
// a color at all; future days have no data yet and stay neutral, same as
// weekends (styled separately, never colored by this logic).
// Previously always hardcoded to the current month with no way to view
// any other one at all. Defaults to today's real month/year on first load.
let _attCalYear=null;
let _attCalMonth=null;
function attCalNav(dir){
  const now=new Date();
  if(_attCalYear===null){_attCalYear=now.getFullYear();_attCalMonth=now.getMonth();}
  _attCalMonth+=dir;
  if(_attCalMonth>11){_attCalMonth=0;_attCalYear++;}
  if(_attCalMonth<0){_attCalMonth=11;_attCalYear--;}
  renderAttendanceCalendar();
}

async function renderAttendanceCalendar(){
  const grid=document.getElementById('att-cal-grid');
  const title=document.getElementById('att-cal-title');
  if(!grid)return;
  const now=new Date();
  if(_attCalYear===null){_attCalYear=now.getFullYear();_attCalMonth=now.getMonth();}
  const year=_attCalYear;
  const month=_attCalMonth;
  const monthName=new Date(year,month,1).toLocaleString('en-AE',{month:'long'});
  if(title)title.textContent=`${monthName} ${year} — Attendance Calendar`;
  const firstDay=new Date(year,month,1).getDay();
  const daysInMonth=new Date(year,month+1,0).getDate();
  // The real "today" (day-of-month) only means something when the
  // calendar is actually showing the real current month — viewing a past
  // month should color every one of its days (they've all already
  // happened), and a future month should color none (nothing has
  // happened yet), not reuse today's day-of-month number from a
  // different month.
  const isCurrentMonth=year===now.getFullYear()&&month===now.getMonth();
  const isFutureMonth=year>now.getFullYear()||(year===now.getFullYear()&&month>now.getMonth());
  const today=isFutureMonth?0:(isCurrentMonth?now.getDate():daysInMonth);
  const monthStr=String(month+1).padStart(2,'0');
  const dayNames=[...grid.querySelectorAll('.cal-day-name')];
  grid.innerHTML='';
  dayNames.forEach(n=>grid.appendChild(n));
  for(let i=0;i<firstDay;i++){
    const blank=document.createElement('div');
    blank.className='cal-day wknd';
    grid.appendChild(blank);
  }

  const presentCountByDate={};
  const leaveCountByDate={};
  // Names (not just counts) per date, so clicking a day can show WHO was
  // on leave that day without a second round trip — see
  // openAttendanceDayDetail() below.
  _attCalLeaveNamesByDate={};
  try{
    // period= (added alongside the month-nav feature) returns exactly this
    // calendar month regardless of today's date — days=Math.max(7,today)
    // only ever worked for the current month (it's a rolling "last N days
    // ending today" window), which is why navigating to any other month
    // needed this in the first place.
    const trendRes=await authenticatedFetch(`${apiBaseUrl()}/attendance/trend?period=${year}-${monthStr}`);
    if(trendRes.ok){
      const trend=await trendRes.json();
      (trend.dates||[]).forEach((d,i)=>{presentCountByDate[d]=trend.counts?.[i]||0;});
    }
  }catch(e){console.warn('[renderAttendanceCalendar] trend fetch failed',e);}
  try{
    const leaveRes=await authenticatedFetch(`${apiBaseUrl()}/leave/requests`);
    if(leaveRes.ok){
      const requests=await leaveRes.json();
      requests.filter(r=>r.status==='approved').forEach(r=>{
        const start=new Date(r.start_date+'T00:00:00');
        const end=new Date(r.end_date+'T00:00:00');
        for(let d=new Date(start);d<=end;d.setDate(d.getDate()+1)){
          if(d.getFullYear()===year&&d.getMonth()===month){
            const key=`${year}-${monthStr}-${String(d.getDate()).padStart(2,'0')}`;
            leaveCountByDate[key]=(leaveCountByDate[key]||0)+1;
            (_attCalLeaveNamesByDate[key]=_attCalLeaveNamesByDate[key]||[]).push({name:r.employee_name,type:r.leave_type});
          }
        }
      });
    }
  }catch(e){console.warn('[renderAttendanceCalendar] leave fetch failed',e);}

  const headcount=document.querySelectorAll('#employee-tbody tr:not([data-empty-state])').length;
  const leaveThreshold=Math.max(1,Math.ceil(headcount*0.2));
  // See _companyWeekendDaySet() -- Sat/Sun by default, but configurable via
  // HR Settings > HR Rules > Weekend Policy so a company that actually runs
  // Sun-Thu (Fri/Sat off) doesn't get its real day off marked "Absent" and
  // its real working Sunday silently excluded from the calendar entirely.
  const weekendDays=_companyWeekendDaySet();

  for(let d=1;d<=daysInMonth;d++){
    const dayOfWeek=new Date(year,month,d).getDay();
    const isWknd=weekendDays?weekendDays.has(dayOfWeek):false;
    const div=document.createElement('div');
    const isRealToday=isCurrentMonth&&d===now.getDate();
    let cls='cal-day'+(isWknd?' wknd':isRealToday?' today':'');
    const key=`${year}-${monthStr}-${String(d).padStart(2,'0')}`;
    if(!isWknd&&d<=today){
      const leaveCount=leaveCountByDate[key]||0;
      const present=presentCountByDate[key]||0;
      if(leaveCount>=leaveThreshold)cls+=' leave';
      else if(present>0)cls+=' present';
      else cls+=' absent';
    }
    div.className=cls;
    div.textContent=d;
    // Previously no click handler at all on any day cell — selecting a
    // date loaded nothing. Every real day is clickable (including
    // weekends/future days); openAttendanceDayDetail() itself handles the
    // "nothing to show yet" case for a future date gracefully.
    div.style.cursor='pointer';
    div.onclick=()=>openAttendanceDayDetail(key);
    grid.appendChild(div);
  }
}

// Fired by clicking a calendar day — previously selecting a date did
// nothing at all. Fetches that specific day's punch-in roll call (the
// same data Today's Attendance shows, now widened via GET /attendance/
// today?date=... to accept any date) and combines it with the leave
// names already gathered by this same render pass, so the popup answers
// "who was actually present/absent/on leave" for the day clicked.
async function openAttendanceDayDetail(dateStr){
  const modalTitle=document.getElementById('att-day-modal-title');
  const body=document.getElementById('att-day-modal-body');
  if(!body)return;
  const niceDate=new Date(`${dateStr}T00:00:00`).toLocaleDateString('en-AE',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
  if(modalTitle)modalTitle.textContent=niceDate;
  body.innerHTML='<div style="text-align:center;color:var(--text3);padding:20px">Loading…</div>';
  showM('m-att-day');
  const leaveList=_attCalLeaveNamesByDate[dateStr]||[];
  const leaveNames=new Set(leaveList.map(l=>l.name));
  try{
    const res=await authenticatedFetch(`${apiBaseUrl()}/attendance/today?date=${encodeURIComponent(dateStr)}`);
    const data=res.ok?await res.json():{employees:[]};
    const present=Array.isArray(data.employees)?data.employees:[];
    const totalActive=_getAttendanceEmployees().length;
    // Rota days off aren't absences (skip anyone already listed as on leave).
    const offList=(Array.isArray(data.off)?data.off:[]).filter(o=>!leaveNames.has(o.employee_name));
    const absentCount=Math.max(0,totalActive-present.length-leaveList.length-offList.length);
    const section=(label,cls,rows)=>rows.length?`<div style="margin-bottom:10px">
      <div style="font-size:11px;font-weight:700;color:var(--text3);text-transform:uppercase;letter-spacing:.04em;margin-bottom:4px">${escapeHtml(label)} (${rows.length})</div>
      ${rows.map(r=>`<div style="display:flex;justify-content:space-between;padding:4px 0;font-size:12.5px;border-bottom:1px solid var(--border2)"><span>${escapeHtml(r.name)}</span><span class="b ${cls}" style="font-size:10px">${escapeHtml(r.detail)}</span></div>`).join('')}
    </div>`:'';
    body.innerHTML=`
      <div class="flx" style="gap:16px;margin-bottom:12px">
        <div><div style="font-size:20px;font-weight:700;color:var(--green)">${present.length}</div><div style="font-size:11px;color:var(--text3)">Present</div></div>
        <div><div style="font-size:20px;font-weight:700;color:var(--amber)">${leaveList.length}</div><div style="font-size:11px;color:var(--text3)">On Leave</div></div>
        <div><div style="font-size:20px;font-weight:700;color:var(--text2)">${offList.length}</div><div style="font-size:11px;color:var(--text3)">Day Off</div></div>
        <div><div style="font-size:20px;font-weight:700;color:var(--red)">${absentCount}</div><div style="font-size:11px;color:var(--text3)">Absent</div></div>
      </div>
      ${section('Present',present.length?'b-g':'',present.map(e=>({name:e.employee_name||e.employee_id,detail:e.check_out_time?`${e.check_in_time||'—'} → ${e.check_out_time}`:(e.check_in_time||'—')})))}
      ${section('On Leave','b-a',leaveList.map(l=>({name:l.name,detail:l.type||'Leave'})))}
      ${section('Day Off','',offList.map(o=>({name:o.employee_name||o.employee_id,detail:o.kind==='leave'?'Leave (rota)':o.kind==='holiday'?'Holiday (rota)':'Off (rota)'})))}
      ${(!present.length&&!leaveList.length&&!offList.length)?'<div style="text-align:center;color:var(--text3);padding:16px 0">No punches or leave recorded for this day.</div>':''}
    `;
  }catch(e){
    body.innerHTML='<div style="text-align:center;color:var(--red);padding:20px">Could not load this day\'s attendance.</div>';
  }
}

// ── HR Reports: Attendance Report ───────────────────────────────────────
// "Reports & Analytics" in the sidebar previously just opened the Payroll
// page — no reports screen existed anywhere in HRMS. Backed by GET
// /attendance/monthly-report (present/absent/leave days + hours per
// employee for a selected month, respecting the same weekend policy as
// the Attendance Calendar — see _companyWeekendDaySet()).
let _hrAttReportCache=null;
// Sort state for the Present/Absent columns — {key:'present_days'|'absent_days'|null, dir:1|-1}.
// Descending by default on first click of a column: for both Present and
// Absent, the numbers people actually want to see first are the extremes
// (most absences to chase up, most present to recognize), not the zeros.
let _hrAttSort={key:null,dir:-1};

function loadHrAttendanceReport(){
  const periodInput=document.getElementById('hrr-att-period');
  if(periodInput&&!periodInput.value){
    const now=new Date();
    periodInput.value=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`;
  }
  const period=periodInput?.value||'';
  _hrAttSort={key:null,dir:-1};
  const tbody=document.getElementById('hrr-att-tbody');
  if(tbody)tbody.innerHTML='<tr><td colspan="7" style="color:var(--text3);text-align:center;padding:24px">Loading…</td></tr>';
  authenticatedFetch(`${apiBaseUrl()}/attendance/monthly-report${period?`?period=${encodeURIComponent(period)}`:''}`)
    .then(r=>r.ok?r.json():Promise.reject(new Error('Report API returned '+r.status)))
    .then(data=>{
      _hrAttReportCache=data;
      const sub=document.getElementById('hrr-att-sub');
      if(sub)sub.textContent=`${data.working_days} working day(s) this period — per-employee present/absent/leave days and hours`;
      _renderHrAttReportRows();
    })
    .catch(e=>{
      console.warn('[loadHrAttendanceReport]',e);
      if(tbody)tbody.innerHTML='<tr><td colspan="7" style="color:var(--red);text-align:center;padding:24px">Could not load attendance report.</td></tr>';
    });
}

// Clicking the Present/Absent header sorts by that column, toggling
// direction on repeat clicks of the same column; picking the other column
// resets to descending. Purely a client-side re-sort of the already-loaded
// report — no re-fetch needed.
function sortHrAttendanceReport(key){
  _hrAttSort=_hrAttSort.key===key?{key,dir:-_hrAttSort.dir}:{key,dir:-1};
  _renderHrAttReportRows();
}

function _renderHrAttReportRows(){
  const tbody=document.getElementById('hrr-att-tbody');
  if(!tbody)return;
  let rows=[...(_hrAttReportCache?.employees||[])];
  const {key,dir}=_hrAttSort;
  if(key)rows.sort((a,b)=>(Number(a[key])-Number(b[key]))*dir||(a.employee_name||'').localeCompare(b.employee_name||''));
  const arrow=k=>key===k?(dir===1?' ▲':' ▼'):'';
  document.querySelectorAll('#hrr-att-thead-present').forEach(th=>{th.textContent='Present'+arrow('present_days');});
  document.querySelectorAll('#hrr-att-thead-absent').forEach(th=>{th.textContent='Absent'+arrow('absent_days');});
  tbody.innerHTML=rows.length?rows.map(e=>`<tr>
    <td style="font-weight:600;color:var(--accent);cursor:pointer" onclick="openEmployeeAttendanceDetail('${escapeHtml(e.employee_id)}','${escapeHtml(e.employee_name||'')}')" title="View day-by-day attendance">${escapeHtml(e.employee_name||'—')}</td>
    <td style="color:var(--text3);font-size:12px">${escapeHtml(e.department||'—')}</td>
    <td class="mono">${e.present_days}</td>
    <td class="mono"${e.absent_days>0?' style="color:var(--red)"':''}>${e.absent_days}</td>
    <td class="mono">${e.leave_days}</td>
    <td class="mono" style="color:var(--text3)">${e.off_days??0}</td>
    <td class="mono">${e.total_hours}</td>
    <td class="mono">${e.ot_hours}</td>
  </tr>`).join(''):'<tr><td colspan="8" style="color:var(--text3);text-align:center;padding:24px">No active employees.</td></tr>';
}

function downloadHrAttendanceReportCsv(){
  const data=_hrAttReportCache;
  if(!data||!(data.employees||[]).length){toast('No report data to export — load the report first','warn');return;}
  const escape=v=>{const s=String(v??'');return s.includes(',')||s.includes('"')||s.includes('\n')?`"${s.replace(/"/g,'""')}"`:s;};
  const headers=['Employee','Department','Present Days','Absent Days','Leave Days','Days Off (rota)','Total Hours','OT Hours'];
  const rows=data.employees.map(e=>[e.employee_name,e.department,e.present_days,e.absent_days,e.leave_days,e.off_days??0,e.total_hours,e.ot_hours]);
  const companyName=document.getElementById('sb-company-name')?.textContent||'TaxFlow HRMS';
  const csv=[
    `${companyName} — Attendance Report`,
    `Period: ${data.period} · Working Days: ${data.working_days}`,
    `Generated: ${new Date().toLocaleDateString('en-GB')}`,
    '',
    headers.map(escape).join(','),
    ...rows.map(r=>r.map(escape).join(',')),
  ].join('\r\n');
  const blob=new Blob(['﻿'+csv],{type:'text/csv;charset=utf-8'});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');
  a.href=url;a.download=`Attendance_Report_${data.period}.csv`;a.click();
  setTimeout(()=>URL.revokeObjectURL(url),2000);
}

let _hrLateReportCache=null;
let _hrLateSort={key:null,dir:-1};

function loadHrLateReport(){
  const periodInput=document.getElementById('hrr-late-period');
  if(periodInput&&!periodInput.value){
    const now=new Date();
    periodInput.value=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`;
  }
  const period=periodInput?.value||'';
  _hrLateSort={key:null,dir:-1};
  const tbody=document.getElementById('hrr-late-tbody');
  if(tbody)tbody.innerHTML='<tr><td colspan="5" style="color:var(--text3);text-align:center;padding:24px">Loading…</td></tr>';
  authenticatedFetch(`${apiBaseUrl()}/attendance/late-report${period?`?period=${encodeURIComponent(period)}`:''}`)
    .then(r=>r.ok?r.json():Promise.reject(new Error('Report API returned '+r.status)))
    .then(data=>{
      _hrLateReportCache=data;
      const sub=document.getElementById('hrr-late-sub');
      if(sub)sub.textContent=`Standard start ${data.standard_start_time}${data.grace_minutes?` (+${data.grace_minutes} min grace)`:''} — employees whose first check-in landed after that`;
      // The report response is the source of truth for the configured
      // rule -- keep the two inputs in sync with it rather than whatever
      // was last typed (also how a fresh page load picks up what's saved).
      const startEl=document.getElementById('late-start-time');
      if(startEl)startEl.value=data.standard_start_time||'09:00';
      const graceEl=document.getElementById('late-grace-minutes');
      if(graceEl)graceEl.value=data.grace_minutes??0;
      _renderHrLateReportRows();
    })
    .catch(e=>{
      console.warn('[loadHrLateReport]',e);
      if(tbody)tbody.innerHTML='<tr><td colspan="5" style="color:var(--red);text-align:center;padding:24px">Could not load late coming report.</td></tr>';
    });
}

function sortHrLateReport(key){
  _hrLateSort=_hrLateSort.key===key?{key,dir:-_hrLateSort.dir}:{key,dir:-1};
  _renderHrLateReportRows();
}

function _renderHrLateReportRows(){
  const tbody=document.getElementById('hrr-late-tbody');
  if(!tbody)return;
  let rows=[...(_hrLateReportCache?.employees||[])];
  const {key,dir}=_hrLateSort;
  if(key)rows.sort((a,b)=>(Number(a[key])-Number(b[key]))*dir||(a.employee_name||'').localeCompare(b.employee_name||''));
  const arrow=k=>key===k?(dir===1?' ▲':' ▼'):'';
  document.querySelectorAll('#hrr-late-thead-days').forEach(th=>{th.textContent='Late Days'+arrow('late_days');});
  document.querySelectorAll('#hrr-late-thead-total').forEach(th=>{th.textContent='Total Late'+arrow('total_late_seconds');});
  tbody.innerHTML=rows.length?rows.map(e=>`<tr>
    <td style="font-weight:600;color:var(--accent);cursor:pointer" onclick="openEmployeeAttendanceDetail('${escapeHtml(e.employee_id)}','${escapeHtml(e.employee_name||'')}','${escapeHtml(_hrLateReportCache?.period||'')}')" title="View day-by-day attendance">${escapeHtml(e.employee_name||'—')}</td>
    <td style="color:var(--text3);font-size:12px">${escapeHtml(e.department||'—')}</td>
    <td class="mono"${e.late_days>0?' style="color:var(--red)"':''}>${e.late_days}</td>
    <td class="mono">${e.late_days>0?escapeHtml(e.total_late):'—'}</td>
    <td class="mono" style="font-size:12px">${escapeHtml(e.last_late_date||'—')}</td>
  </tr>`).join(''):'<tr><td colspan="5" style="color:var(--text3);text-align:center;padding:24px">No active employees.</td></tr>';
}

function saveLateRulesConfig(){
  const startTime=document.getElementById('late-start-time')?.value||'09:00';
  const graceMinutes=Math.max(0,parseInt(document.getElementById('late-grace-minutes')?.value,10)||0);
  saveServer('hr_settings',{id:'late-rules-config',startTime,graceMinutes},{throwOnError:true})
    .then(()=>{toast('Late coming rule saved','ok');loadHrLateReport();})
    .catch(()=>toast('Could not save — cannot reach server','err'));
}

function downloadHrLateReportCsv(){
  const data=_hrLateReportCache;
  if(!data||!(data.employees||[]).length){toast('No report data to export — load the report first','warn');return;}
  const escape=v=>{const s=String(v??'');return s.includes(',')||s.includes('"')||s.includes('\n')?`"${s.replace(/"/g,'""')}"`:s;};
  const headers=['Employee','Department','Late Days','Total Late','Last Late Date'];
  const rows=data.employees.map(e=>[e.employee_name,e.department,e.late_days,e.total_late,e.last_late_date||'']);
  const companyName=document.getElementById('sb-company-name')?.textContent||'TaxFlow HRMS';
  const csv=[
    `${companyName} — Late Coming Report`,
    `Period: ${data.period} · Standard Start: ${data.standard_start_time} · Grace: ${data.grace_minutes} min`,
    `Generated: ${new Date().toLocaleDateString('en-GB')}`,
    '',
    headers.map(escape).join(','),
    ...rows.map(r=>r.map(escape).join(',')),
  ].join('\r\n');
  const blob=new Blob(['﻿'+csv],{type:'text/csv;charset=utf-8'});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');
  a.href=url;a.download=`Late_Coming_Report_${data.period}.csv`;a.click();
  setTimeout(()=>URL.revokeObjectURL(url),2000);
}

// Clicking an employee's name in the Attendance Report previously did
// nothing — this opens a day-by-day drill-down for that employee, backed
// by GET /attendance/employee-daily, with its own month picker (defaults
// to whatever month the report itself was showing).
let _empAttDetailId=null;
let _empAttDetailName='';
function openEmployeeAttendanceDetail(employeeId,employeeName,period){
  _empAttDetailId=employeeId;
  _empAttDetailName=employeeName||'';
  document.getElementById('emp-att-detail-title').textContent=employeeName||'Attendance';
  const periodInput=document.getElementById('emp-att-detail-period');
  if(periodInput)periodInput.value=period||document.getElementById('hrr-att-period')?.value||_hrAttReportCache?.period||'';
  showM('m-emp-att-detail');
  loadEmployeeAttendanceDetail();
}

// Row cells mirror daily_attendance_report.py's own column set exactly
// (Emp No./AC-No./Day/Name/Date/up to 3 Clock In-Out-Work Time triples/
// Total/OT/Under Time/Absent/SICK/Holiday) so the on-screen popup and
// that downloadable report agree on what a day looks like.
function _empAttDetailRowHtml(d){
  const sessions=d.sessions||[];
  // A blank Clock Out means two different things depending on the day: for
  // TODAY it can just mean "hasn't left yet" (still possibly coming), but
  // for a day that's already over it means no checkout was ever recorded --
  // e.g. an entry-only device (a dwell/proximity sensor, a simple turnstile)
  // that structurally never sends an "out" signal. Previously both looked
  // identical (a bare "—"), which read as a bug on every single past day
  // for anyone tracked by that kind of device.
  const sessionCells=sessions.map(s=>{
    const clockOutCell=s.clock_out?escapeHtml(s.clock_out):(s.clock_in&&!d.is_today?'<span style="color:var(--text3);font-style:italic">No checkout</span>':'—');
    return `<td>${s.clock_in?escapeHtml(s.clock_in):'—'}</td><td>${clockOutCell}</td><td>${s.work_time?escapeHtml(s.work_time):'—'}</td>`;
  }).join('');
  const rowStyle=d.status==='weekend'||d.status==='upcoming'||d.status==='off'?' style="color:var(--text3)"':d.status==='absent'?' style="color:var(--red)"':'';
  return `<tr${rowStyle}>
    <td>${escapeHtml(d.emp_no||'')}</td>
    <td>${escapeHtml(d.ac_no||'')}</td>
    <td>${escapeHtml(d.day_name)}</td>
    <td>${escapeHtml(_empAttDetailName)}</td>
    <td>${escapeHtml(d.date)}</td>
    ${sessionCells}
    <td>${d.total_hours&&d.total_hours!=='0:00'?escapeHtml(d.total_hours):'—'}</td>
    <td>${d.ot_hours&&d.ot_hours!=='0:00'?escapeHtml(d.ot_hours):'—'}</td>
    <td>${d.under_hours&&d.under_hours!=='0:00'?escapeHtml(d.under_hours):'—'}</td>
    <td>${d.status==='off'?'<span style="font-style:italic">Day off</span>':escapeHtml(d.absent||'')}</td>
    <td>${escapeHtml(d.sick||'')}</td>
    <td>${escapeHtml(d.holiday||'')}</td>
  </tr>`;
}

async function loadEmployeeAttendanceDetail(){
  const tbody=document.getElementById('emp-att-detail-tbody');
  if(!_empAttDetailId||!tbody)return;
  const period=document.getElementById('emp-att-detail-period')?.value||'';
  tbody.innerHTML='<tr><td colspan="20" style="color:var(--text3);text-align:center;padding:20px">Loading…</td></tr>';
  try{
    const r=await authenticatedFetch(`${apiBaseUrl()}/attendance/employee-daily?employee_id=${encodeURIComponent(_empAttDetailId)}${period?`&period=${encodeURIComponent(period)}`:''}`);
    if(!r.ok)throw new Error('Request failed ('+r.status+')');
    const data=await r.json();
    const sub=document.getElementById('emp-att-detail-sub');
    if(sub)sub.textContent=`${data.department||''} — ${data.period}`;
    const days=data.days||[];
    tbody.innerHTML=days.length?days.map(_empAttDetailRowHtml).join(''):'<tr><td colspan="20" style="color:var(--text3);text-align:center;padding:20px">No data for this month.</td></tr>';
  }catch(e){
    console.warn('[loadEmployeeAttendanceDetail]',e);
    tbody.innerHTML='<tr><td colspan="20" style="color:var(--red);text-align:center;padding:20px">Could not load attendance for this employee.</td></tr>';
  }
}

// Fixed palette (not a free color picker) so task colors stay visually
// distinct and consistent everywhere a task shows up in miniature (the
// Rota cell badge, the Edit Shift modal's attached-tasks list) — a raw
// <input type="color"> would let two tasks land on near-identical shades
// that are indistinguishable at dot size.
const TASK_COLORS=['#3b82f6','#8b5cf6','#f59e0b','#10b981','#ef4444','#06b6d4','#ec4899','#f97316'];

function renderTaskColorPicker(selected){
  const wrap=document.getElementById('task-color-picker');
  if(!wrap)return;
  const current=selected||TASK_COLORS[0];
  document.getElementById('task-color').value=current;
  wrap.innerHTML=TASK_COLORS.map(c=>`<button type="button" title="${escapeHtml(c)}" onclick="selectTaskColor('${escapeHtml(c)}')" style="width:26px;height:26px;border-radius:50%;background:${escapeHtml(c)};cursor:pointer;border:2px solid ${c===current?'var(--text)':'transparent'};box-shadow:0 0 0 1px var(--border);padding:0"></button>`).join('');
}

function selectTaskColor(color){
  document.getElementById('task-color').value=color;
  renderTaskColorPicker(color);
}

// ── Task Management ─────────────────────────────────────────────────────
// Backed by the generic AppDataRecord 'tasks' collection (same pattern as
// employeeLoans/jobRequisitions — a small admin-managed list, not a
// per-employee ledger needing its own dedicated table). Flat Table view
// only (the Kanban board view was removed by request); status is changed
// via the Edit modal's Status field. Admin/manager-only for now (no
// ESS-side view yet).
let _taskListCache=[];
const TASK_STATUSES=['todo','progress','done'];
const TASK_STATUS_LABEL={todo:'To Do',progress:'Progress',in_progress:'Progress',done:'Done'};
// 'in_progress' was this status's key before the column was briefly
// removed and re-added as 'progress' — bucketed here so a task saved
// under the old key still lands in the right column instead of falling
// through to To Do.
function _normalizeTaskStatus(status){
  if(status==='in_progress')return 'progress';
  return TASK_STATUSES.includes(status)?status:'todo';
}
const TASK_REPEAT_LABEL={none:'—',daily:'Daily',weekly:'Weekly',monthly:'Monthly'};

// Local (not UTC) YYYY-MM-DD — toISOString() is still "yesterday" until 04:00 in UAE.
function _taskLocalToday(){
  const d=new Date();
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
}

async function _fetchTaskRecords(){
  const r=await authenticatedFetch(`${apiBaseUrl()}/app-data/records/tasks?limit=500`);
  if(!r.ok)throw new Error(`Could not load tasks (${r.status})`);
  const data=await r.json();
  return Array.isArray(data?.records)?data.records:[];
}

async function loadTasks(){
  await populateTaskAssigneeSelect();
  try{
    _taskListCache=await _fetchTaskRecords();
  }catch(e){
    console.warn('[loadTasks]',e);
    _taskListCache=[];
  }
  await _processRepeatingTasks();
  renderTaskBoard();
}

// Checked once per page visit (this feature is Tier 2/JSON-backed, not
// worth a dedicated backend scheduler yet — see docs/hrms-architecture.md
// §6). For any repeating task whose due date has already passed and that
// hasn't spawned its next occurrence yet, creates ONE fresh copy (status
// To Do, progress 0) due on the first occurrence on/after today — missed
// occurrences are skipped, not back-filled — and flags the original with
// next_spawned. The copy's id is derived from the series + due date, so two
// managers opening the page at once upsert the same record, not two.
// Unassigned templates never spawn. The original is left as it was.
function _nextRepeatDueDate(dueDate,repeat){
  const d=new Date(`${dueDate}T00:00:00`);
  if(repeat==='daily'){
    d.setDate(d.getDate()+1);
  }else if(repeat==='weekly'){
    d.setDate(d.getDate()+7);
  }else if(repeat==='monthly'){
    // A bare setMonth(+1) on e.g. 31 Jan overflows into "31 Feb", which
    // JS Date silently rolls forward into 3 Mar instead of clamping —
    // anchor to day 1 first, then clamp back to the target month's own
    // last day so a month-end repeating task always lands on THAT
    // month's end, not several days into the next one.
    const day=d.getDate();
    d.setDate(1);
    d.setMonth(d.getMonth()+1);
    const lastDay=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();
    d.setDate(Math.min(day,lastDay));
  }else{
    return null;
  }
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
}
async function _processRepeatingTasks(){
  const todayStr=_taskLocalToday();
  const due=_taskListCache.filter(t=>t.assigned_to&&t.repeat&&t.repeat!=='none'&&t.due_date&&t.due_date<todayStr&&!t.next_spawned);
  for(const t of due){
    let nextDue=_nextRepeatDueDate(t.due_date,t.repeat);
    while(nextDue&&nextDue<todayStr)nextDue=_nextRepeatDueDate(nextDue,t.repeat);
    if(!nextDue)continue;
    const seriesId=t.series_id||t.id;
    const cloneId=`${seriesId}-${nextDue}`;
    try{
      if(!_taskListCache.some(x=>x.id===cloneId)){
        const clone={
          ...t,id:cloneId,series_id:seriesId,
          due_date:nextDue,status:'todo',progress:0,next_spawned:false,created_at:new Date().toISOString(),
        };
        await saveServer('tasks',clone,{throwOnError:true});
        _taskListCache.push(clone);
      }
      await saveServer('tasks',{...t,next_spawned:true},{throwOnError:true});
      t.next_spawned=true;
    }catch(e){
      console.warn('[processRepeatingTasks]',e);
    }
  }
}

// Shared across the page's Assigned To filter and the To Do column's
// per-employee assign panel -- one fetch, two consumers, always
// active-only (see GET /payroll/employees' own fix). The Add/Edit Task
// modal no longer has its own assignee select (removed 2026-09-22); this
// still runs harmlessly since modalSel below is simply never found.
let _taskEmployeeListCache=[];

async function populateTaskAssigneeSelect(){
  const modalSel=document.getElementById('task-assignee');
  const filterSel=document.getElementById('task-filter-employee');
  try{
    const r=await authenticatedFetch(`${apiBaseUrl()}/payroll/employees`);
    _taskEmployeeListCache=r.ok?await r.json():[];
  }catch(e){
    _taskEmployeeListCache=[];
  }
  const employees=_taskEmployeeListCache;
  if(modalSel){
    const prev=modalSel.value;
    modalSel.innerHTML='<option value="">— Unassigned —</option>'+
      employees.map(e=>`<option value="${escapeHtml(e.id)}" data-name="${escapeHtml(e.full_name)}">${escapeHtml(e.full_name)} (${escapeHtml(e.employee_no)})</option>`).join('');
    if(prev)modalSel.value=prev;
  }
  if(filterSel){
    const prev=filterSel.value;
    filterSel.innerHTML='<option value="">All Employees</option>'+
      employees.map(e=>`<option value="${escapeHtml(e.id)}">${escapeHtml(e.full_name)}</option>`).join('');
    if(prev)filterSel.value=prev;
  }
}

// Unique task NAMES seen so far (most-recently-used instance per name) —
// shared by the modal's "Load From Previous Task" dropdown and the To Do
// column's per-employee assign picker below.
function _uniqueTaskTemplates(){
  const seen=new Set();
  const opts=[];
  [..._taskListCache].reverse().forEach(t=>{
    if(!t.title||seen.has(t.title))return;
    seen.add(t.title);
    opts.push(t);
  });
  return opts;
}

// "+ Assign Task" button/modal: pick one or more employees, pick a saved
// task name, Assign — this is the main way a previously-unassigned SAVED
// task (a reusable template) gets handed to someone (Add Task also
// collects an assignee directly now, but this modal is still how you
// assign an existing template later, and now to several people at once
// in one action rather than repeating the whole flow per person).
function showAssignTaskModal(){
  const grid=document.getElementById('assign-task-employee-grid');
  const taskSel=document.getElementById('assign-task-template');
  const searchEl=document.getElementById('assign-task-employee-search');
  if(searchEl)searchEl.value='';
  if(grid){
    grid.innerHTML=_taskEmployeeListCache.length
      ?_taskEmployeeListCache.map(e=>`<label data-emp-label style="display:flex;align-items:center;gap:8px;font-size:13px;cursor:pointer"><input type="checkbox" class="assign-task-employee-cb" value="${escapeHtml(e.id)}" data-name="${escapeHtml(e.full_name)}"> ${escapeHtml(e.full_name)}</label>`).join('')
      :'<div style="color:var(--text3);font-size:12px;grid-column:1/-1">No employees found.</div>';
  }
  const templates=_uniqueTaskTemplates();
  if(taskSel){
    taskSel.innerHTML=templates.length
      ?'<option value="">— Select Task —</option>'+templates.map(t=>`<option value="${escapeHtml(t.id)}">${escapeHtml(t.title)}</option>`).join('')
      :'<option value="">No saved tasks yet — click + Add Task first</option>';
  }
  showM('m-assign-task');
}

// Filters the Assign Task employee checkbox grid as you type -- purely a
// display:none toggle on each <label>, so a checked box stays checked
// (and still counts in confirmAssignTask()) even while its label is
// hidden by a search that no longer matches it.
function filterAssignTaskEmployees(){
  const query=(document.getElementById('assign-task-employee-search')?.value||'').trim().toLowerCase();
  document.querySelectorAll('#assign-task-employee-grid [data-emp-label]').forEach(label=>{
    const name=(label.querySelector('input')?.dataset.name||label.textContent||'').toLowerCase();
    label.style.display=!query||name.includes(query)?'':'none';
  });
}

async function confirmAssignTask(){
  const checked=[...document.querySelectorAll('#assign-task-employee-grid .assign-task-employee-cb:checked')];
  const taskSel=document.getElementById('assign-task-template');
  const templateId=taskSel?.value;
  if(!checked.length){toast('Select at least one employee','warn');return;}
  if(!templateId){toast('Select a task','warn');return;}
  const source=_taskListCache.find(x=>x.id===templateId);
  if(!source)return;
  const assignedNames=[];
  const failedNames=[];
  for(const cb of checked){
    const employeeId=cb.value;
    const employeeName=cb.dataset.name||'';
    try{
      const task=await _ensureTaskAssignedToEmployee(templateId,employeeId,employeeName);
      if(task)assignedNames.push(employeeName);
    }catch(e){
      failedNames.push(employeeName);
    }
  }
  if(!assignedNames.length){
    toast(`Could not assign "${source.title}" — please try again`,'err');
    return;
  }
  hideM('m-assign-task');
  // Same reasoning as saveTaskModal() -- a stale "Assigned To: <someone
  // else>" filter would hide these brand-new assignments from the table
  // immediately after creating them (only meaningful for a single pick;
  // left alone for multiple since no one filter value could match all).
  const empFilter=document.getElementById('task-filter-employee');
  if(checked.length===1&&empFilter&&empFilter.value&&empFilter.value!==checked[0].value)empFilter.value='';
  renderTaskBoard();
  toast(`"${source.title}" assigned to ${assignedNames.length} employee${assignedNames.length===1?'':'s'}: ${assignedNames.join(', ')}`,'ok');
  if(failedNames.length)toast(`Could not assign to: ${failedNames.join(', ')}`,'err');
}

// Shared by confirmAssignTask() (Task Management's "+ Assign Task",
// possibly several employees at once) and Rota's "+ Add Task" picker (see
// _rotaEditTaskOptionsHtml, which lists every saved task -- assigned or
// not -- so a manager can assign-and-schedule in one step instead of
// visiting Task Management first). Picking a template not already
// assigned to this employee clones it into a real assignment; an OPEN one
// (same title, same employee, not Done) is reused instead so the same
// assignment never duplicates — a Done one gets a fresh instance.
// Throws if the save fails.
async function _ensureTaskAssignedToEmployee(templateId,employeeId,employeeName){
  const source=_taskListCache.find(x=>x.id===templateId);
  if(!source)return null;
  const isOpen=t=>_normalizeTaskStatus(t.status)!=='done';
  if(source.assigned_to===employeeId&&isOpen(source))return source;
  const existing=_taskListCache.find(t=>t.assigned_to===employeeId&&t.title===source.title&&isOpen(t));
  if(existing)return existing;
  const task={
    id:`TASK-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,
    title:source.title,
    department:source.department||'',
    description:source.description||'',
    assigned_to:employeeId,
    assigned_to_name:employeeName,
    color:source.color||TASK_COLORS[0],
    priority:source.priority||'Medium',
    due_date:'',
    status:'todo',
    progress:0,
    repeat:source.repeat||'none',
    next_spawned:false,
    created_at:new Date().toISOString(),
  };
  await saveServer('tasks',task,{throwOnError:true});
  _taskListCache.push(task);
  return task;
}

function showTaskModal(id){
  const t=id?_taskListCache.find(x=>x.id===id):null;
  document.getElementById('task-modal-title').textContent=t?'Edit Task':'Add Task';
  document.getElementById('task-edit-id').value=id||'';
  document.getElementById('task-title').value=t?.title||'';
  document.getElementById('task-department').value=t?.department||'';
  document.getElementById('task-description').value=t?.description||'';
  document.getElementById('task-priority').value=t?.priority||'Medium';
  document.getElementById('task-due-date').value=t?.due_date||'';
  document.getElementById('task-status').value=t?_normalizeTaskStatus(t.status):'todo';
  document.getElementById('task-repeat').value=t?.repeat||'none';
  renderTaskColorPicker(t?.color);
  const progressVal=t?.status==='done'?100:(t?.progress||0);
  document.getElementById('task-progress').value=progressVal;
  document.getElementById('task-progress-value').textContent=progressVal;
  const delBtn=document.getElementById('task-delete-btn');
  if(delBtn)delBtn.style.display=t?'':'none';
  _taskModalOriginal=t?_readTaskModalFields():null;
  showM('m-task');
  setTimeout(()=>document.getElementById('task-title').focus(),120);
}

// Field values as the Edit modal opened them — saveTaskModal() only writes the
// fields the user actually changed, so an employee's ESS status update made
// while the modal (or the page) was open isn't overwritten by a stale copy.
let _taskModalOriginal=null;
const _TASK_MODAL_FIELDS=['title','department','description','color','priority','due_date','status','progress','repeat'];

function _readTaskModalFields(){
  return {
    title:(document.getElementById('task-title')?.value||'').trim(),
    department:document.getElementById('task-department')?.value||'',
    description:(document.getElementById('task-description')?.value||'').trim(),
    color:document.getElementById('task-color')?.value||TASK_COLORS[0],
    priority:document.getElementById('task-priority')?.value||'Medium',
    due_date:document.getElementById('task-due-date')?.value||'',
    status:document.getElementById('task-status')?.value||'todo',
    progress:Number(document.getElementById('task-progress')?.value||0),
    repeat:document.getElementById('task-repeat')?.value||'none',
  };
}

async function saveTaskModal(){
  const form=_readTaskModalFields();
  if(!form.title){toast('Task name is required','warn');return;}
  const id=document.getElementById('task-edit-id')?.value||`TASK-${Date.now()}`;
  let existing=_taskListCache.find(x=>x.id===id);
  if(existing){
    try{
      _taskListCache=await _fetchTaskRecords();
    }catch(e){
      toast('Could not save task — please check your connection and try again','err');
      return;
    }
    existing=_taskListCache.find(x=>x.id===id);
    if(!existing){
      hideM('m-task');
      renderTaskBoard();
      toast('This task was deleted by someone else','warn');
      return;
    }
    const orig=_taskModalOriginal||form;
    const latest={
      ...existing,
      status:_normalizeTaskStatus(existing.status),
      progress:existing.status==='done'?100:Number(existing.progress||0),
    };
    _TASK_MODAL_FIELDS.forEach(f=>{
      if(form[f]===orig[f])form[f]=latest[f]??form[f];
    });
  }
  const task={
    id,
    title:form.title,
    department:form.department,
    description:form.description,
    // "Assign To" was removed from this modal (2026-09-22) -- assigning is done from
    // the page's "+ Assign Task" panel / Assigned To filter, or the Rota cell editor.
    // A save here must never touch whatever assignment those already set: an edit
    // keeps it exactly as it was, and a brand-new task stays unassigned like before
    // this field ever existed.
    assigned_to:existing?.assigned_to||'',
    assigned_to_name:existing?.assigned_to_name||'',
    color:form.color,
    priority:form.priority,
    due_date:form.due_date,
    status:form.status,
    // Done always reads back as 100% regardless of what the slider was
    // left at — a finished task is fully done by definition.
    progress:form.status==='done'?100:form.progress,
    repeat:form.repeat,
    // Editing an existing task's own due date forward re-arms its repeat
    // (it's no longer "already spawned" for its new date); a brand-new
    // task obviously hasn't spawned anything yet either.
    next_spawned:existing&&existing.due_date===form.due_date?(existing.next_spawned||false):false,
    created_at:existing?.created_at||new Date().toISOString(),
  };
  // Carry over fields this modal doesn't edit (series_id, ESS-side fields...).
  if(existing)Object.keys(existing).forEach(k=>{if(!(k in task))task[k]=existing[k];});
  try{
    await saveServer('tasks',task,{throwOnError:true});
  }catch(e){
    toast(`Could not save task: ${e.serverDetail||e.message}`,'err');
    return;
  }
  const idx=_taskListCache.findIndex(x=>x.id===id);
  if(idx>=0)_taskListCache[idx]=task;else _taskListCache.push(task);
  hideM('m-task');
  if(!existing){
    // A brand-new task is unassigned/undated by default -- if the table
    // was left filtered from an earlier look-up (e.g. "Assigned To: <someone>"
    // still selected), the task saves correctly but never appears in the
    // filtered view, with nothing on screen to click Edit on -- looking
    // exactly like the save silently failed. Clearing the filters
    // guarantees whatever was just added is immediately visible.
    const deptFilter=document.getElementById('task-department-filter');
    const empFilter=document.getElementById('task-filter-employee');
    const priorityFilter=document.getElementById('task-filter-priority');
    const searchFilter=document.getElementById('task-filter-search');
    if(deptFilter)deptFilter.value='';
    if(empFilter)empFilter.value='';
    if(priorityFilter)priorityFilter.value='';
    if(searchFilter)searchFilter.value='';
  }
  renderTaskBoard();
  toast(`Task ${existing?'updated':'added'}`,'ok');
}

async function deleteTaskFromModal(){
  const id=document.getElementById('task-edit-id')?.value;
  if(!id)return;
  if(await deleteTaskDirect(id))hideM('m-task');
}

async function deleteTaskDirect(id){
  const t=_taskListCache.find(x=>x.id===id);
  if(!t)return false;
  if(!(await appConfirm({title:'Delete Task',message:`Delete task "${t.title||'this task'}"?`,okText:'Delete'})))return false;
  try{
    await deleteServer('tasks',{id},{throwOnError:true});
  }catch(e){
    toast(`Could not delete task: ${e.serverDetail||e.message}`,'err');
    return false;
  }
  _taskListCache=_taskListCache.filter(x=>x.id!==id);
  renderTaskBoard();
  toast('Task deleted','ok');
  return true;
}

function _taskTableRowHtml(t){
  const priorityCls=t.priority==='High'?'b-r':t.priority==='Low'?'b-g':'b-a';
  const overdue=t.due_date&&t.status!=='done'&&t.due_date<_taskLocalToday();
  const normStatus=_normalizeTaskStatus(t.status);
  const statusCls=normStatus==='done'?'b-g':normStatus==='progress'?'b-b':'b-gray';
  const progress=t.status==='done'?100:(t.progress||0);
  return `<tr>
    <td style="font-weight:600">${escapeHtml(t.assigned_to_name||'Unassigned')}</td>
    <td style="color:var(--text3);font-size:12px">${escapeHtml(t.department||'—')}</td>
    <td><span style="display:inline-block;width:9px;height:9px;border-radius:50%;background:${escapeHtml(t.color||TASK_COLORS[0])};margin-right:7px;vertical-align:middle"></span>${escapeHtml(t.title)}</td>
    <td><span class="b ${priorityCls}">${escapeHtml(t.priority||'Medium')}</span></td>
    <td class="mono"${overdue?' style="color:var(--red)"':''}>${escapeHtml(t.due_date||'—')}</td>
    <td>${escapeHtml(TASK_REPEAT_LABEL[t.repeat||'none']||'—')}</td>
    <td><span class="b ${statusCls}">${escapeHtml(TASK_STATUS_LABEL[normStatus])}</span></td>
    <td style="min-width:70px"><div class="task-progress-bar" title="${progress}% complete"><div class="task-progress-fill" style="width:${progress}%"></div></div></td>
    <td style="white-space:nowrap"><button class="icon-btn edit" title="Edit" onclick="showTaskModal('${escapeHtml(t.id)}')">${editIconSvg()}</button> <button class="icon-btn danger" title="Delete" onclick="deleteTaskDirect('${escapeHtml(t.id)}')">${deleteIconSvg()}</button></td>
  </tr>`;
}

function renderTaskBoard(){
  const deptFilter=document.getElementById('task-department-filter')?.value||'';
  const empFilter=document.getElementById('task-filter-employee')?.value||'';
  const priorityFilter=document.getElementById('task-filter-priority')?.value||'';
  const search=(document.getElementById('task-filter-search')?.value||'').trim().toLowerCase();
  const filtered=_taskListCache.filter(t=>{
    // A saved task with no assigned_to yet used to be hidden from this
    // table entirely (a "template only" state, reusable from the "+
    // Assign Task" modal and "Load From Previous Task") -- but that made
    // a just-added task look like it silently vanished. It now lists
    // here too (shown as "Unassigned" in _taskTableRowHtml) so nothing
    // saved from + Add Task disappears from view.
    if(deptFilter&&t.department!==deptFilter)return false;
    if(empFilter&&t.assigned_to!==empFilter)return false;
    if(priorityFilter&&t.priority!==priorityFilter)return false;
    if(search&&!(t.title||'').toLowerCase().includes(search))return false;
    return true;
  });
  const tableBody=document.getElementById('task-table-tbody');
  if(tableBody){
    const rows=[...filtered].sort((a,b)=>(a.due_date||'9999').localeCompare(b.due_date||'9999'));
    tableBody.innerHTML=rows.length?rows.map(_taskTableRowHtml).join(''):'<tr><td colspan="9" style="color:var(--text3);text-align:center;padding:24px">No tasks</td></tr>';
  }
}

function validateWPS(){
  const status=document.getElementById('wps-status');
  const results=document.getElementById('wps-results');
  const rows=getPayrollRows();
  const exceptions=rows.filter(row=>row.dataset.wps!=='ok').length;
  if(status){status.className=exceptions?'b b-a':'b b-g';status.textContent=exceptions?exceptions+' exception(s)':'Validated';}
  if(results){
    const lines=rows.map(row=>{
      const info=getPayrollRowInfo(row);
      const ok=row.dataset.wps==='ok';
      return `<div><span style="color:var(--${ok?'green':'amber'})">${ok?'✓':'⚠'}</span> ${escapeHtml(info.name)} — ${ok?'Ready':'Missing bank/IBAN'}</div>`;
    });
    lines.push(`<div style="margin-top:6px;color:var(--${exceptions?'amber':'green'})">Total net pay: ${money(rows.reduce((s,r)=>s+getPayrollRowInfo(r).net,0))}</div>`);
    results.innerHTML=lines.join('');
  }
  toast(exceptions?'WPS validation: '+exceptions+' exception(s)':'WPS validation passed ✓',exceptions?'warn':'ok');
  renderSifPreview(rows);
  return exceptions===0;
}

// Mirrors the SCR record fields generateSIF() actually writes to the file,
// so what the user previews here matches what gets downloaded.
function renderSifPreview(rows){
  const tbody=document.getElementById('sif-preview-tbody');
  if(!tbody)return;
  if(!rows.length){emptyTableMessage(tbody,'No payroll rows — run payroll first.');return;}
  const period=document.getElementById('pay-period')?.value||document.getElementById('wps-salary-month')?.value||'';
  const daysWorked=_sifDaysInPeriod(period);
  tbody.innerHTML=rows.map(row=>{
    const info=getPayrollRowInfo(row);
    const ok=row.dataset.wps==='ok';
    const {empId,iban,bank}=_sifEmployeeRecord(row);
    const missing=' style="color:var(--amber)"';
    return `<tr><td>SCR</td><td class="mono">${escapeHtml(empId)}</td><td${ok?'':missing}>${ok?escapeHtml(bank):'Missing'}</td><td class="mono"${ok?'':missing}>${ok?escapeHtml(iban):'Missing'}</td><td class="mono">${info.basic.toFixed(2)}</td><td class="mono">${(info.allow+info.ot).toFixed(2)}</td><td class="mono">${daysWorked}</td><td class="mono">${info.net.toFixed(2)}</td></tr>`;
  }).join('');
}

// Real calendar days in a "YYYY-MM" period (28-31, not a flat 30 every
// month) — used as the SIF "days worked" field when there's no per-employee
// unpaid-leave adjustment to apply. new Date(year, month, 0) rolls back to
// the last day of the PREVIOUS month when month is 1-indexed like this,
// which is exactly the last day of the target month.
function _sifDaysInPeriod(period){
  const m=/^(\d{4})-(\d{2})$/.exec(period||'');
  if(!m)return 30;
  return new Date(Number(m[1]),Number(m[2]),0).getDate();
}

// Looks up the real employee record backing a #payroll-tbody row, by the
// employee id both tables already carry in dataset.employeeId (set by
// renderPayrollRunRow()/renderPayrollEmployeeRecord()) — previously matched
// by `r.textContent.includes(info.name)`, a plain substring search, so
// "Ali" matched the record for "Ali Hassan" and salary could be transferred
// to the wrong bank account entirely.
function _sifEmployeeRecord(row){
  const realEmployeeId=row.dataset.employeeId||'';
  const emp=realEmployeeId&&document.querySelector(`#payroll-employee-tbody tr[data-employee-id="${CSS.escape(realEmployeeId)}"]`);
  return {
    // Real Labour Card / MOL number when captured, falling back to the
    // real (stable) employee id — never a row-position index, which
    // changed an employee's "id" between two consecutive SIF files
    // whenever the table was re-sorted or re-rendered.
    empId:emp?.dataset.laborCard||realEmployeeId||'',
    // Full, untruncated values — the visible bankText cell intentionally
    // truncates the IBAN for display, so reading it back out of the DOM
    // (as this used to, via the row's first .mono cell — which was
    // actually the SALARY column, not IBAN at all) produced either the
    // wrong number or a half-IBAN no bank could ever accept.
    iban:emp?.dataset.iban||'',
    bank:emp?.dataset.bank||'',
  };
}

async function generateSIF(){
  const valid=validateWPS();
  const molId=(document.getElementById('wps-mol-id')?.value||'').trim();
  if(!molId){toast('Enter the employer MOL ID before generating the SIF','warn');return;}
  const fileSeq=(document.getElementById('wps-file-seq')?.value||'SIF-001').trim();
  const payDate=document.getElementById('pay-date')?.value||'';
  const period=document.getElementById('pay-period')?.value||'';
  const yearMonth=payrollPeriodToYearMonth(period);
  if(!yearMonth){toast('Select a valid payroll period first','warn');return;}
  // The bank file comes from the stored payroll run, never from editable grid cells.
  let run=null;
  try{run=await _payrollRunForPeriod(yearMonth);}catch(err){toast(err.message||'Could not load payroll runs','err');return;}
  if(!run||run.status!=='approved'){toast('Approve payroll for this period first — the SIF is generated from the approved run','warn');return;}
  try{
    const qs=new URLSearchParams({mol_id:molId,file_seq:fileSeq,pay_date:payDate});
    const response=await authenticatedFetch(`${apiBaseUrl()}/payroll/runs/${run.id}/sif?${qs}`,{method:'GET'});
    if(!response.ok){let d='';try{d=(await response.json()).detail||'';}catch{}throw new Error(d||`Request failed (${response.status})`);}
    const blob=await response.blob();
    const a=document.createElement('a');
    a.href=URL.createObjectURL(blob);
    a.download=`${fileSeq}.sif`;
    a.click();
    URL.revokeObjectURL(a.href);
  }catch(err){toast(`SIF download failed: ${err.message}`,'err');return;}
  audit('Generated WPS SIF file',fileSeq,'Downloaded');
  toast(valid?'SIF file downloaded ✓':'SIF downloaded (employees without an IBAN are excluded)','ok');
}

function getPayrollRowInfo(row){
  const nameEl=row.querySelector('.pay-emp-name');
  const name=(nameEl?.childNodes[0]?.textContent?.trim())||nameEl?.textContent?.trim()||'Employee';
  const basic=parseMoneyInput(row.querySelector('.pay-basic'));
  const allow=parseMoneyInput(row.querySelector('.pay-allow'));
  const ot=parseMoneyInput(row.querySelector('.pay-ot'));
  const ded=parseMoneyInput(row.querySelector('.pay-ded'));
  return {name,basic,allow,ot,ded,net:basic+allow+ot-ded};
}

function renderPayslipPreview(info){
  const body=document.getElementById('payslip-body');
  if(!body)return;
  const pc=document.getElementById('payslip-company'),pp=document.getElementById('payslip-period');
  if(pc)pc.textContent=(typeof currentCompany!=='undefined'&&currentCompany?.name)||'Payslip';
  if(pp)pp.textContent=`${document.getElementById('pay-period')?.value||''} Payslip`.trim();
  body.innerHTML=`
    <div class="flx-b"><span>Employee</span><strong style="color:var(--text)">${escapeHtml(info.name)}</strong></div>
    <div class="flx-b"><span>Total Salary</span><span class="mono">${money(info.basic)}</span></div>
    <div class="flx-b"><span>Allowances</span><span class="mono">${money(info.allow)}</span></div>
    <div class="flx-b"><span>Overtime / Variable Pay</span><span class="mono">${money(info.ot)}</span></div>
    <div class="flx-b"><span>Deductions</span><span class="mono" style="color:var(--red)">${money(info.ded)}</span></div>
    <div class="divider"></div>
    <div class="flx-b"><strong style="color:var(--text)">Net Pay</strong><strong class="mono" style="color:var(--green)">${money(info.net)}</strong></div>`;
}

function previewPayslip(btn){
  const row=btn.closest('tr');
  if(!row)return;
  const info=getPayrollRowInfo(row);
  renderPayslipPreview(info);
  const tab=document.querySelector('#page-payroll .tab:nth-child(5)');
  if(tab)stab(tab,'pay-payslips');
  toast('Payslip preview opened for '+info.name,'info');
}

function previewStaticPayslip(name,net){
  const numeric=parseFloat(String(net).replace(/,/g,''))||0;
  renderPayslipPreview({name,basic:numeric*.78,allow:numeric*.22,ot:0,ded:0,net:numeric});
}

function publishPayslips(){
  // Was claiming "published to employee email and mobile app" — this app
  // has no email/push-notification delivery pipeline for payslips at all,
  // so that never actually happened; the only real effect was writing a
  // marker record nothing else reads. Real payslip generation is the
  // separate Approve Payroll -> /payroll/generate flow, which does work
  // and does reach an employee's ESS payslip view. Honest wording until an
  // actual delivery mechanism exists, rather than a fabricated success claim.
  const period=document.getElementById('pay-period')?.value||'';
  saveServer('payrollRuns',{id:`PUB-${Date.now()}`,period,status:'Published',published_at:new Date().toISOString()});
  toast('Payroll run marked as published — payslips are generated via Approve Payroll','info');
  audit('Marked payroll run as published',period,'Published');
}

function postPayrollJournal(){
  recalcPayroll();
  const ref='PAY-JE-'+new Date().toISOString().slice(0,10).replace(/-/g,'');
  const date=new Date().toISOString().split('T')[0];
  const gross=parseAmount(document.getElementById('pay-je-gross')?.textContent);
  const deductions=parseAmount(document.getElementById('pay-je-ded')?.textContent);
  const net=parseAmount(document.getElementById('pay-je-net')?.textContent);
  postLedgerLine({date,ref,description:'Payroll gross salary expense',debit:gross,credit:0,account:'Operating Expenses (5000)'});
  if(deductions)postLedgerLine({date,ref,description:'Payroll deductions payable',debit:0,credit:deductions,account:'Accounts Payable (2000)'});
  postLedgerLine({date,ref,description:'Net payroll payable',debit:0,credit:net,account:'Accounts Payable (2000)'});
  filterLedger();
  toast('Payroll journal posted to accounting ?','ok');
  audit('Posted payroll journal','Accounting','Posted');
}

function calcGratuity(){
  const basic=parseMoneyInput(document.getElementById('eos-basic'));
  const years=parseFloat(document.getElementById('eos-years')?.value)||0;
  const months=parseFloat(document.getElementById('eos-months')?.value)||0;
  const contractType=document.getElementById('eos-contract')?.value||'unlimited';
  const reason=document.getElementById('eos-reason')?.value||'dismissal';
  const serviceYears=years+(months/12);

  // UAE Labour Law (Federal Decree-Law No.33 of 2021)
  // Gratuity = 21 days/year for first 5 yrs + 30 days/year after 5 yrs
  // Resignation reduction for unlimited contract
  let multiplier=1;
  if(reason==='resignation'&&contractType==='unlimited'){
    if(serviceYears<1){multiplier=0;}
    else if(serviceYears<3){multiplier=1/3;}
    else if(serviceYears<5){multiplier=2/3;}
    // 5+ years = full gratuity even on resignation
  }
  if(serviceYears<1){multiplier=0;}

  const daily=basic/30;
  const firstFive=Math.min(serviceYears,5)*21;
  const aboveFive=Math.max(serviceYears-5,0)*30;
  const eligibleDays=firstFive+aboveFive;
  const raw=daily*eligibleDays*multiplier;
  const cap=basic*24; // 2-year cap
  const total=Math.min(raw,cap);

  const dailyEl=document.getElementById('eos-daily');
  const daysEl=document.getElementById('eos-days');
  const totalEl=document.getElementById('eos-total');
  const noteEl=document.getElementById('eos-note');
  if(dailyEl)dailyEl.textContent=money(daily);
  if(daysEl)daysEl.textContent=eligibleDays.toFixed(2);
  if(totalEl)totalEl.textContent=money(total);
  if(noteEl){
    const notes=[];
    if(serviceYears<1)notes.push('Less than 1 year — no gratuity entitlement');
    else if(reason==='resignation'&&contractType==='unlimited'&&serviceYears<5)notes.push(`Resignation before 5 years: ${Math.round(multiplier*100)}% of full gratuity`);
    if(raw>cap)notes.push('Capped at 2 years\' total salary ('+money(cap)+')');
    if(!notes.length&&multiplier===1)notes.push('Full gratuity entitlement under UAE Labour Law');
    noteEl.textContent=notes.join(' · ');
  }
}

// ══════════════════════════════════════════════════════════════════════════════
// PERIOD LOCKING
// ══════════════════════════════════════════════════════════════════════════════
const _lockedPeriods=new Set(); // 'YYYY-MM' strings

function isPeriodLocked(dateStr){
  if(!dateStr)return false;
  return _lockedPeriods.has(String(dateStr).slice(0,7));
}

function togglePeriodLock(period){
  if(_lockedPeriods.has(period)){
    _lockedPeriods.delete(period);
    debouncedSaveServer('lockedPeriods',{id:period,locked:false,updated:new Date().toISOString()});
    toast(`Period ${period} unlocked`,'ok');
  }else{
    _lockedPeriods.add(period);
    debouncedSaveServer('lockedPeriods',{id:period,locked:true,updated:new Date().toISOString()});
    toast(`Period ${period} locked ✓`,'ok');
    audit('Locked accounting period',period,'Locked');
  }
  renderPeriodLockPanel();
}

function renderPeriodLockPanel(){
  const wrap=document.getElementById('period-lock-wrap');
  if(!wrap)return;
  const now=new Date();
  const months=Array.from({length:12},(_,i)=>{
    const idx=now.getFullYear()*12+now.getMonth()-6+i;
    return `${Math.floor(idx/12)}-${String(idx%12+1).padStart(2,'0')}`;
  });
  wrap.innerHTML=months.map(m=>{
    const locked=_lockedPeriods.has(m);
    const label=new Date(m+'-15T12:00:00Z').toLocaleString('en-AE',{month:'short',year:'numeric',timeZone:'UTC'});
    return `<div style="display:flex;align-items:center;justify-content:space-between;padding:8px 0;border-bottom:1px solid var(--border)">
      <span>${label} <span class="b ${locked?'b-r':'b-g'}" style="margin-left:8px">${locked?'Locked':'Open'}</span></span>
      <button class="btn ${locked?'btn-g':'btn-r'} btn-sm" onclick="togglePeriodLock('${m}')">${locked?'Unlock':'Lock'}</button>
    </div>`;
  }).join('');
}

// ══════════════════════════════════════════════════════════════════════════════
// RECURRING JOURNAL ENTRIES
// ══════════════════════════════════════════════════════════════════════════════
let _recurringJournals=[]; // loaded from server

function loadRecurringJournals(data=[]){
  _recurringJournals=Array.isArray(data)?data:[];
  renderRecurringJournalList();
}

function saveRecurringJournal(){
  const desc=document.getElementById('rec-je-desc')?.value.trim();
  const debitAcc=document.getElementById('rec-je-debit')?.value.trim();
  const creditAcc=document.getElementById('rec-je-credit')?.value.trim();
  const amount=parseAmount(document.getElementById('rec-je-amount')?.value);
  const freq=document.getElementById('rec-je-freq')?.value||'monthly';
  const nextDate=document.getElementById('rec-je-next')?.value;
  if(!desc||!amount||!debitAcc||!creditAcc){toast('All fields are required','warn');return;}
  const record={id:'RJE-'+Date.now(),description:desc,debit_account:debitAcc,credit_account:creditAcc,amount,frequency:freq,next_date:nextDate||new Date().toISOString().split('T')[0],active:true,created:new Date().toISOString()};
  _recurringJournals.push(record);
  saveServer('recurringJournals',record);
  renderRecurringJournalList();
  ['rec-je-desc','rec-je-amount','rec-je-next'].forEach(id=>{const el=document.getElementById(id);if(el)el.value='';});
  toast('Recurring journal saved ✓','ok');
  audit('Added recurring journal',desc,'Created');
}

function renderRecurringJournalList(){
  const tbody=document.getElementById('recurring-je-tbody');
  if(!tbody)return;
  if(!_recurringJournals.length){tbody.innerHTML='<tr><td colspan="6" style="text-align:center;color:var(--muted)">No recurring journals set up.</td></tr>';return;}
  tbody.innerHTML=_recurringJournals.map(r=>`<tr>
    <td>${escapeHtml(r.description)}</td>
    <td class="mono">${escapeHtml(r.debit_account)}</td>
    <td class="mono">${escapeHtml(r.credit_account)}</td>
    <td class="mono">${formatAed(r.amount)}</td>
    <td><span class="b b-a">${escapeHtml(r.frequency)}</span></td>
    <td>${escapeHtml(r.next_date||'')}</td>
    <td><button class="btn btn-p btn-sm" onclick="postRecurringJournal('${r.id}')">Post Now</button>
        <button class="btn btn-g btn-sm" onclick="deleteRecurringJournal('${r.id}')">✕</button></td>
  </tr>`).join('');
}

function postRecurringJournal(id){
  const r=_recurringJournals.find(x=>x.id===id);
  if(!r)return;
  const date=new Date().toISOString().split('T')[0];
  const ref='RJE-'+date.replace(/-/g,'');
  postLedgerLine({date,ref,description:r.description,debit:r.amount,credit:0,account:r.debit_account});
  postLedgerLine({date,ref,description:r.description,debit:0,credit:r.amount,account:r.credit_account});
  filterLedger();
  // Advance next date
  const next=new Date(r.next_date||date);
  if(r.frequency==='monthly')next.setMonth(next.getMonth()+1);
  else if(r.frequency==='quarterly')next.setMonth(next.getMonth()+3);
  else if(r.frequency==='weekly')next.setDate(next.getDate()+7);
  r.next_date=next.toISOString().split('T')[0];
  saveServer('recurringJournals',r);
  renderRecurringJournalList();
  toast(`Posted: ${r.description}  ✓`,'ok');
  audit('Posted recurring journal',r.description,'Posted');
}

function deleteRecurringJournal(id){
  const idx=_recurringJournals.findIndex(x=>x.id===id);
  if(idx>=0){
    deleteServer('recurringJournals',{id});
    _recurringJournals.splice(idx,1);
    renderRecurringJournalList();
    toast('Recurring journal removed','ok');
  }
}

function checkDueRecurringJournals(){
  if(!_recurringJournals.length)return;
  const today=new Date().toISOString().split('T')[0];
  const due=_recurringJournals.filter(r=>r.active&&r.next_date&&r.next_date<=today);
  if(due.length){
    toast(`${due.length} recurring journal(s) due — check Accounting → Recurring`,'warn');
  }
}

