function triggerJsonDownload(obj,filename){
  const blob=new Blob([JSON.stringify(obj,null,2)],{type:'application/json'});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');
  a.href=url;a.download=filename;
  document.body.appendChild(a);a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

function triggerRawDownload(blob,filename){
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');
  a.href=url;a.download=filename;
  document.body.appendChild(a);a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

async function _loadSheetJs(){
  if(window.XLSX)return;
  // Try multiple CDNs in order
  const cdns=[
    'https://unpkg.com/xlsx@0.18.5/dist/xlsx.full.min.js',
    'https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js',
  ];
  for(const src of cdns){
    try{
      await new Promise((resolve,reject)=>{
        const s=document.createElement('script');
        s.src=src;
        s.onload=resolve;
        s.onerror=reject;
        document.head.appendChild(s);
      });
      if(window.XLSX)return;
    }catch{/* try next */}
  }
  throw new Error('Could not load Excel library — check internet connection');
}

function _backupModuleFilter(){
  return{
    inv:document.getElementById('bk-inv')?.checked!==false,
    pur:document.getElementById('bk-pur')?.checked!==false,
    jnl:document.getElementById('bk-jnl')?.checked!==false,
    hr:document.getElementById('bk-hr')?.checked!==false,
    audit:document.getElementById('bk-audit')?.checked!==false
  };
}

function _applyModuleFilter(data){
  const include=_backupModuleFilter();
  // "_db" suffixed keys (app_data.py's export_all_data()) are the real
  // relational tables (Invoice, Account, GeneralLedgerEntry, Employee,
  // PayrollRun/Item, SourceTransaction) that the AppDataRecord collections
  // above them don't cover at all — grouped under the same category
  // toggles as their legacy-collection counterparts.
  const invCols=['salesInvoices','quotations','salesCategories','salesUnits','customers','creditControl','invoices_db','invoice_lines_db'];
  const purCols=['purchaseRecords','purchaseDocuments','bills','vendors','payments','receipts'];
  const jnlCols=['accounts','ledger','journalDrafts','bankAccounts','bankTransactions','vatReturns','corporateTax','fixedAssets','accrualsPrepayments','costCenters','budgets','cashFlowForecasts','consolidation','relatedPartyTransactions','accounts_db','general_ledger_db','source_transactions_db'];
  // Previously missed most of HRMS: leave requests and attendance history
  // are real Tier 1 tables (leave_requests_db/attendance_details_db, added
  // to export_all_data()/export_db_dump() alongside this) that a "Payroll &
  // HR: Employee records and payroll data" backup should obviously include,
  // and tasks/overtime/loans/salary-advances/corrections/recruitment/
  // hr_settings were never assigned to ANY category at all — meaning they
  // silently downloaded regardless of whether "Payroll & HR" was checked or
  // not, the opposite of what an unchecked toggle promises.
  const hrCols=['employees','rotaShifts','rotaAssignments','rotaSwaps','rotaApprovals','rotaDrafts','tasks','overtimeRequests','employeeLoans','salaryAdvances','attendanceCorrections','jobRequisitions','candidates','payrollAdjustments','hr_settings','employees_db','payroll_runs_db','payroll_items_db','leave_requests_db','attendance_details_db'];
  const filtered={};
  Object.keys(data).forEach(k=>{
    if(k==='audit'&&!include.audit)return;
    if(k==='users')return;
    if(invCols.includes(k)&&!include.inv)return;
    if(purCols.includes(k)&&!include.pur)return;
    if(jnlCols.includes(k)&&!include.jnl)return;
    if(hrCols.includes(k)&&!include.hr)return;
    filtered[k]=data[k];
  });
  return filtered;
}

async function downloadExcelBackup(){
  toast('Preparing Excel…','info');
  try{
    await _loadSheetJs();
    const resp=await authenticatedFetch(`${apiBaseUrl()}/app-data/export`);
    if(!resp.ok)throw new Error('Export failed');
    const r=await resp.json();
    const data=_applyModuleFilter(r.data||{});

    const XLSX=window.XLSX;
    const wb=XLSX.utils.book_new();

    // Friendly sheet name → collection key(s)
    const sheetMap=[
      ['Invoices',      ['salesInvoices']],
      ['Customers',     ['customers']],
      ['Quotations',    ['quotations']],
      ['Bills',         ['bills']],
      ['Vendors',       ['vendors']],
      ['Payments',      ['payments','receipts']],
      ['Accounts',      ['accounts']],
      ['Employees',     ['employees']],
      ['Products',      ['products']],
      ['Bank Accounts', ['bankAccounts']],
      ['VAT Returns',   ['vatReturns']],
      ['Expenses',      ['expenses']],
      ['Audit Log',     ['audit']],
      // Real relational tables (export_all_data(), app_data.py) — kept as
      // their own sheets rather than merged into the legacy-collection
      // sheets above (e.g. "Invoices"/"Accounts"), since their row shapes
      // don't match and mixing them would produce a sheet with
      // inconsistent columns.
      ['Invoices (Posted)',    ['invoices_db']],
      ['Invoice Lines',        ['invoice_lines_db']],
      ['Chart of Accounts',    ['accounts_db']],
      ['General Ledger',       ['general_ledger_db']],
      ['Source Transactions',  ['source_transactions_db']],
      ['Employees (HR)',       ['employees_db']],
      ['Payroll Runs',         ['payroll_runs_db']],
      ['Payroll Items',        ['payroll_items_db']],
      ['Leave Requests',       ['leave_requests_db']],
      ['Attendance',           ['attendance_details_db']],
      // Legacy Tier 2 HR collections (never had their own sheet before —
      // they were in the export payload but just silently dropped here).
      ['Tasks',                ['tasks']],
      ['Overtime Requests',    ['overtimeRequests']],
      ['Employee Loans',       ['employeeLoans']],
      ['Salary Advances',      ['salaryAdvances']],
      ['Attendance Corrections',['attendanceCorrections']],
      ['Rota',                 ['rotaAssignments']],
    ];

    sheetMap.forEach(([sheetName,keys])=>{
      const rows=keys.flatMap(k=>Array.isArray(data[k])?data[k]:[]);
      if(!rows.length)return;
      // Flatten and sanitize — use aoa_to_sheet for reliable primitive handling
      const safe=v=>{
        if(v===null||v===undefined)return'';
        if(typeof v==='object')return JSON.stringify(v);
        if(typeof v==='number')return isFinite(v)?v:'';
        return String(v);
      };
      const flat=rows.map(row=>{
        const out={};
        Object.entries(row).forEach(([k,v])=>{
          if(v!==null&&v!==undefined&&typeof v==='object'&&!Array.isArray(v)){
            Object.entries(v).forEach(([ik,iv])=>out[`${k}.${ik}`]=safe(iv));
          }else{
            out[k]=safe(v);
          }
        });
        return out;
      });
      const flatHeaders=flat.length?Object.keys(flat[0]):[];
      const aoa=[flatHeaders,...flat.map(r=>flatHeaders.map(h=>safe(r[h])))];
      const ws=XLSX.utils.aoa_to_sheet(aoa);
      ws['!cols']=flatHeaders.map(c=>({wch:Math.min(40,Math.max(10,c.length+2))}));
      XLSX.utils.book_append_sheet(wb,ws,sheetName.slice(0,31));
    });

    if(wb.SheetNames.length===0){toast('No data to export','err');return;}

    const ts=new Date().toISOString().slice(0,10);
    // Use write+blob instead of writeFile for reliable browser downloads
    const wbout=XLSX.write(wb,{bookType:'xlsx',type:'array'});
    const xlsxBlob=new Blob([wbout],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});
    triggerRawDownload(xlsxBlob,`taxflow-backup-${ts}.xlsx`);
    audit('Downloaded Excel backup','Backup','Complete');
    toast('Excel downloaded','ok');
  }catch(e){
    toast('Excel export failed: '+e.message,'err');
  }
}

